INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "苔藓植物的一种，扁平叶状，生长在阴湿的地面或石上。", "primary_collocate": null, "pronunciation": "dì qián", "ipa": "ti˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "地钱是苔藓植物，叶子扁平，贴着地面生长。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地钱常常生长在阴湿的地面或石头上。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学课上，老师给我们看了地钱的叶子。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地钱的叶子扁扁的，像一条绿色的带子。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地钱属于苔藓植物，没有真正的根。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在森林里的湿石头上能找到地钱。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地钱不开花，靠孢子繁殖。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种苔藓植物叫地钱，喜欢潮湿的环境。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，花盆边上长出了地钱。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用放大镜观察地钱的叶片。", "target_word": "地钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "丛", "label": "量词"}, {"form": "地錢", "label": "繁体"}], "register": "书面", "sense_fingerprint": "地钱：叶状体扁平、生长在阴湿处的苔藓植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 苔 (Zipf 3.52), 藓 (Zipf 3.05), 扁平 (Zipf 3.36), 贴着 (Zipf 3.34)']::text[], 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地钱", "is_correct": true, "explanation": "正确：地钱是苔藓植物，叶子扁平，贴着地面生长，与句意相符。"}, {"text": "松树", "is_correct": false, "explanation": "体貌：松树的叶子呈针状，与“叶子扁平”不符。"}, {"text": "竹子", "is_correct": false, "explanation": "语义：竹子是高大的木本植物，不属于苔藓植物。"}, {"text": "向日葵", "is_correct": false, "explanation": "语义：向日葵是高大的开花植物，叶子也不贴着地面生长。"}], "explanations": {"地钱": "正确：地钱是苔藓植物，叶子扁平，贴着地面生长，与句意相符。", "松树": "体貌：松树的叶子呈针状，与“叶子扁平”不符。", "竹子": "语义：竹子是高大的木本植物，不属于苔藓植物。", "向日葵": "语义：向日葵是高大的开花植物，叶子也不贴着地面生长。"}, "sentence_index": 0, "correct_answer": "地钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的地钱开得很艳。", "explanation": "这里应该用〈月季〉。地钱不开花，不能说“开得很艳”。"}, {"text": "妈妈把地钱的花摘下来，做成了一束干花。", "explanation": "这里应该用〈玫瑰〉。地钱不开花，没有可以摘下来做干花的花朵；只有开花的植物（如玫瑰）才能这样用。"}, {"text": "他坐在地钱上休息。", "explanation": "这里应该用〈石头〉。地钱太矮小、太薄，人不能坐在上面休息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地钱", "is_correct": true, "explanation": "正确：地钱不开花，靠孢子繁殖，与句意相符。"}, {"text": "玫瑰", "is_correct": false, "explanation": "语义：玫瑰会开花，与“不开花”矛盾。"}, {"text": "小麦", "is_correct": false, "explanation": "语义：小麦会开花，靠种子繁殖，与“不开花，靠孢子繁殖”不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“开花”和“繁殖”只用于生物，不能说石头开花或繁殖。"}], "explanations": {"地钱": "正确：地钱不开花，靠孢子繁殖，与句意相符。", "玫瑰": "语义：玫瑰会开花，与“不开花”矛盾。", "小麦": "语义：小麦会开花，靠种子繁殖，与“不开花，靠孢子繁殖”不符。", "石头": "搭配：“开花”和“繁殖”只用于生物，不能说石头开花或繁殖。"}, "sentence_index": 6, "correct_answer": "地钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池塘边长着一颗地钱。", "explanation": "这里应该用〈片〉。“颗”多用于圆粒状的东西，地钱是扁平的叶状体，不能用“颗”。"}, {"text": "墙缝里长着一粒地钱。", "explanation": "这里应该用〈丛〉。“粒”用于颗粒状的东西，地钱不是颗粒。"}, {"text": "庭院里长着一朵地钱。", "explanation": "这里应该用〈丛〉。“朵”用于花，而地钱不开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阴湿的石缝里长着一片绿绿地钱。", "corrected_sentence": "阴湿的石缝里长着一片绿绿的地钱。", "error_description": "“绿绿”是重叠形容词，修饰名词时后面要加“的”，应说“绿绿的地钱”；漏掉“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "岩石缝里长着一个地钱。", "corrected_sentence": "岩石缝里长着一丛地钱。", "error_description": "“地钱”多成丛或成片生长，应用量词“丛”或“片”，不能用通用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
