INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93137, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就此是到这里为止，不再往下了。", "primary_collocate": null, "pronunciation": "jiù cǐ", "ipa": "tɕjoʊ̯˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们就此告别，明天再见。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就此结束，别再说了。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的故事就此完了。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛就此结束，谢谢大家。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的课就此打住吧。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的谈话就此停下。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题就此不谈了。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧账就此了结，谁也别再提。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好吧，今天就此散会。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人就此分手，不再联系。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "到这里为止，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就此", "is_correct": true, "explanation": "“就此”表示到此为止，与“告别”的结束语义相合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”须与否定或“从来如此”之类的语境连用，不能直接修饰“告别”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与句中“明天再见”的确定安排不合。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：“反复”表示重复，不能与“告别”这种一次性的动作搭配。"}], "explanations": {"就此": "“就此”表示到此为止，与“告别”的结束语义相合。", "从来": "搭配：“从来”须与否定或“从来如此”之类的语境连用，不能直接修饰“告别”。", "偶尔": "语义：“偶尔”表示不常发生，与句中“明天再见”的确定安排不合。", "反复": "搭配：“反复”表示重复，不能与“告别”这种一次性的动作搭配。"}, "sentence_index": 0, "correct_answer": "就此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛就此拖延了一个小时，大家都很着急。", "explanation": "这里应该用〈推迟〉。就此表示到此为止，与“拖延了一个小时”所说的继续拖下去相矛盾。"}, {"text": "这次讨论就此又持续了两天，大家都累了。", "explanation": "这里应该用〈结束〉。就此表示到此为止，与“又持续了两天”的延续语义相矛盾。"}, {"text": "这次讨论就此进入了新阶段，大家都很期待。", "explanation": "这里应该用〈继续〉。就此表示到此为止，与“进入新阶段”所说的继续推进相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就此", "is_correct": true, "explanation": "“就此”表示到此为止，与“不谈了”的终止语义相合。"}, {"text": "重新", "is_correct": false, "explanation": "语义：“重新”表示再次开始，与“不谈了”的停止语义相反。"}, {"text": "时常", "is_correct": false, "explanation": "语义：“时常”表示经常，与“不谈了”的终止语义不合。"}, {"text": "尽快", "is_correct": false, "explanation": "搭配：“尽快”表示赶快，不能与“不谈了”这种停止式的表述搭配。"}], "explanations": {"就此": "“就此”表示到此为止，与“不谈了”的终止语义相合。", "重新": "语义：“重新”表示再次开始，与“不谈了”的停止语义相反。", "时常": "语义：“时常”表示经常，与“不谈了”的终止语义不合。", "尽快": "搭配：“尽快”表示赶快，不能与“不谈了”这种停止式的表述搭配。"}, "sentence_index": 6, "correct_answer": "就此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个人就此分手，却又在第二天一起出发。", "explanation": "这里应该用〈从此〉。就此表示到此为止，与“又在第二天一起出发”所说的继续相矛盾。"}, {"text": "这件事就此没完，他们要继续争吵。", "explanation": "这里应该用〈结束〉。就此表示到此为止，与“没完”所说的不结束相矛盾。"}, {"text": "两个人就此分开，却约定明天再见面。", "explanation": "就此表示到此为止、不再往下，与“约定明天再见面”所说的继续相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次谈话就此的结束，大家散了吧。", "corrected_sentence": "这次谈话就此结束，大家散了吧。", "error_description": "“就此”是副词，后面应直接接动词，不能加“的”；应写作“就此结束”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人就此的断了来往，互不联系。", "corrected_sentence": "两个人就此断了来往，互不联系。", "error_description": "“就此”是副词，后面应直接接动词，不能加“的”；应写作“就此断了来往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
