INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93138, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就在此时或此地；趁此机会。", "primary_collocate": null, "pronunciation": "jiù cǐ", "ipa": "tɕjoʊ̯˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "会议就此开始，请大家安静。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信号就此中断，电话里再也没有声音。", "target_word": "就此", "complexity_tier": "T3", "furigana": "xìnhào jiù cǐ zhōngduàn, diànhuà lǐ zài yě méiyǒu shēngyīn.", "sentence_source": "generated"}, {"text": "他刚说完这句话，就此转身走出了房间。", "target_word": "就此", "complexity_tier": "T3", "furigana": "tā gāng shuō wán zhè jù huà, jiù cǐ zhuǎnshēn zǒuchūle fángjiān.", "sentence_source": "generated"}, {"text": "车子就此停下，我们下了车。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛就此开始，观众都站了起来。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会刚开始，记者就此围住了发言人。", "target_word": "就此", "complexity_tier": "T3", "furigana": "fābùhuì gāng kāishǐ, jìzhě jiù cǐ wéizhùle fāyánrén.", "sentence_source": "generated"}, {"text": "灯光就此熄灭，剧场陷入一片黑暗。", "target_word": "就此", "complexity_tier": "T3", "furigana": "dēngguāng jiù cǐ xīmiè, jùchǎng xiànrù yí piàn hēi''àn.", "sentence_source": "generated"}, {"text": "我们就此出发，天黑前能到。", "target_word": "就此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟声就此响起，人们纷纷涌向广场。", "target_word": "就此", "complexity_tier": "T3", "furigana": "zhōngshēng jiù cǐ xiǎngqǐ, rénmen fēnfēn yǒngxiàng guǎngchǎng.", "sentence_source": "generated"}, {"text": "话音未落，他就此消失在人群之中。", "target_word": "就此", "complexity_tier": "T3", "furigana": "huàyīn wèiluò, tā jiù cǐ xiāoshī zài rénqún zhī zhōng.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "就在这时或这里；趁着这个机会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就此", "is_correct": true, "explanation": "“就此”表示就在此时开始，与“会议开始”的语境相合。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示持续不变，与会议刚开始的语境不合。"}, {"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示推测，句子陈述的是确定的开始，语义不合。"}, {"text": "向来", "is_correct": false, "explanation": "搭配：“向来”表示一贯如此，不能与表示当下开始的“开始”搭配。"}], "explanations": {"就此": "“就此”表示就在此时开始，与“会议开始”的语境相合。", "仍然": "语义：“仍然”表示持续不变，与会议刚开始的语境不合。", "也许": "语义：“也许”表示推测，句子陈述的是确定的开始，语义不合。", "向来": "搭配：“向来”表示一贯如此，不能与表示当下开始的“开始”搭配。"}, "sentence_index": 0, "correct_answer": "就此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天就在此时出发，天黑前能到。", "explanation": "这里应该用〈届时〉。“就在此时”指当下，与“明天”这样的未来时间相矛盾。"}, {"text": "他刚说完话，隔了半个小时才就在此时动身。", "explanation": "这里应该用〈随即〉。“就在此时”指当下，与“隔了半个小时才”的延后语义相矛盾。"}, {"text": "车子就此慢慢停下了三天，我们才下车。", "explanation": "这里应该用〈立即〉。就此表示就在此时，与“慢慢停下了三天”的持续语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就此", "is_correct": true, "explanation": "“就此”表示就在此时，与“灯光熄灭”的语境相合。"}, {"text": "未必", "is_correct": false, "explanation": "语义：“未必”表示不一定，与后句“陷入一片黑暗”的确定结果相矛盾。"}, {"text": "不再", "is_correct": false, "explanation": "语义：“不再”表示不会再发生，与“灯光熄灭”的叙述相矛盾。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸，句中“陷入一片黑暗”是不幸的结果，语义相反。"}], "explanations": {"就此": "“就此”表示就在此时，与“灯光熄灭”的语境相合。", "未必": "语义：“未必”表示不一定，与后句“陷入一片黑暗”的确定结果相矛盾。", "不再": "语义：“不再”表示不会再发生，与“灯光熄灭”的叙述相矛盾。", "幸亏": "语义：“幸亏”表示庆幸，句中“陷入一片黑暗”是不幸的结果，语义相反。"}, "sentence_index": 6, "correct_answer": "就此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚进门，过了很久才就此又出去买东西。", "explanation": "这里应该用〈随即〉。就此表示就在此时，与“过了很久才”的延后语义相矛盾。"}, {"text": "雨下了整整一周，直到周末才就此停下。", "explanation": "这里应该用〈终于〉。就此表示就在此时，与“直到周末才”的延后语义相矛盾。"}, {"text": "我们初次见面后过了半年才就此逐渐熟悉起来，大家都很高兴。", "explanation": "这里应该用〈后来〉。就此表示就在此时，与“过了半年才”的延后语义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出就此的开始，请大家安静。", "corrected_sentence": "演出就此开始，请大家安静。", "error_description": "语法错误：“就此”是副词，后面应直接接动词，不能加“的”；应写作“演出就此开始”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯就此的停下，大家都愣住了。", "corrected_sentence": "电梯就此停下，大家都愣住了。", "error_description": "“就此”是副词，后面应直接接动词，不能加“的”；应写作“电梯就此停下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
