INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以工业生产为国民经济主体的国家。", "primary_collocate": null, "pronunciation": "gōng yè guó", "ipa": "kʊŋ˥ jɛ˥˩ kwɔ˧˥", "syllable_count": 3, "sentences": [{"text": "这个国家从农业国变成了工业国。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业国的经济靠工业生产。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业国的工业产品卖得很好。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，英国是最早的工业国。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业国的人大多住在城市。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究工业国的经济问题。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业国比农业国更需要能源。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工业国的钢铁很有名。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多工业国都在发展新技术。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书里介绍了几个工业国。", "target_word": "工业国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "国民经济以工业生产为主的国家，与农业国相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业国", "is_correct": true, "explanation": "正确：「工业国」指以工业生产为主的国家，与“从农业国变成了”的变化方向相符。"}, {"text": "大城市", "is_correct": false, "explanation": "语义：国家不能变成城市，前面的“农业国”与“大城市”无法对应。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“变成了”后应接同类的国家概念，“银行”不能与“农业国”相对。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆不是国家，句意无法成立。"}], "explanations": {"工业国": "正确：「工业国」指以工业生产为主的国家，与“从农业国变成了”的变化方向相符。", "大城市": "语义：国家不能变成城市，前面的“农业国”与“大城市”无法对应。", "银行": "搭配：“变成了”后应接同类的国家概念，“银行”不能与“农业国”相对。", "博物馆": "语义：博物馆不是国家，句意无法成立。"}, "sentence_index": 0, "correct_answer": "工业国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个园区是一个工业国。", "explanation": "这里应该用〈工业区〉。园区是地方，工业国指国家，不能用来指园区。"}, {"text": "这个工业国在城市的东边。", "explanation": "这里应该用〈工业园〉。工业国指国家，不能指位于城市东边的一片工业园。"}, {"text": "这座城市是重要的工业国。", "explanation": "这里应该用〈工业中心〉。城市是地方，工业国指国家，不能用来说城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业国", "is_correct": true, "explanation": "正确：「工业国」指以工业生产为主的国家，能源需求大，与“比农业国更需要能源”相符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是国家，无法与农业国比较能源需求。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠不是国家或社会，无法与农业国比较能源需求。"}, {"text": "大象", "is_correct": false, "explanation": "搭配：“需要能源”的主语应是国家或社会，“大象”不能与之搭配。"}], "explanations": {"工业国": "正确：「工业国」指以工业生产为主的国家，能源需求大，与“比农业国更需要能源”相符。", "花朵": "语义：花朵不是国家，无法与农业国比较能源需求。", "沙漠": "语义：沙漠不是国家或社会，无法与农业国比较能源需求。", "大象": "搭配：“需要能源”的主语应是国家或社会，“大象”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "工业国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在书里介绍了几本工业国。", "explanation": "这里应该用〈个〉。国家用量词“个”，“本”用于书籍，不能用于国家。"}, {"text": "她在书里介绍了几条工业国。", "explanation": "这里应该用〈个〉。“条”用于长条形的东西，不能用于国家。"}, {"text": "她在书里介绍了几辆工业国。", "explanation": "这里应该用〈个〉。“辆”用于车辆，不能用于国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英国是一座工业国。", "corrected_sentence": "英国是一个工业国。", "error_description": "错误：“工业国”的量词应为“个”，“座”多用于山、桥等大型建筑，不能用于国家。正确：“英国是一个工业国。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "德国是一台工业国。", "corrected_sentence": "德国是一个工业国。", "error_description": "错误：“工业国”的量词应为“个”，“台”用于机器、电器，不能用于国家。正确：“德国是一个工业国。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
