INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "珍贵的东西；对孩子的爱称。", "primary_collocate": null, "pronunciation": "bǎo bèi", "ipa": "pɑʊ˨˩˦ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "宝贝，天黑了，该睡觉了。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈笑着说：“宝贝，来吃饭吧。”", "target_word": "宝贝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多千年前的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝贝，别哭，妈妈在这儿。", "target_word": "宝贝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海底的箱子里藏着很多宝贝。", "target_word": "宝贝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山洞里找到了一件宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸叫小女儿“宝贝”，她就笑了。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画是这家博物馆最珍贵的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝贝，今天在学校开心吗？", "target_word": "宝贝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人拿出一件祖传的宝贝给我们看。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件宝贝", "label": "量词"}, {"form": "寶貝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "珍贵稀有的物品，或大人亲昵称呼孩子的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93158, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：对孩子的爱称，用于亲人对孩子的呼唤。"}, {"text": "百倍", "is_correct": false, "explanation": "bǎi（第三声）与 bǎo 韵母不同，意思是一百倍。"}, {"text": "保卫", "is_correct": false, "explanation": "wèi 与 bèi 声母不同，意思是保护、防卫。"}, {"text": "保费", "is_correct": false, "explanation": "fèi 与 bèi 声母不同，意思是保险费。"}, {"text": "报备", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是事先报告、备案。"}], "explanations": {"宝贝": "宝贝：对孩子的爱称，用于亲人对孩子的呼唤。", "百倍": "bǎi（第三声）与 bǎo 韵母不同，意思是一百倍。", "保卫": "wèi 与 bèi 声母不同，意思是保护、防卫。", "保费": "fèi 与 bèi 声母不同，意思是保险费。", "报备": "bào（第四声）与 bǎo（第三声）声调不同，意思是事先报告、备案。"}, "sentence_index": null, "correct_answer": "宝贝"}, "level_3": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：对孩子的爱称，用作呼语，与“该睡觉了”相合。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：天已经黑了，与“早晨”的时间矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能作呼语，与“天黑了，该睡觉了”所指的对象不符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“饭”一般不用作呼语，与“天黑了，该睡觉了”也不连贯。"}], "explanations": {"宝贝": "宝贝：对孩子的爱称，用作呼语，与“该睡觉了”相合。", "早晨": "语义：天已经黑了，与“早晨”的时间矛盾。", "书包": "语义：书包是物品，不能作呼语，与“天黑了，该睡觉了”所指的对象不符。", "饭": "搭配：“饭”一般不用作呼语，与“天黑了，该睡觉了”也不连贯。"}, "sentence_index": 0, "correct_answer": "宝贝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从柜子里拿出一张宝贝给我们看。", "explanation": "这里应该用〈件〉。宝贝指珍贵的物品，量词用“件”；“张”用于纸张、桌子等平面物品。"}, {"text": "您好，宝贝，请问车站在哪儿？", "explanation": "宝贝作爱称只用于亲近的孩子或亲人，对陌生人这样称呼不合适。"}, {"text": "博物馆里陈列着一位千年宝贝。", "explanation": "这里应该用〈件〉。位用于人，表示尊敬，不用来数珍贵的物品；宝贝指珍贵的物品，量词用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：对孩子的爱称，与“小女儿”相合。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能作称呼，与“小女儿”不相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能作称呼，与“小女儿”不相合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是物品，不能作称呼，与“小女儿”不相合。"}], "explanations": {"宝贝": "宝贝：对孩子的爱称，与“小女儿”相合。", "雨伞": "语义：雨伞是物品，不能作称呼，与“小女儿”不相合。", "桌子": "语义：桌子是物品，不能作称呼，与“小女儿”不相合。", "课本": "语义：课本是物品，不能作称呼，与“小女儿”不相合。"}, "sentence_index": 6, "correct_answer": "宝贝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人拿出一座宝贝给我们看。", "explanation": "这里应该用〈件〉。座用于山、桥、建筑等大型物体，宝贝指珍贵的物品，量词用“件”。"}, {"text": "老板，宝贝，这批货什么时候到？", "explanation": "宝贝作爱称只用于亲人或亲近的晚辈，对老板这样称呼不合适。"}, {"text": "他把一盏宝贝挂在了客厅里。", "explanation": "这里应该用〈件〉。盏用于灯具，宝贝指珍贵的物品，量词用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "博物馆里摆着一只宝贝。", "corrected_sentence": "博物馆里摆着一件宝贝。", "error_description": "“宝贝”指珍贵的物品，量词应用“件”。这里错在量词“只”，“只”多用于动物或成对的物品，不能用来数这类物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件宝贝们很珍贵，他们一直收着。", "corrected_sentence": "这件宝贝很珍贵，他们一直收着。", "error_description": "“宝贝们”是复数形式，而“这件”指单个物品，二者矛盾。这里错在多加了“们”，应去掉，改为“宝贝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
