INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后代是一个人以后的孩子和孙子。", "primary_collocate": null, "pronunciation": "hòu dài", "ipa": "xoʊ˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老人的后代都住在这个城市。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷希望后代都过得幸福。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是爷爷的后代,都姓王。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的后代有二十多人。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时,他的后代都回家看他。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有后代,一个人生活。", "target_word": "后代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的后代坐满了一张大桌子。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生把房子留给了后代。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的后代现在都在国外工作。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是这家人的后代吗?", "target_word": "后代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "子孙后代", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人自己的孩子和孙子等家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后代", "is_correct": true, "explanation": "后代指某人的子孙，老人的子孙都住在这个城市，符合语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外地来旅游的人，不会都住在这个城市，与“住在这个城市”矛盾。"}, {"text": "外国人", "is_correct": false, "explanation": "搭配：“外国人”指国籍，不能说成“老人的外国人”，与“后代”不搭。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“陌生人”指彼此不认识的人，不能被“老人的”领属。"}], "explanations": {"后代": "后代指某人的子孙，老人的子孙都住在这个城市，符合语境。", "游客": "语义：游客是外地来旅游的人，不会都住在这个城市，与“住在这个城市”矛盾。", "外国人": "搭配：“外国人”指国籍，不能说成“老人的外国人”，与“后代”不搭。", "陌生人": "搭配：“陌生人”指彼此不认识的人，不能被“老人的”领属。"}, "sentence_index": 0, "correct_answer": "后代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的后代，比我晚两年进公司。", "explanation": "这里应该用〈后辈〉。后代指自己的子孙，同事中比我晚进公司的人要用后辈。"}, {"text": "这辆公交车上坐着三个后代。", "explanation": "这里应该用〈乘客〉。后代指子孙，车上的人要说乘客。"}, {"text": "我们班的后代都很努力。", "explanation": "这里应该用〈同学〉。后代指子孙，班里的同学不能称后代，要说同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后代", "is_correct": true, "explanation": "后代指子孙，奶奶的子孙坐满一张大桌，符合语境。"}, {"text": "家畜", "is_correct": false, "explanation": "语义：家畜是饲养的动物，不能坐满餐桌。"}, {"text": "乘客", "is_correct": false, "explanation": "配价：“乘客”需要交通工具作补足，不能说“奶奶的乘客”。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆是器物，不会坐在桌边。"}], "explanations": {"后代": "后代指子孙，奶奶的子孙坐满一张大桌，符合语境。", "家畜": "语义：家畜是饲养的动物，不能坐满餐桌。", "乘客": "配价：“乘客”需要交通工具作补足，不能说“奶奶的乘客”。", "花盆": "语义：花盆是器物，不会坐在桌边。"}, "sentence_index": 6, "correct_answer": "后代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上有个后代在问路。", "explanation": "这里应该用〈后生〉。后代指子孙，路上不认识的年轻人要说后生。"}, {"text": "学校门口站着一个后代在维持秩序。", "explanation": "这里应该用〈保安〉。后代指子孙，负责维持秩序的人要说保安。"}, {"text": "今天有三个后代来买东西。", "explanation": "这里应该用〈顾客〉。后代指子孙，来买东西的人要说顾客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有三只后代在外地读书。", "corrected_sentence": "他有三个后代在外地读书。", "error_description": "“后代”指人，量词应用“个”，“只”多用于动物，应改为“三个后代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的一条后代在国外工作。", "corrected_sentence": "他的一个后代在国外工作。", "error_description": "“后代”指人，量词应用“个”，“条”用于细长的东西，应改为“一个后代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
