INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93165, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带大是从小照顾一个孩子，直到他长大。", "primary_collocate": null, "pronunciation": "dài dà", "ipa": "tai˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶一个人把我带大。", "target_word": "带大", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她独自把三个孩子带大了。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆把我带大，我很感谢她。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小没有妈妈，是姐姐带大的。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子是爷爷带大的。", "target_word": "带大", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她一边工作一边把儿子带大。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把孩子带大不容易。", "target_word": "带大", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸妈妈很忙，我是保姆带大的。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把弟弟带大后才结婚。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居阿姨帮忙把女儿带大。", "target_word": "带大", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "带大了", "label": "体标"}, {"form": "带大过", "label": "体标"}], "register": "口语", "sense_fingerprint": "带大：从小照看孩子到长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67a56d63-f4af-48ab-bef5-25a06a44575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93165, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带大", "is_correct": true, "explanation": "正确答案。带大：从小抚养孩子，直到他长大。"}, {"text": "太大", "is_correct": false, "explanation": "声母不同：tài 的 t 与 dài 的 d 不同，意思是“太大”（程度过高）。"}, {"text": "带到", "is_correct": false, "explanation": "韵母不同：dào 与 dà 的韵母不同（ao 与 a），意思是“带到某处”。"}, {"text": "代打", "is_correct": false, "explanation": "第二个音节声调不同：dǎ（第三声）与 dà（第四声）不同，意思是“替补击球”。"}], "explanations": {"带大": "正确答案。带大：从小抚养孩子，直到他长大。", "太大": "声母不同：tài 的 t 与 dài 的 d 不同，意思是“太大”（程度过高）。", "带到": "韵母不同：dào 与 dà 的韵母不同（ao 与 a），意思是“带到某处”。", "代打": "第二个音节声调不同：dǎ（第三声）与 dà（第四声）不同，意思是“替补击球”。"}, "sentence_index": null, "correct_answer": "带大"}, "level_3": {"options": [{"text": "带大", "is_correct": true, "explanation": "正确：“把我带大”指抚养我长大，符合句意。"}, {"text": "生下来", "is_correct": false, "explanation": "语义：生下来指生育，奶奶不能生下“我”，与句意矛盾。"}, {"text": "送走", "is_correct": false, "explanation": "搭配：“送走”说离开，与奶奶一个人抚养我的语境不搭。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：丢掉与“奶奶一个人把我……”的抚养意思相反。"}], "explanations": {"带大": "正确：“把我带大”指抚养我长大，符合句意。", "生下来": "语义：生下来指生育，奶奶不能生下“我”，与句意矛盾。", "送走": "搭配：“送走”说离开，与奶奶一个人抚养我的语境不搭。", "丢掉": "语义：丢掉与“奶奶一个人把我……”的抚养意思相反。"}, "sentence_index": 0, "correct_answer": "带大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠打工带大了全家人。", "explanation": "这里应该用〈养活〉。带大只用于从小抚养孩子到长大，全家人都是成年人，要说养活。"}, {"text": "他带大了全队，最后赢得了比赛。", "explanation": "这里应该用〈带领〉。带大指从小抚养孩子到长大，不能用来表示带领团队。"}, {"text": "他从小就把早起的习惯带大了。", "explanation": "这里应该用〈培养〉。带大只用于抚育人长大，习惯要说培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93165, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带大", "is_correct": true, "explanation": "正确：“把孩子带大”指抚育到成年，与“不容易”的语境相符。"}, {"text": "逃避", "is_correct": false, "explanation": "配价：“逃避”后不能直接带“孩子”作宾语，此处不成立。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”指把整体分开，用于孩子不成立，句意不通。"}, {"text": "翻开", "is_correct": false, "explanation": "搭配：“翻开”用于书页等，不能用于孩子，句意不通。"}], "explanations": {"带大": "正确：“把孩子带大”指抚育到成年，与“不容易”的语境相符。", "逃避": "配价：“逃避”后不能直接带“孩子”作宾语，此处不成立。", "拆开": "语义：“拆开”指把整体分开，用于孩子不成立，句意不通。", "翻开": "搭配：“翻开”用于书页等，不能用于孩子，句意不通。"}, "sentence_index": 6, "correct_answer": "带大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项政策带大了当地的经济。", "explanation": "这里应该用〈带动〉。带大只用于抚育人长大，经济、事业要用带动。"}, {"text": "这家工厂每年带大很多汽车。", "explanation": "这里应该用〈生产〉。带大只用于人（主要是孩子），不能用于产品。"}, {"text": "这次培训让他的水平带大了不少。", "explanation": "这里应该用〈提高〉。带大指抚育孩子长大，水平、质量要用提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一个人把儿子带大了了。", "corrected_sentence": "她一个人把儿子带大了。", "error_description": "错误：动态助词“了”重复出现在补语“大”之后，只用一个“了”即可。正确：“把儿子带大了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老两口三个儿子都把带大了。", "corrected_sentence": "老两口三个儿子都带大了。", "error_description": "错误：“把”字句必须带出被处置的宾语，此处“把”后没有宾语，多加了“把”。正确：“老两口三个儿子都带大了”，不用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
