INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以资金投入企业或项目以获取收益的人。", "primary_collocate": null, "pronunciation": "tóu zī jiā", "ipa": "tʰou˧˥ tsɹ̩˥ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位投资家准备投资一家新公司。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资家在决定之前，会仔细看公司的报告。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位成功的投资家，投过很多项目。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资家希望这个项目能带来收益。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要投资家的资金来发展。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位投资家对新技术很有兴趣。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资家要承担一定的风险。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业找到了一位合适的投资家。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资家看中了这个项目的市场。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的投资家会先了解企业的情况。", "target_word": "投资家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位投资家", "label": "量词"}], "register": "书面语", "sense_fingerprint": "以资金投入企业或项目以获取收益的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad589025-ca3e-4551-a9f9-01f0e0f0297e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投资家", "is_correct": true, "explanation": "正确。“这位投资家”指以资金投入企业或项目以获取收益的人，与“准备投资一家新公司”相符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”不能投资一家新公司，与句意不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”用“扇”计量，不说“这位窗户”，也不能进行投资。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有资金，不能投资一家新公司，与句意不合。"}], "explanations": {"投资家": "正确。“这位投资家”指以资金投入企业或项目以获取收益的人，与“准备投资一家新公司”相符。", "蔬菜": "语义：“蔬菜”不能投资一家新公司，与句意不合。", "窗户": "搭配：“窗户”用“扇”计量，不说“这位窗户”，也不能进行投资。", "石头": "语义：“石头”没有资金，不能投资一家新公司，与句意不合。"}, "sentence_index": 0, "correct_answer": "投资家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "投资家负责公司的日常管理。", "explanation": "这里应该用〈经理〉。投资家出资获利，不负责公司日常管理。"}, {"text": "投资家每天在工地上搬砖。", "explanation": "这里应该用〈工人〉。投资家是出资获利的人，不在工地搬砖。"}, {"text": "投资家每天在教室里给学生上课。", "explanation": "这里应该用〈教师〉。投资家是出资获利的人，不给学生上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投资家", "is_correct": true, "explanation": "正确。“投资家要承担一定的风险”指投入资金的人需要承担风险，与句意相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能决定投入资金，与“承担一定的风险”的语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有判断和行动的能力，不能承担投资风险。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不能搭配“承担风险”这类由人担责的动作。"}], "explanations": {"投资家": "正确。“投资家要承担一定的风险”指投入资金的人需要承担风险，与句意相符。", "小狗": "语义：小狗不能决定投入资金，与“承担一定的风险”的语境不合。", "石头": "语义：石头没有判断和行动的能力，不能承担投资风险。", "桌子": "搭配：“桌子”不能搭配“承担风险”这类由人担责的动作。"}, "sentence_index": 6, "correct_answer": "投资家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位投资家每天管理公司的日常事务。", "explanation": "这里应该用〈企业家〉。投资家出资获利，不参与日常经营管理。"}, {"text": "投资家每天向客户介绍产品。", "explanation": "这里应该用〈销售员〉。投资家关注的是投入资金的收益，不向客户介绍产品。"}, {"text": "投资家每月核对账目。", "explanation": "这里应该用〈会计〉。投资家的工作是投入资金获利，不负责核对账目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只投资家很有眼光。", "corrected_sentence": "这位投资家很有眼光。", "error_description": "量词错误：“投资家”指人，应用“位”，不能用“只”，应说“这位投资家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只投资家愿意承担风险。", "corrected_sentence": "那位投资家愿意承担风险。", "error_description": "量词错误：“投资家”指人，应用“位”，不能用“只”，应说“那位投资家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f27f85-6783-4741-affc-281f8a2bbe2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
