INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依法将违法者在短期内留置并限制其自由。", "primary_collocate": null, "pronunciation": "jū liú", "ipa": "tɕy˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "公安机关依法拘留了这名违法者。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定,可以拘留违法的人十五天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方依法拘留了三名嫌疑人。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察因他打人,依法拘留了他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方决定依法拘留他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有法律规定,不能随便拘留别人。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察依法拘留他十天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公安机关拘留过很多违法者。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依法拘留违法者,是警察的工作。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方已经依法拘留了那个司机。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拘留了", "label": "体标"}, {"form": "拘留过", "label": "体标"}], "register": "书面", "sense_fingerprint": "公安机关依法短期留置违法者并限制其自由(法律用语)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”是依法短期限制违法者人身自由，与句中“依法”的语境相符。"}, {"text": "查封", "is_correct": false, "explanation": "搭配：“查封”针对房屋、场所等财物，不能用于人。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：“表彰”是褒扬有功的人，与“违法者”矛盾。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”针对账户、资产，不能用于人。"}], "explanations": {"拘留": "“拘留”是依法短期限制违法者人身自由，与句中“依法”的语境相符。", "查封": "搭配：“查封”针对房屋、场所等财物，不能用于人。", "表彰": "语义：“表彰”是褒扬有功的人，与“违法者”矛盾。", "冻结": "搭配：“冻结”针对账户、资产，不能用于人。"}, "sentence_index": 0, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察依法拘留了他的手机。", "explanation": "这里应该用〈扣押〉。拘留针对人身自由，手机等财物要用扣押。"}, {"text": "他因为贩毒被判了三年拘留。", "explanation": "这里应该用〈监禁〉。拘留最长十五日，判几年要用监禁。"}, {"text": "他因为超速被依法拘留两百元。", "explanation": "这里应该用〈罚款〉。拘留是限制人身自由的措施，不能按金额计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”是依法短期限制人身自由，与“依法……他十天”的语境相符。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”针对申请或事项，不能用于拘禁人身。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与依法限制人身自由的意思相反。"}, {"text": "签发", "is_correct": false, "explanation": "搭配：“签发”的对象是证件、文件，不能说“签发他十天”。"}], "explanations": {"拘留": "“拘留”是依法短期限制人身自由，与“依法……他十天”的语境相符。", "批准": "语义：“批准”针对申请或事项，不能用于拘禁人身。", "表扬": "语义：“表扬”是褒奖，与依法限制人身自由的意思相反。", "签发": "搭配：“签发”的对象是证件、文件，不能说“签发他十天”。"}, "sentence_index": 6, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察依法拘留了那家饭店。", "explanation": "这里应该用〈查封〉。拘留的对象是人，饭店等场所要用查封。"}, {"text": "老师让他拘留了一节课。", "explanation": "这里应该用〈罚站〉。拘留是公安机关依法执行的措施，学校老师的处罚不能用拘留。"}, {"text": "他因为违纪被学校拘留一周。", "explanation": "这里应该用〈禁足〉。拘留是公安机关依法执行的措施，学校的处罚要用禁足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公安机关依法拘留得那名醉酒驾驶者十天。", "corrected_sentence": "公安机关依法拘留了那名醉酒驾驶者十天。", "error_description": "表示拘留时长的“十天”前应用“了”表示完成，不能用“得”。“拘留得那名醉酒驾驶者十天”是错误形式，应为“拘留了那名醉酒驾驶者十天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那名肇事司机警方依法拘留了。", "corrected_sentence": "那名肇事司机被警方依法拘留了。", "error_description": "被动句中施事“警方”前必须用“被”。漏掉“被”后应为“那名肇事司机被警方依法拘留了”，不能写成“那名肇事司机警方依法拘留了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
