INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指控是说某个人做了坏事。", "primary_collocate": null, "pronunciation": "zhǐ kòng", "ipa": "ʈʂɨ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "邻居指控他偷了自行车。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明指控同学拿了他的书。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她指控老板每天让工人加班到半夜。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有指控过别人。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女人指控司机撞了她的车。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你凭什么指控我？", "target_word": "指控", "complexity_tier": "T3", "furigana": "zhǐ kòng", "sentence_source": "generated"}, {"text": "他们指控这家店卖假药。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人指控那个年轻人骗了他的钱。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们指控哥哥吃了所有的蛋糕。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证据，你不能随便指控别人。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指控了", "label": "体标"}, {"form": "指控过", "label": "体标"}], "register": "中性", "sense_fingerprint": "指控：说某人做了坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：指控即说某人做了坏事，邻居说他偷了自行车，符合句意。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖是称赞好的行为，与“偷了自行车”矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢针对别人的帮助或好意，不能用于偷窃行为。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”后要接损失或款项，不能接“他偷了自行车”。"}], "explanations": {"指控": "正确：指控即说某人做了坏事，邻居说他偷了自行车，符合句意。", "夸奖": "语义：夸奖是称赞好的行为，与“偷了自行车”矛盾。", "感谢": "语义：感谢针对别人的帮助或好意，不能用于偷窃行为。", "赔偿": "搭配：“赔偿”后要接损失或款项，不能接“他偷了自行车”。"}, "sentence_index": 0, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是指控别人不努力。", "explanation": "这里应该用〈指责〉。指控多指说某人做了坏事或犯罪，不努力还不到需要指控的程度。"}, {"text": "老师指控他上课讲话。", "explanation": "这里应该用〈批评〉。指控带有“说某人犯了严重错误”的分量，上课讲话只需批评。"}, {"text": "妈妈指控邻居太吵。", "explanation": "这里应该用〈抱怨〉。指控要说出对方做了坏事，邻居太吵只是不满，应说抱怨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：指控即说某人做了坏事，“卖假药”正是被指控的违法行为，符合句意。"}, {"text": "批准", "is_correct": false, "explanation": "语义：批准表示同意，与“卖假药”这种违法行为不符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：推荐是向人介绍好的东西，不能用于违法行为。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”后接的是费用或开支，不能接“卖假药”。"}], "explanations": {"指控": "正确：指控即说某人做了坏事，“卖假药”正是被指控的违法行为，符合句意。", "批准": "语义：批准表示同意，与“卖假药”这种违法行为不符。", "推荐": "语义：推荐是向人介绍好的东西，不能用于违法行为。", "报销": "搭配：“报销”后接的是费用或开支，不能接“卖假药”。"}, "sentence_index": 6, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手指控远处的山。", "explanation": "这里应该用〈指着〉。“指控”是控告某人做了坏事，此处只是用手指向远处，应说“指着”。"}, {"text": "他很会指控自己的情绪。", "explanation": "这里应该用〈控制〉。“指控”含有控告对方罪行的意思，管理情绪要用“控制”。"}, {"text": "老板指控员工工作认真。", "explanation": "这里应该用〈表扬〉。指控要说明对方做了坏事，对工作认真的员工应当表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店主指控了过他偷东西。", "corrected_sentence": "店主指控过他偷东西。", "error_description": "“指控”后用“过”表示经历，不能再加“了”；应说“指控过他偷东西”，“了过”连用是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把指控我们泄露了秘密。", "corrected_sentence": "老板指控我们泄露了秘密。", "error_description": "“把”后须接被处置的对象，此句“把”后直接是动词“指控”，不合语法，应去掉“把”，说“老板指控我们泄露了秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
