INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93178, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开指出并控告某人的罪状或过失。", "primary_collocate": null, "pronunciation": "zhǐ kòng", "ipa": "ʈʂɨ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "律师在法庭上指控他犯了盗窃罪。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸公开指控这家公司污染河水。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官指控三名男子参与抢劫。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民在会上指控官员乱花公款。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者公开指控市长收了别人的钱。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们公开指控工厂拖欠工资。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方指控我们违反了合同。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方指控他开车撞伤了行人。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生联名指控校长乱收费。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原告在法院指控对方诈骗。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指控了", "label": "体标"}, {"form": "指控过", "label": "体标"}], "register": "书面", "sense_fingerprint": "指控：公开指出并控告某人的罪状或过失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：律师在法庭上指控他犯了盗窃罪，指控即正式说某人犯了罪，符合句意。"}, {"text": "辩护", "is_correct": false, "explanation": "语义：辩护是替被告开脱罪责，与“指控他犯了盗窃罪”正好相反。"}, {"text": "赞扬", "is_correct": false, "explanation": "配价：“赞扬”要接值得称赞的人或行为，不能接“犯了盗窃罪”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢的对象是他人的帮助或善意，与“盗窃罪”无关。"}], "explanations": {"指控": "正确：律师在法庭上指控他犯了盗窃罪，指控即正式说某人犯了罪，符合句意。", "辩护": "语义：辩护是替被告开脱罪责，与“指控他犯了盗窃罪”正好相反。", "赞扬": "配价：“赞扬”要接值得称赞的人或行为，不能接“犯了盗窃罪”。", "感谢": "语义：感谢的对象是他人的帮助或善意，与“盗窃罪”无关。"}, "sentence_index": 0, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他指控这份数据不太准确。", "explanation": "这里应该用〈怀疑〉。指控针对的是有人做了坏事，数据不准确不是可以指控的行为。"}, {"text": "妈妈指控我的字写得很好。", "explanation": "这里应该用〈称赞〉。指控表示说人做了坏事，夸奖字写得好不能用“指控”。"}, {"text": "老板指控员工在办公室喝了一杯水。", "explanation": "这里应该用〈提醒〉。指控针对的是罪状或过失，在办公室喝一杯水不算过失，只需提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：指控即指出对方做了违法或违约的事，“违反了合同”正是被指控的内容，符合句意。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：表彰是对好人好事的肯定，与“违反了合同”矛盾。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺用于喜事，不能用于违约行为。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”后接的是损失或款项，不能接“违反了合同”。"}], "explanations": {"指控": "正确：指控即指出对方做了违法或违约的事，“违反了合同”正是被指控的内容，符合句意。", "表彰": "语义：表彰是对好人好事的肯定，与“违反了合同”矛盾。", "祝贺": "语义：祝贺用于喜事，不能用于违约行为。", "赔偿": "搭配：“赔偿”后接的是损失或款项，不能接“违反了合同”。"}, "sentence_index": 6, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用手指控桌上的杯子。", "explanation": "这里应该用〈指着〉。“指控”是控告某人做了坏事，此处只是用手指向杯子，应说“指着”。"}, {"text": "他很会指控自己的怒火。", "explanation": "这里应该用〈控制〉。“指控”含有控告对方罪行的意思，管理怒火要用“控制”。"}, {"text": "大家都指控他的勇敢。", "explanation": "这里应该用〈佩服〉。指控是说对方做了坏事，对他的勇敢表示敬意应说“佩服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店主在法院被指控那个小偷。", "corrected_sentence": "店主在法院指控那个小偷。", "error_description": "“被”字句的主语应是受到指控的人（小偷），店主是指控方，不能用“被”。应说“店主在法院指控那个小偷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻居把指控那个司机酒驾。", "corrected_sentence": "邻居指控那个司机酒驾。", "error_description": "“指控”前面不能加“把”，应去掉“把”，说“邻居指控那个司机酒驾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
