INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使不好的事物不再存在。", "primary_collocate": null, "pronunciation": "xiāo chú", "ipa": "ɕjɑʊ̯˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "政府想消除城市里的污染。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要消除对别人的偏见。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副耳机可以消除外面的噪音。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校一直在努力消除安全隐患。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友的陪伴消除了我的孤独。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家想办法消除贫富差距。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以消除照片里的杂物。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地，他消除了对水的恐惧。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新的方法消除了脸上的痘印。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打扫干净，消除了厨房里的细菌。", "target_word": "消除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消除了", "label": "完成体"}, {"form": "消除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使不好的事物不再存在：消除污染、偏见、隐患", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”表示使污染不再存在，符合政府想治理污染的意图。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”使污染变多，与政府想治理污染的意图相反。"}, {"text": "散布", "is_correct": false, "explanation": "搭配：“散布”多用于消息、谣言，不能和“污染”搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、艺术作品，不能说欣赏污染。"}], "explanations": {"消除": "正确：“消除”表示使污染不再存在，符合政府想治理污染的意图。", "增加": "语义：“增加”使污染变多，与政府想治理污染的意图相反。", "散布": "搭配：“散布”多用于消息、谣言，不能和“污染”搭配。", "欣赏": "搭配：“欣赏”的对象是风景、艺术作品，不能说欣赏污染。"}, "sentence_index": 0, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们消除了这项纪录。", "explanation": "这里应该用〈打破〉。纪录要用打破，消除只用于去掉不好的事物。"}, {"text": "政府消除了空气质量。", "explanation": "这里应该用〈改善〉。空气质量要用改善，消除不能用于质量这类抽象的好坏状况。"}, {"text": "我终于消除了这本书。", "explanation": "这里应该用〈消化〉。读完书后理解吸收要用消化；消除用于去掉不好的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消除", "is_correct": true, "explanation": "正确：“消除”表示去掉照片里的杂物，符合软件的用途。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是人或景物，不能说拍摄照片里已有的杂物。"}, {"text": "制作", "is_correct": false, "explanation": "语义：“制作”是做出新东西，照片里的杂物已经存在，与“消除”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱杂物。"}], "explanations": {"消除": "正确：“消除”表示去掉照片里的杂物，符合软件的用途。", "拍摄": "搭配：“拍摄”的对象是人或景物，不能说拍摄照片里已有的杂物。", "制作": "语义：“制作”是做出新东西，照片里的杂物已经存在，与“消除”的语境不符。", "唱": "搭配：“唱”的对象是歌曲，不能说唱杂物。"}, "sentence_index": 6, "correct_answer": "消除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察消除了那起案件。", "explanation": "这里应该用〈侦破〉。案件要用侦破；消除用于去掉不好的事物，不用于办案。"}, {"text": "他消除了那支蜡烛。", "explanation": "这里应该用〈熄灭〉。蜡烛、火要用熄灭，消除用于去掉不好的事物。"}, {"text": "工人消除了那座桥。", "explanation": "这里应该用〈拆除〉。拆除用于把桥梁、房屋等建筑拆掉；消除用于去掉误会、隐患等不好的情况，不用于建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府把城市里的污染消除。", "corrected_sentence": "政府把城市里的污染消除了。", "error_description": "错误在于“把”字句中动词“消除”后缺少“了”等成分，句子不完整；应为“把城市里的污染消除了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经消除了过厨房里的细菌。", "corrected_sentence": "他们已经消除过厨房里的细菌。", "error_description": "错误在于“消除了过”同时用了完成体“了”和经历体“过”，两者不能并用；应为“已经消除过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
