INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93191, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "无人是没有人在。", "primary_collocate": null, "pronunciation": "wú rén", "ipa": "u˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他到家时，房间里无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上十点，教学楼里已经无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去找老师，办公室无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨天，公园里几乎无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店门开着，可是店里无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回头看，身后无人。", "target_word": "无人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早上的海边无人，很安静。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议室里无人，灯也关了。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我敲门没人开，屋里好像无人。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子里的老房子现在无人居住。", "target_word": "无人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "无人：某处没有人在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67a56d63-f4af-48ab-bef5-25a06a44575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无人", "is_correct": true, "explanation": "正确：无人（wú rén）指某处没有人在，是这个义项的本义。"}, {"text": "五人", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是五个人。"}, {"text": "误人", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是耽误别人。"}, {"text": "武人", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是习武的人。"}], "explanations": {"无人": "正确：无人（wú rén）指某处没有人在，是这个义项的本义。", "五人": "wǔ（第三声）与 wú（第二声）声调不同，意思是五个人。", "误人": "wù（第四声）与 wú（第二声）声调不同，意思是耽误别人。", "武人": "wǔ（第三声）与 wú（第二声）声调不同，意思是习武的人。"}, "sentence_index": null, "correct_answer": "无人"}, "level_3": {"options": [{"text": "无关", "is_correct": false, "explanation": "语义：“无关”指与……没有关系，不能用来描述房间里的状况。"}, {"text": "无人", "is_correct": true, "explanation": "正确：“无人”说房间里没有人，与“他到家时”的情境相符。"}, {"text": "无益", "is_correct": false, "explanation": "搭配：“无益”多用于行为或事情的效果，不能用来描述房间里的情况。"}, {"text": "无尽", "is_correct": false, "explanation": "语义：“无尽”指没有尽头，不能用来描述房间的状况。"}], "explanations": {"无关": "语义：“无关”指与……没有关系，不能用来描述房间里的状况。", "无人": "正确：“无人”说房间里没有人，与“他到家时”的情境相符。", "无益": "搭配：“无益”多用于行为或事情的效果，不能用来描述房间里的情况。", "无尽": "语义：“无尽”指没有尽头，不能用来描述房间的状况。"}, "sentence_index": 0, "correct_answer": "无人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人是无人的，我有点同情他。", "explanation": "这里应该用〈孤寡〉。“无人”指没有人在场，不能用来形容人的处境；无人照顾的老人要说“孤寡”。"}, {"text": "门口站着的是无人的管理员。", "explanation": "这里应该用〈值班〉。“无人”不能修饰人，管理员要说“值班的管理员”。"}, {"text": "他是无人的学生，只能自己学。", "explanation": "这里应该用〈没人指导〉。“无人”不能修饰人；学生没人指导要说“没人指导的学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”指声音杂乱，与后面的“很安静”矛盾。"}, {"text": "无人", "is_correct": true, "explanation": "正确：“无人”说海边没有人，与“很安静”一致。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”多形容声音，不能与“很安静”同时用来描述海边。"}], "explanations": {"嘈杂": "语义：“嘈杂”指声音杂乱，与后面的“很安静”矛盾。", "无人": "正确：“无人”说海边没有人，与“很安静”一致。", "热闹": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。", "吵闹": "搭配：“吵闹”多形容声音，不能与“很安静”同时用来描述海边。"}, "sentence_index": 6, "correct_answer": "无人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小狗是无人的，没人喂它。", "explanation": "这里应该用〈无主〉。“无人”指没有人在场，不指动物没有主人；没有主人要说“无主”。"}, {"text": "这位老板是无人的，员工都很尊敬他。", "explanation": "这里应该用〈受尊敬〉。“无人”不能用来形容人；老板受尊敬要说“受尊敬”。"}, {"text": "他是无人的朋友，只能独自吃饭。", "explanation": "这里应该用〈没有〉。“无人”不能修饰人，应说“没有朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
