INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”指声音很大，与后面的“很安静”矛盾。"}, {"text": "无人", "is_correct": true, "explanation": "正确：“无人”说店里没有人，与“很安静”一致。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多，不能与“很安静”同时描述同一个地方。"}], "explanations": {"喧闹": "语义：“喧闹”指声音很大，与后面的“很安静”矛盾。", "无人": "正确：“无人”说店里没有人，与“很安静”一致。", "热闹": "语义：“热闹”指人多、有声音，与“很安静”互相矛盾。", "拥挤": "搭配：“拥挤”说人多，不能与“很安静”同时描述同一个地方。"}, "sentence_index": 6, "correct_answer": "无人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是家里无人的孩子，很懂事。", "explanation": "这里应该用〈独生子〉。“无人”指没有人在场，不能用来说明家庭关系；只有一个孩子要说“独生子”。"}, {"text": "这个村子里无人的老人很多。", "explanation": "这里应该用〈孤寡〉。“无人”指没有人在场，不能说人没有亲人；无人照顾的老人要说“孤寡老人”。"}, {"text": "他是无人的长子，家里的事都要他管。", "explanation": "这里应该用〈长子〉。“无人”不能修饰人；家里的老大要说“长子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他叫了很久，门里没无人答应。", "corrected_sentence": "他叫了很久，门里无人答应。", "error_description": "错误：“无人”本身已含“没有”的意思，前面不能再加“没”，应说“门里无人答应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "半夜的操场上没无人，只有路灯亮着。", "corrected_sentence": "半夜的操场上无人，只有路灯亮着。", "error_description": "错误：“无人”本身已含“没有”的意思，前面不能再加“没”，应说“操场上无人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
