INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一定范围内比较技能、成绩的活动。", "primary_collocate": null, "pronunciation": "jìng sài", "ipa": "tɕiŋ˥˩ sai˥˩", "syllable_count": 2, "sentences": [{"text": "全国中学生数学竞赛下个月举行。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项竞赛每两年办一次。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在省里的编程竞赛中拿了奖。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞赛成绩明天在网上公布。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为英语竞赛准备了三个月。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次技能竞赛有二十个队参加。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞赛规则里写着不能带手机。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着学生去参加科学竞赛。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司组织了一场销售竞赛。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞赛结束后，评委公布了名次。", "target_word": "竞赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "技能竞赛", "label": "复合"}, {"form": "競賽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一定范围内比较技能成绩的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5c59a7b-8344-40ee-b9d9-79947b58f882') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞赛", "is_correct": true, "explanation": "正确：数学竞赛是比较技能的活动，可以在下个月举行，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“举行”后接的是活动，不能接饭菜。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能举行。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是活动，不能举行。"}], "explanations": {"竞赛": "正确：数学竞赛是比较技能的活动，可以在下个月举行，符合句意。", "饭菜": "搭配：“举行”后接的是活动，不能接饭菜。", "窗户": "语义：窗户是物件，不能举行。", "石头": "语义：石头不是活动，不能举行。"}, "sentence_index": 0, "correct_answer": "竞赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都去医院竞赛。", "explanation": "这里应该用〈体检〉。竞赛是比较技能、成绩的活动，去医院查身体应说体检。"}, {"text": "两组结果进行了竞赛。", "explanation": "这里应该用〈对比〉。竞赛是比一比谁做得好的活动，两组结果只是相互比较，应说对比。"}, {"text": "我们班的班会上，竞赛讲了很多道理。", "explanation": "这里应该用〈老师〉。竞赛是比较技能、成绩的活动，不能讲道理，讲道理的人应说老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞赛", "is_correct": true, "explanation": "正确：竞赛规则是比赛时要遵守的规定，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，没有规则可言。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能订立规则，句子说不通。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“规则”前面要是活动或机构，“花”不能搭配。"}], "explanations": {"竞赛": "正确：竞赛规则是比赛时要遵守的规定，符合句意。", "椅子": "语义：椅子是家具，没有规则可言。", "冰箱": "语义：冰箱不能订立规则，句子说不通。", "花": "搭配：“规则”前面要是活动或机构，“花”不能搭配。"}, "sentence_index": 6, "correct_answer": "竞赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在竞赛里买了一双鞋。", "explanation": "这里应该用〈商场〉。竞赛是比较技能、成绩的活动，不是购物的地方，买东西应说商场。"}, {"text": "农民在竞赛里种菜。", "explanation": "这里应该用〈农场〉。竞赛是比较技能、成绩的活动，不是种植的地方，种菜应在农场。"}, {"text": "这家餐馆的竞赛很好吃。", "explanation": "这里应该用〈菜〉。竞赛是比较技能、成绩的活动，不能用来指可以吃的食物，应说菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "竞赛一种比较技能的活动。", "corrected_sentence": "竞赛是一种比较技能的活动。", "error_description": "缺少系词：“竞赛”作判断句的主语时，谓语前要加“是”，应说“竞赛是一种比较技能的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年报名了三竞赛。", "corrected_sentence": "他去年报名了三场竞赛。", "error_description": "量词缺失：数词和“竞赛”之间要加量词“场”，应说“三场竞赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
