INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93219, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "赶紧是马上就做，不要慢。", "primary_collocate": null, "pronunciation": "gǎn jǐn", "ipa": "kan˨˩˦ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "要迟到了，我们赶紧走吧。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，大家赶紧回家。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快考试了，你赶紧复习吧。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到电话响，她赶紧跑过去接。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭好了，赶紧来吃吧。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发现钱包不见了，赶紧回去找。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了，妈妈赶紧抱起他。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到老师来了，同学们赶紧坐好。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天要黑了，我们得赶紧下山。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车快开了，你赶紧上车！", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "马上行动，不拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“赶紧”是副词，表示抓紧时间立刻去做，与“要迟到了”的紧迫语境相合。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢，与“要迟到了”的紧迫语境相反。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意地，与“要迟到了”的催促语境无关。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”表示从未，不能用于“我们……走吧”这样的祈使句。"}], "explanations": {"赶紧": "正确：“赶紧”是副词，表示抓紧时间立刻去做，与“要迟到了”的紧迫语境相合。", "慢慢": "语义：“慢慢”表示缓慢，与“要迟到了”的紧迫语境相反。", "故意": "语义：“故意”表示有意地，与“要迟到了”的催促语境无关。", "从不": "搭配：“从不”表示从未，不能用于“我们……走吧”这样的祈使句。"}, "sentence_index": 0, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她赶紧喜欢上了这个城市。", "explanation": "这里应该用〈渐渐〉。赶紧表示立即行动，不能修饰“喜欢”这类心理状态。"}, {"text": "他赶紧去年就知道了这件事。", "explanation": "这里应该用〈早就〉。赶紧要求马上行动，不能用来说已经掌握的情况。"}, {"text": "他赶紧迟到了。", "explanation": "这里应该用〈有时〉。赶紧带有“马上去做”的意思，不能描述习惯性的迟到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“妈妈赶紧抱起他”表示立刻行动，与“孩子哭了”的情境相合。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有效果，与“抱起他”的动作不搭。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，“从来抱起他”不成立。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰“抱起”这样的动作，“很抱起他”不成立。"}], "explanations": {"赶紧": "正确：“妈妈赶紧抱起他”表示立刻行动，与“孩子哭了”的情境相合。", "白白": "语义：“白白”表示徒然、没有效果，与“抱起他”的动作不搭。", "从来": "搭配：“从来”多与否定词连用，“从来抱起他”不成立。", "很": "搭配：“很”是程度副词，不能直接修饰“抱起”这样的动作，“很抱起他”不成立。"}, "sentence_index": 6, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年春天我们赶紧去旅游。", "explanation": "这里应该用〈打算〉。赶紧强调马上行动，不能用于很远的将来。"}, {"text": "天气赶紧变冷。", "explanation": "这里应该用〈逐渐〉。赶紧表示立即，不能描述气温慢慢变化。"}, {"text": "我赶紧在北京住过。", "explanation": "这里应该用〈曾经〉。赶紧表示马上行动，不能用来说过去的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天快黑了，我们很赶紧走吧。", "corrected_sentence": "天快黑了，我们赶紧走吧。", "error_description": "程度副词错误：“赶紧”本身是副词，不能再被“很”修饰。应去掉“很”，说“我们赶紧走吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议马上要开始了，你赶紧了进来。", "corrected_sentence": "会议马上要开始了，你赶紧进来。", "error_description": "动态助词错误：“了”不能插在副词“赶紧”和动词“进来”之间。“赶紧进来”中不需要“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
