INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，抓紧时间，立刻。", "primary_collocate": null, "pronunciation": "gǎn jǐn", "ipa": "kan˨˩˦ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "时间不多了，你赶紧把作业写完。", "target_word": "赶紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药要趁热喝，赶紧喝吧。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电了，我赶紧找充电器。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人快到了，赶紧把房间收拾一下。", "target_word": "赶紧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有水，大家赶紧躲开。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看见老人摔倒，他赶紧跑过去扶。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业明天要交，今晚得赶紧做完。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想起约会的事，赶紧换衣服出门。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤快洒出来了，她赶紧关火。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨越下越大，我们赶紧找地方躲雨。", "target_word": "赶紧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "抓紧时间，立刻去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“你赶紧把作业写完”表示抓紧时间立刻去做，与“时间不多了”相合。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢，与“时间不多了”的紧迫语境相反。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然，“白白把作业写完”与催促的语境不合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能用于“你……把作业写完”的催促句。"}], "explanations": {"赶紧": "正确：“你赶紧把作业写完”表示抓紧时间立刻去做，与“时间不多了”相合。", "慢慢": "语义：“慢慢”表示缓慢，与“时间不多了”的紧迫语境相反。", "白白": "语义：“白白”表示徒然，“白白把作业写完”与催促的语境不合。", "从来": "搭配：“从来”多与否定词连用，不能用于“你……把作业写完”的催促句。"}, "sentence_index": 0, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我赶紧生病了。", "explanation": "这里应该用〈突然〉。赶紧表示马上去做某事，不能用来说生病这种不由自主发生的变化。"}, {"text": "他赶紧高兴了一个下午。", "explanation": "这里应该用〈整整〉。赶紧表示马上去做，不能用来说持续一个下午的心情。"}, {"text": "天气赶紧变冷。", "explanation": "这里应该用〈逐渐〉。赶紧表示立即，不能描述气温慢慢变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶紧", "is_correct": true, "explanation": "正确：“今晚得赶紧做完”表示抓紧时间完成，与“明天要交”的紧迫语境相合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意地，“今晚得故意做完”与紧迫的语境不合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“明天要交”的因果关系不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“今晚得……做完”的必然性相反。"}], "explanations": {"赶紧": "正确：“今晚得赶紧做完”表示抓紧时间完成，与“明天要交”的紧迫语境相合。", "故意": "语义：“故意”表示有意地，“今晚得故意做完”与紧迫的语境不合。", "竟然": "语义：“竟然”表示出乎意料，与“明天要交”的因果关系不通。", "偶尔": "语义：“偶尔”表示不经常，与“今晚得……做完”的必然性相反。"}, "sentence_index": 6, "correct_answer": "赶紧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们赶紧每年都回老家。", "explanation": "这里应该用〈经常〉。赶紧表示马上去做，不能用来说每年重复发生的事。"}, {"text": "我赶紧没吃过北京烤鸭。", "explanation": "这里应该用〈从来〉。赶紧表示马上去做，不能用来描述一直没有发生过的经历。"}, {"text": "他赶紧三年前就毕业了。", "explanation": "这里应该用〈早就〉。赶紧表示马上去做，不能用来说几年前已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很赶紧换衣服出门。", "corrected_sentence": "他赶紧换衣服出门。", "error_description": "程度副词错误：“赶紧”是副词，不能受“很”修饰。应删去“很”，说“赶紧换衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨了，我们赶紧了去躲雨。", "corrected_sentence": "下雨了，我们赶紧去躲雨。", "error_description": "体标错误：“赶紧”是副词，后面不能直接加“了”。应删去“了”，说“赶紧去躲雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。"}, {"text": "中午", "is_correct": false, "explanation": "中午属于白天之内，与“晚间”没有对立关系，不构成反义。"}, {"text": "上午", "is_correct": false, "explanation": "上午是白天的前半段，不是与“晚间”相对的词。"}, {"text": "周末", "is_correct": false, "explanation": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。", "中午": "中午属于白天之内，与“晚间”没有对立关系，不构成反义。", "上午": "上午是白天的前半段，不是与“晚间”相对的词。", "周末": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。"}, {"text": "下午", "is_correct": false, "explanation": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。"}, {"text": "星期三", "is_correct": false, "explanation": "星期三指一周中的某一天，与“晚间”的时段没有对立关系。"}, {"text": "春节", "is_correct": false, "explanation": "春节指农历新年，与“晚间”没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（太阳下山以后）相对，二者是一对反义词。", "下午": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。", "星期三": "星期三指一周中的某一天，与“晚间”的时段没有对立关系。", "春节": "春节指农历新年，与“晚间”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚间是太阳下山以后的时候。", "primary_collocate": null, "pronunciation": "wǎn jiān", "ipa": "wan˨˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "晚间天黑了，路上的车少了。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间我常常在家看书。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山了，晚间的风有点凉。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚间，大家喜欢在外面走走。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间路灯都亮了，请小心开车。", "target_word": "晚间", "complexity_tier": "T3", "furigana": "wǎn jiān", "sentence_source": "generated"}, {"text": "他每天晚间都去公园跑步。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间的天空里有很多星星。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间的街上很热闹，很多人在散步。", "target_word": "晚间", "complexity_tier": "T3", "furigana": "wǎn jiān", "sentence_source": "generated"}, {"text": "冬天晚间天黑得早。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚间我们一家人在院子里吃饭。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晚間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳下山、天黑以后的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指太阳下山以后，与“天黑了”相符。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是早上，与“天黑了”矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是白天，不会出现天黑的情况。"}, {"text": "白昼", "is_correct": false, "explanation": "语域：“白昼”偏书面，口语多说“白天”；且白昼时天不会黑。"}], "explanations": {"晚间": "正确：“晚间”指太阳下山以后，与“天黑了”相符。", "清晨": "语义：清晨是早上，与“天黑了”矛盾。", "中午": "语义：中午是白天，不会出现天黑的情况。", "白昼": "语域：“白昼”偏书面，口语多说“白天”；且白昼时天不会黑。"}, "sentence_index": 0, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚间的太阳还挂在天上，我们在湖边钓鱼。", "explanation": "这里应该用〈白天〉。太阳还挂在天上时用“白天”，“晚间”指太阳下山以后，两者不能搭配。"}, {"text": "那天我一只晚间都在看书。", "explanation": "这里应该用〈个〉。时段名词“晚间”的量词是“个”（一个晚上），“只”不能用于时段。"}, {"text": "晚间的日出很美，我们早早起来看。", "explanation": "这里应该用〈清晨〉。日出在清晨，“晚间”指太阳下山以后，不能用来描述日出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指入夜后的时段，天空中有星星，与句意相符。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是白天最亮的时候，天空中看不到许多星星。"}, {"text": "午后", "is_correct": false, "explanation": "语义：午后仍是白天，天空中看不到星星。"}, {"text": "昼间", "is_correct": false, "explanation": "语域：“昼间”偏书面，口语多说“白天”；且白天的天空看不到星星。"}], "explanations": {"晚间": "正确：“晚间”指入夜后的时段，天空中有星星，与句意相符。", "正午": "语义：正午是白天最亮的时候，天空中看不到许多星星。", "午后": "语义：午后仍是白天，天空中看不到星星。", "昼间": "语域：“昼间”偏书面，口语多说“白天”；且白天的天空看不到星星。"}, "sentence_index": 6, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚间吃早饭的时候，我们在院子里聊天。", "explanation": "这里应该用〈早上〉。吃早饭是在早上，“晚间”指太阳下山以后，不能用来说早饭的时间。"}, {"text": "我们在一座晚间里聊了很久。", "explanation": "这里应该用〈个〉。时段名词“晚间”的量词是“个”，“座”只用于山、楼房等大型固定物。"}, {"text": "晚间的午饭时间，食堂里很热闹。", "explanation": "这里应该用〈中午〉。午饭时间是中午，“晚间”指太阳下山以后，不能用来说午饭时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们晚间的看电视。", "corrected_sentence": "我们晚间看电视。", "error_description": "错误：“晚间”后多加了“的”，动词“看”前不能直接用“的”，应说「我们晚间看电视」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天一晚间散步。", "corrected_sentence": "他每天晚间散步。", "error_description": "错误：“晚间”前多加了数词“一”。时间词“晚间”前用“每天”修饰即可，不加数词，应说「他每天晚间散步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。"}, {"text": "下午", "is_correct": false, "explanation": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。"}, {"text": "中午", "is_correct": false, "explanation": "中午是白天的一个时刻，与“晚间”没有对立关系。"}, {"text": "星期天", "is_correct": false, "explanation": "星期天指一周中的某一天，与“晚间”的时段没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。", "下午": "下午属于白天的一部分，与“晚间”没有对立关系，不构成反义。", "中午": "中午是白天的一个时刻，与“晚间”没有对立关系。", "星期天": "星期天指一周中的某一天，与“晚间”的时段没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。"}, {"text": "周末", "is_correct": false, "explanation": "周末指星期六、星期日，与“晚间”的时段没有对立关系。"}, {"text": "星期一", "is_correct": false, "explanation": "星期一指一周中的某一天，与“晚间”没有对立关系。"}, {"text": "元旦", "is_correct": false, "explanation": "元旦指公历新年，与“晚间”没有对立关系。"}], "correct_answer": "白天", "explanations": {"白天": "正确：白天与晚间（傍晚到夜里）相对，二者是一对反义词。", "周末": "周末指星期六、星期日，与“晚间”的时段没有对立关系。", "星期一": "星期一指一周中的某一天，与“晚间”没有对立关系。", "元旦": "元旦指公历新年，与“晚间”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚上；傍晚到夜里的一段时间。", "primary_collocate": null, "pronunciation": "wǎn jiān", "ipa": "wan˨˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "今天晚间有一场大雨。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目晚间七点开始播出。", "target_word": "晚间", "complexity_tier": "T3", "furigana": "wǎn jiān", "sentence_source": "generated"}, {"text": "明天晚间气温会降到五度。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店晚间十点才关门。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末晚间，电影院里人很多。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说晚间不要吃太多。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司晚间会发通知。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这趟火车晚间到北京。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在晚间八点以后给我打电话。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视节目在晚间播出。", "target_word": "晚间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晚間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从傍晚到夜里的时段，常用于预报、安排、通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指傍晚到夜里的时段，与“今天”及大雨的预报相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”与句中的“今天”冲突，不能同时指今天。"}, {"text": "明年", "is_correct": false, "explanation": "语义：明年是将来的年份，与“今天”矛盾。"}, {"text": "前夜", "is_correct": false, "explanation": "语域：“前夜”偏书面，且指前一天的夜里，与“今天”冲突。"}], "explanations": {"晚间": "正确：“晚间”指傍晚到夜里的时段，与“今天”及大雨的预报相符。", "昨天": "语义：“昨天”与句中的“今天”冲突，不能同时指今天。", "明年": "语义：明年是将来的年份，与“今天”矛盾。", "前夜": "语域：“前夜”偏书面，且指前一天的夜里，与“今天”冲突。"}, "sentence_index": 0, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚间的阳光很刺眼，我们在操场上踢球。", "explanation": "这里应该用〈白天〉。阳光刺眼时是白天，“晚间”指傍晚到夜里，不能用来描述白天的阳光。"}, {"text": "他一片晚间都在复习。", "explanation": "这里应该用〈个〉。时段名词“晚间”的量词是“个”，“片”不能用于时段。"}, {"text": "晚间的晨练很热闹，老人们都在公园里。", "explanation": "这里应该用〈早上〉。晨练在早上，“晚间”指傍晚到夜里，不能用于早晨的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚间", "is_correct": true, "explanation": "正确：“晚间”指入夜前后的时段，适用于公司发通知的语境。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”是过去，与“会”表示将来的语境矛盾。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去的一周，与表示将来的“会发”矛盾。"}, {"text": "昨晚", "is_correct": false, "explanation": "语义：“昨晚”指过去的夜间，与表示将来的“会发”矛盾。"}], "explanations": {"晚间": "正确：“晚间”指入夜前后的时段，适用于公司发通知的语境。", "去年": "语义：“去年”是过去，与“会”表示将来的语境矛盾。", "上周": "语义：“上周”指过去的一周，与表示将来的“会发”矛盾。", "昨晚": "语义：“昨晚”指过去的夜间，与表示将来的“会发”矛盾。"}, "sentence_index": 6, "correct_answer": "晚间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚间的午后很安静，我在窗边看书。", "explanation": "这里应该用〈下午〉。午后属于白天，“晚间”指傍晚到夜里，不能用来说午后的时间。"}, {"text": "这个节目在一阵晚间里播出。", "explanation": "这里应该用〈个〉。时段名词“晚间”的量词是“个”，“阵”多用于风、雨、声音等。"}, {"text": "晚间的中午很热，我们去游泳。", "explanation": "这里应该用〈白天〉。中午属于白天，“晚间”指傍晚到夜里，不能用于中午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友一只晚间都在等我。", "corrected_sentence": "朋友一个晚间都在等我。", "error_description": "错误：时段名词“晚间”的量词用错。“只”多用于鸟兽等动物，时段应用量词“个”，说「朋友一个晚间都在等我」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐一阵晚间都在看书。", "corrected_sentence": "姐姐一个晚间都在看书。", "error_description": "错误：时段名词“晚间”的量词用错。“一阵”多用于风、雨、声音等，时段应用量词“个”，说「姐姐一个晚间都在看书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
