INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "服务台是有人在那里回答问题、帮你忙的桌子。", "primary_collocate": null, "pronunciation": "fú wù tái", "ipa": "fu˧˥ u˥˩ tʰai˧˥", "syllable_count": 3, "sentences": [{"text": "我有问题，就去服务台问。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务台后面坐着一位小姐。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的包找到了，在服务台那里。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务台的人告诉我怎么走。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到服务台拿你的钥匙。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在服务台问了去地铁站的路。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机放在服务台上了。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务台前面有很多人在等。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务台旁边有一张大地图。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把票交给了服务台的小姐。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服務台", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有人坐在后面回答问题、帮人忙的桌子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务台", "is_correct": true, "explanation": "正确：服务台是有人回答问题的桌子，“去服务台问”符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能在那里问问题。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是存放食物的电器，不是可以问问题的地方。"}, {"text": "盥洗室", "is_correct": false, "explanation": "语域：“盥洗室”偏书面委婉，且不是问问题的地方。"}], "explanations": {"服务台": "正确：服务台是有人回答问题的桌子，“去服务台问”符合句意。", "厨房": "语义：厨房是做饭的地方，不能在那里问问题。", "冰箱": "语义：冰箱是存放食物的电器，不是可以问问题的地方。", "盥洗室": "语域：“盥洗室”偏书面委婉，且不是问问题的地方。"}, "sentence_index": 0, "correct_answer": "服务台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在服务台看完了电影。", "explanation": "这里应该用〈影院〉。看电影要去影院，服务台只回答问题、帮忙，不能用来看电影。"}, {"text": "商场门口摆着一条服务台。", "explanation": "这里应该用〈个〉。服务台是设施，量词用“个”，“条”用于河流、裤子等细长物。"}, {"text": "我在服务台洗完了澡。", "explanation": "这里应该用〈浴室〉。洗澡要去浴室，服务台只回答问题、帮忙，不能用来洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务台", "is_correct": true, "explanation": "正确：手机放在服务台上，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：手机不能放在天空上，天空不是可以放置物品的平面。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能作放置东西的平面，“放在…上”不能接“空气”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不能作为放手机的平面。"}], "explanations": {"服务台": "正确：手机放在服务台上，符合句意。", "天空": "语义：手机不能放在天空上，天空不是可以放置物品的平面。", "空气": "搭配：“空气”不能作放置东西的平面，“放在…上”不能接“空气”。", "星星": "语义：星星在天上，不能作为放手机的平面。"}, "sentence_index": 6, "correct_answer": "服务台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在服务台买了一件衣服。", "explanation": "这里应该用〈柜台〉。买东西要到柜台，服务台只负责咨询和办事。"}, {"text": "商场大厅里有一面服务台。", "explanation": "这里应该用〈个〉。服务台是设施，量词用“个”，“面”多用于镜子、旗子等。"}, {"text": "大厅里放着一把服务台。", "explanation": "这里应该用〈个〉。“把”用于带把手的物件，不能用来修饰服务台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他服务台前面等我。", "corrected_sentence": "他在服务台前面等我。", "error_description": "错误：“服务台”前缺少介词“在”，应说「他在服务台前面等我」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我服务台问路。", "corrected_sentence": "我到服务台问路。", "error_description": "错误：“服务台”前缺少介词“到”（或“去”），表示动作的地点时应说「我到服务台问路」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
