INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设在公共场所、为顾客提供咨询和服务的柜台。", "primary_collocate": null, "pronunciation": "fú wù tái", "ipa": "fu˧˥ u˥˩ tʰai˧˥", "syllable_count": 3, "sentences": [{"text": "商场一楼有一个服务台。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的服务台二十四小时有人。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的服务台可以帮你查航班。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的服务台能告诉你科室在哪儿。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在服务台办好了入住。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆服务台可以办借书卡。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客到服务台问退货的事。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站服务台提供免费的地图。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务台的工作人员很有礼貌。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到出口，就问问服务台。", "target_word": "服务台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服務台", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商场、酒店、机场等公共场所里为顾客咨询和办事设的柜台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823c9f7d-00cb-41f2-a06b-9f6f2f7e63e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务台", "is_correct": true, "explanation": "正确：商场一楼设有服务台，“一个服务台”符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会出现在商场一楼，句意不通。"}, {"text": "湖", "is_correct": false, "explanation": "语义：商场一楼不会有湖，与常识矛盾。"}, {"text": "殿堂", "is_correct": false, "explanation": "语域：“殿堂”是文学用语，口语不这样描述商场一楼，且与句意不符。"}], "explanations": {"服务台": "正确：商场一楼设有服务台，“一个服务台”符合句意。", "月亮": "语义：月亮不会出现在商场一楼，句意不通。", "湖": "语义：商场一楼不会有湖，与常识矛盾。", "殿堂": "语域：“殿堂”是文学用语，口语不这样描述商场一楼，且与句意不符。"}, "sentence_index": 0, "correct_answer": "服务台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在服务台吃了一碗面。", "explanation": "这里应该用〈餐厅〉。吃饭要去餐厅，服务台只提供咨询和服务，不能用来吃饭。"}, {"text": "医院大厅里摆着一把服务台。", "explanation": "这里应该用〈个〉。服务台是设施，量词用“个”，“把”用于带把手的物件。"}, {"text": "我在服务台睡了一觉。", "explanation": "这里应该用〈休息室〉。睡觉要去休息室或病房，服务台只提供咨询和服务，不能用来睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务台", "is_correct": true, "explanation": "正确：顾客到服务台询问退货的事，符合句意。"}, {"text": "洗手间", "is_correct": false, "explanation": "语义：洗手间不是询问退货事情的地方。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地上不能询问退货的事，句意不通。"}, {"text": "盥洗室", "is_correct": false, "explanation": "语域：“盥洗室”偏书面委婉，且不适合在那里询问退货的事。"}], "explanations": {"服务台": "正确：顾客到服务台询问退货的事，符合句意。", "洗手间": "语义：洗手间不是询问退货事情的地方。", "草地": "语义：草地上不能询问退货的事，句意不通。", "盥洗室": "语域：“盥洗室”偏书面委婉，且不适合在那里询问退货的事。"}, "sentence_index": 6, "correct_answer": "服务台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去服务台试了这件大衣。", "explanation": "这里应该用〈试衣间〉。试衣要到试衣间，服务台用于咨询和办事。"}, {"text": "走廊尽头有一扇服务台。", "explanation": "这里应该用〈个〉。服务台是设施，量词用“个”，“扇”只用于门、窗等。"}, {"text": "我在服务台买了一块蛋糕。", "explanation": "这里应该用〈柜台〉。买东西要到柜台，服务台只负责咨询和办事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机场门口有一只服务台。", "corrected_sentence": "机场门口有一个服务台。", "error_description": "错误：量词“只”不能用于服务台，应为“个”，应说「机场门口有一个服务台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "顾客在服务台的办理退货。", "corrected_sentence": "顾客在服务台办理退货。", "error_description": "错误：“服务台”后多加了“的”，动词“办理”前不能直接用“的”，应说「顾客在服务台办理退货」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2ae81b-9c76-4294-9157-08660c801e9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
