INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东风是从东边吹来的风。", "primary_collocate": null, "pronunciation": "dōng fēng", "ipa": "tʊŋ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "今天吹的是东风，不是西风。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从东边来，这是东风。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风把船吹向西边。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗子往西飘，今天是东风。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风吹来，窗帘向西边飘。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是北风，今天换成了东风。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说，明天有三级东风。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在海边，觉得东风很大。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风一停，小船就不动了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一阵东风吹过，树叶向西动了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "東風", "label": "繁体"}, {"form": "一阵东风", "label": "量词"}], "register": "中性", "sense_fingerprint": "从东边吹来的风（风向）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西风", "is_correct": false, "explanation": "语义：后句说“不是西风”，前句若也说“西风”就自相矛盾。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”指从东边吹来的风，与后句“不是西风”形成对照。"}, {"text": "风力", "is_correct": false, "explanation": "搭配：“吹”的对象是风本身，不能说吹“风力”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“吹”不能用于降水，“吹的是雨”说不通。"}], "explanations": {"西风": "语义：后句说“不是西风”，前句若也说“西风”就自相矛盾。", "东风": "正确：“东风”指从东边吹来的风，与后句“不是西风”形成对照。", "风力": "搭配：“吹”的对象是风本身，不能说吹“风力”。", "雨": "搭配：“吹”不能用于降水，“吹的是雨”说不通。"}, "sentence_index": 0, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们顺着东风朝东边走，风一直吹在后背上。", "explanation": "这里应该用〈西边〉。“东风”是从东边吹来的风，顺着它走应朝西边，朝东边走就是逆风。"}, {"text": "我昨天看见一只东风从海上吹来。", "explanation": "这里应该用〈阵〉。风一阵一阵地来，“东风”作量词搭配应用“阵”，不用“只”。"}, {"text": "今天是东风，旗子往东飘。", "explanation": "这里应该用〈西风〉。风从西边吹来，旗子才会往东飘；从东边吹来的东风不能使旗子往东飘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "搭配：“三级”用于风力等级，不能用于降雨。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”是风，可以用“三级”表示风力，与天气预报的内容相合。"}, {"text": "冰雹", "is_correct": false, "explanation": "搭配：“三级”用于风力，冰雹不能用“三级”来计量。"}, {"text": "东方", "is_correct": false, "explanation": "语义：“东方”是方位词，不是一种风，不能与“三级”搭配。"}], "explanations": {"雨": "搭配：“三级”用于风力等级，不能用于降雨。", "东风": "正确：“东风”是风，可以用“三级”表示风力，与天气预报的内容相合。", "冰雹": "搭配：“三级”用于风力，冰雹不能用“三级”来计量。", "东方": "语义：“东方”是方位词，不是一种风，不能与“三级”搭配。"}, "sentence_index": 6, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家住在东风的南边。", "explanation": "这里应该用〈东边〉。“东风”指风，不能表示方位，说方位要用“东边”或“东方”。"}, {"text": "东风把船吹向东边。", "explanation": "“东风”是从东边吹来的风，吹向东边与风向矛盾，应吹向西边。"}, {"text": "一股东风从西边吹来，把窗户吹开了。", "explanation": "“东风”指从东边吹来的风，说它从西边吹来就把风向说错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今早吹起了一只东风，树叶都在摇。", "corrected_sentence": "今早吹起了一阵东风，树叶都在摇。", "error_description": "错误形式是“一只东风”，正确形式是“一阵东风”。“东风”是风，量词应用“阵”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天会刮从东风，出门要小心。", "corrected_sentence": "明天会刮东风，出门要小心。", "error_description": "错误形式是“刮从东风”，正确形式是“刮东风”。“东风”是风本身，不是方位，前面不能用“从”引出来源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从东方吹来的风；多指春风。", "primary_collocate": null, "pronunciation": "dōng fēng", "ipa": "tʊŋ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "东风吹来，花都开了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的东风很暖和。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风一来，河里的冰就化了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都说，东风带来了春天。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风吹绿了河边的小草。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东风吹过，柳树发芽了。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一阵暖暖的东风吹在脸上。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨夜东风吹过，今天满山是花。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人常用东风来形容春天的到来。", "target_word": "东风", "complexity_tier": "T3", "furigana": "shī rén cháng yòng dōng fēng lái xíng róng chūn tiān de dào lái", "sentence_source": "generated"}, {"text": "东风送暖，大地又有了生机。", "target_word": "东风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "東風", "label": "繁体"}, {"form": "一阵东风", "label": "量词"}], "register": "书面", "sense_fingerprint": "春风（东风送暖，春天来临）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷风", "is_correct": false, "explanation": "语义：“冷风”是寒冷的风，与花开的春日情景不合。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”指春风，吹来时百花开放，与句意相合。"}, {"text": "北风", "is_correct": false, "explanation": "语义：“北风”多指冬季的寒风，与“花都开了”的春天不符。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”不能说“吹来”，“吹”的对象应是风。"}], "explanations": {"冷风": "语义：“冷风”是寒冷的风，与花开的春日情景不合。", "东风": "正确：“东风”指春风，吹来时百花开放，与句意相合。", "北风": "语义：“北风”多指冬季的寒风，与“花都开了”的春天不符。", "雨": "搭配：“雨”不能说“吹来”，“吹”的对象应是风。"}, "sentence_index": 0, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们都说，东风带来了冬天。", "explanation": "这里应该用〈寒风〉。“东风”指春风，带来的是春天，不能带来冬天。"}, {"text": "人们都说，一只东风带来了春天。", "explanation": "这里应该用〈阵〉。“东风”作量词搭配应用“阵”，不用“只”。"}, {"text": "东风吹过，树叶纷纷落下，秋天到了。", "explanation": "“东风”指春风，应带来暖意和生机；这里说树叶落下、秋天到了，与春风的作用相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒风", "is_correct": false, "explanation": "语义：“寒风”寒冷，与“暖暖的”相矛盾。"}, {"text": "东风", "is_correct": true, "explanation": "正确：“东风”指春风，带来暖意，与“一阵暖暖的”相合。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”是冷的，不能说成“暖暖的雪”。"}, {"text": "冰雹", "is_correct": false, "explanation": "搭配：冰雹是降落的冰块，不能说“吹在脸上”。"}], "explanations": {"寒风": "语义：“寒风”寒冷，与“暖暖的”相矛盾。", "东风": "正确：“东风”指春风，带来暖意，与“一阵暖暖的”相合。", "雪": "语义：“雪”是冷的，不能说成“暖暖的雪”。", "冰雹": "搭配：冰雹是降落的冰块，不能说“吹在脸上”。"}, "sentence_index": 6, "correct_answer": "东风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "东风吹到哪里，哪里的花就都谢了，草木都枯黄了。", "explanation": "“东风”多指温暖的春风，它吹到的地方应是花开草绿；这里说花谢草枯，与春风的意思相反。"}, {"text": "东风一来，河里的冰就冻得更厚了。", "explanation": "“东风”指春风，应使冰化开、春暖回来；这里说冰冻得更厚，与春风的作用相反。"}, {"text": "我家住在东风的南边。", "explanation": "这里应该用〈东边〉。“东风”指春风，是风，不是方位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天的一只东风吹过河面，冰都化了。", "corrected_sentence": "春天的东风吹过河面，冰都化了。", "error_description": "错误形式是“一只东风”，正确形式是“东风”。“东风”作为风，不能用量词“只”，应说“一阵东风”或直接用“春天的东风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早春的一条东风吹绿了河岸。", "corrected_sentence": "早春的东风吹绿了河岸。", "error_description": "错误形式是“一条东风”，正确形式是“东风”（或“一阵东风”）。“东风”是风，不能用量词“条”，“条”用于河流、道路等长条形事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
