INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上分是在游戏里让分数变多、排名往上。", "primary_collocate": null, "pronunciation": "shàng fēn", "ipa": "ʂɑŋ˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "今晚我想和朋友一起打游戏上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都玩游戏，想早点上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个英雄很强，用它上分特别快。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天一直输，今天一定要上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥带我玩了三个小时，终于上分了。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想在排位赛里上分，要多和队友说话。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他不出门，在家打游戏上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的游戏打得好，带我上分吧。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩了一晚上，一点儿也没上分。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新手机玩游戏，上分比以前快多了。", "target_word": "上分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上分了", "label": "体标：了"}, {"form": "上分过", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "游戏中让分数变多、排名上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确答案。“上分”指在游戏里让分数变多、排名上升。"}, {"text": "上坟", "is_correct": false, "explanation": "“坟”与“分”只有第二个音节的声调不同（fén 与 fēn），意思是到墓地祭扫。"}, {"text": "上风", "is_correct": false, "explanation": "“风”与“分”韵母不同（fēng 与 fēn，-ng 与 -n），意思是占优势的位置。"}, {"text": "上粉", "is_correct": false, "explanation": "“粉”与“分”只有声调不同（fěn 与 fēn），意思是在食材或物体表面敷上一层粉。"}], "explanations": {"上分": "正确答案。“上分”指在游戏里让分数变多、排名上升。", "上坟": "“坟”与“分”只有第二个音节的声调不同（fén 与 fēn），意思是到墓地祭扫。", "上风": "“风”与“分”韵母不同（fēng 与 fēn，-ng 与 -n），意思是占优势的位置。", "上粉": "“粉”与“分”只有声调不同（fěn 与 fēn），意思是在食材或物体表面敷上一层粉。"}, "sentence_index": null, "correct_answer": "上分"}, "level_3": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确。“上分”指在游戏里让分数变多，与“打游戏”搭配，符合句意。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”与“和朋友一起打游戏”不能同时进行，句子不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“洗碗”不能与“打游戏”并列作为今晚想做的事，句中动作搭配不合理。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“一起打游戏”的意图相反，句子不通。"}], "explanations": {"上分": "正确。“上分”指在游戏里让分数变多，与“打游戏”搭配，符合句意。", "写作业": "语义：“写作业”与“和朋友一起打游戏”不能同时进行，句子不通。", "洗碗": "搭配：“洗碗”不能与“打游戏”并列作为今晚想做的事，句中动作搭配不合理。", "睡觉": "语义：“睡觉”与“一起打游戏”的意图相反，句子不通。"}, "sentence_index": 0, "correct_answer": "上分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工资上分了两百块。", "explanation": "这里应该用〈涨〉。“上分”只用于游戏里的分数或段位，工资的增加要说“涨”。"}, {"text": "这家店的客流上分了很多。", "explanation": "这里应该用〈增长〉。“上分”只用于游戏里的分数或段位，客流的增加要说“增长”。"}, {"text": "我的体重一直在上分，已经胖了五公斤。", "explanation": "这里应该用〈上升〉。“上分”只用于游戏里的分数或段位，体重的增加要说“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上分", "is_correct": true, "explanation": "正确。“上分”指在游戏里让分数变多，与“在家打游戏”搭配，符合句意。"}, {"text": "逛街", "is_correct": false, "explanation": "搭配：“逛街”需要到外面去，与“在家”的地点不搭配。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”要出门走动，与句中的“不出门”矛盾。"}, {"text": "买菜", "is_correct": false, "explanation": "语义：“买菜”要到外面的市场去，与句中的“不出门”矛盾。"}], "explanations": {"上分": "正确。“上分”指在游戏里让分数变多，与“在家打游戏”搭配，符合句意。", "逛街": "搭配：“逛街”需要到外面去，与“在家”的地点不搭配。", "散步": "语义：“散步”要出门走动，与句中的“不出门”矛盾。", "买菜": "语义：“买菜”要到外面的市场去，与句中的“不出门”矛盾。"}, "sentence_index": 6, "correct_answer": "上分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他练习书法很认真，一个月就上分很多。", "explanation": "这里应该用〈进步〉。“上分”指游戏里的分数或段位上升，书法水平的提高要说“进步”。"}, {"text": "这个月我的收入上分了不少。", "explanation": "这里应该用〈增加〉。“上分”只用于游戏，收入的增加要说“增加”。"}, {"text": "今年的物价上分了很多。", "explanation": "这里应该用〈上涨〉。“上分”指游戏中分数上升，物价的上涨要说“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这局他上分了三十分，排名一下子升了很多。", "corrected_sentence": "这局他上了三十分，排名一下子升了很多。", "error_description": "错误形式“上分了三十分”重复了“分”，“上分”已是动宾结构，不能再接数量词。正确形式是离合用法“上了三十分”，即在“上”和“分”之间插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一晚他上分三分，队友很高兴。", "corrected_sentence": "这一晚他上了三分，队友很高兴。", "error_description": "“上分”本身是动宾结构，后面不能再接数量词“三分”。应说“上了三分”，表示分数上升三分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上去是从下面往上面去。", "primary_collocate": null, "pronunciation": "shàng qù", "ipa": "ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "楼上有人等你，你快上去吧。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上去拿一下书，马上下来。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我们只能从楼梯上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的风景很美，你想上去看看吗？", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在三楼，你可以上去找他。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子搬到屋顶，然后自己也上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台阶很高，我不敢一个人上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在下面等着，我上去看看。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我们不要上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上去叫弟弟吃饭。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上去了", "label": "体标"}, {"form": "上去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "独立作动词，从下面去上面（楼上、山上等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“上去”指从下往上去，楼上有人等你，应往上去。"}, {"text": "下去", "is_correct": false, "explanation": "语义：“下去”指向下去，与“楼上有人等你”的方向相反。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”指向外去，与楼上等人的语境不符。"}, {"text": "下来", "is_correct": false, "explanation": "搭配：“下来”指向说话人一方下行，与“楼上”的位置相冲突。"}], "explanations": {"上去": "正确：“上去”指从下往上去，楼上有人等你，应往上去。", "下去": "语义：“下去”指向下去，与“楼上有人等你”的方向相反。", "出去": "语义：“出去”指向外去，与楼上等人的语境不符。", "下来": "搭配：“下来”指向说话人一方下行，与“楼上”的位置相冲突。"}, "sentence_index": 0, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你上去吧，我在楼上等你。", "explanation": "这里应该用〈上来〉。说话人在楼上，对方应朝说话人所在处移动，用“上来”；“上去”指离开说话人向上去。"}, {"text": "他从楼上走上去，回到了一楼。", "explanation": "这里应该用〈下去〉。从楼上回到一楼是由高向低，应说“下去”；“上去”只表示由低向高。"}, {"text": "我们周末上去海边游泳。", "explanation": "这里应该用〈去〉。海边不是向上的方向，“上去”不用于水平移动的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“上去”指由低往高去，台阶很高，需要往上走。"}, {"text": "跌下去", "is_correct": false, "explanation": "语义：“跌下去”是向下坠落，与“台阶很高，我不敢一个人上去”所描述的向上动作相反。"}, {"text": "摔下去", "is_correct": false, "explanation": "语义：“摔”也指意外跌落，说“不敢摔下去”不合常理。"}, {"text": "停下来", "is_correct": false, "explanation": "搭配：“停下来”指停止，与“一个人”登台阶的语境不搭。"}], "explanations": {"上去": "正确：“上去”指由低往高去，台阶很高，需要往上走。", "跌下去": "语义：“跌下去”是向下坠落，与“台阶很高，我不敢一个人上去”所描述的向上动作相反。", "摔下去": "语义：“摔”也指意外跌落，说“不敢摔下去”不合常理。", "停下来": "搭配：“停下来”指停止，与“一个人”登台阶的语境不搭。"}, "sentence_index": 6, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她上去北京找工作。", "explanation": "这里应该用〈去〉。北京不是高处的目的地，“上去”只用于向上的移动。"}, {"text": "我们上去火车站接人。", "explanation": "这里应该用〈去〉。火车站不在高处，不能用“上去”。"}, {"text": "天气突然冷上去了。", "explanation": "这里应该用〈冷起来〉或〈冷下来〉。“冷”是形容词，不能直接接“上去”表示变冷；“上去”的变化义多指升高，如“涨上去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先把书搬上去去。", "corrected_sentence": "他先把书搬上去。", "error_description": "错误形式「他先把书搬上去去」；正确形式「他先把书搬上去」。「上去」本身已含「去」，后面不能再加一个「去」，多出的「去」应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上去了拿一本书。", "corrected_sentence": "他上去拿了一本书。", "error_description": "“了”应放在动词“拿”之后，说“上去拿了一本书”；“上去了拿”把“了”插在补语和动词之间，不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
