INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt1_core', '{"pos": "方向补语", "semantic_class": "function", "definition": "由低处向高处去。", "primary_collocate": null, "pronunciation": "shàng qù", "ipa": "ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "小猫很快爬上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沿着楼梯跑上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球飞上去了，我拿不到。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她踩着椅子爬上去换灯。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很陡，我们慢慢走上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跳上去坐在大石头上。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把梯子靠好，然后爬上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走不动了，我扶着他走上去。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟一下子飞上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座塔很高，我们一口气爬上去了。", "target_word": "上去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上得去", "label": "可能补语"}, {"form": "上不去", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "放在动词后作方向补语，表示由低处向高处移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“爬上去”表示由低向高的动作，“上去”作方向补语。"}, {"text": "不上去", "is_correct": false, "explanation": "语义：“很快”与否定的“爬不上去”矛盾，句意不通。"}, {"text": "上不去", "is_correct": false, "explanation": "搭配：可能补语的否定形式与“很快”搭配不当。"}, {"text": "不下去", "is_correct": false, "explanation": "语义：“不下去”指无法向下，与句中向上爬的动作相冲突。"}], "explanations": {"上去": "正确：“爬上去”表示由低向高的动作，“上去”作方向补语。", "不上去": "语义：“很快”与否定的“爬不上去”矛盾，句意不通。", "上不去": "搭配：可能补语的否定形式与“很快”搭配不当。", "不下去": "语义：“不下去”指无法向下，与句中向上爬的动作相冲突。"}, "sentence_index": 0, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从山顶爬上去，走到了山脚下。", "explanation": "这里应该用〈下去〉。从山顶到山脚是由高向低，应说“下去”；“上去”只表示由低处向高处。"}, {"text": "小猫爬上去，钻进了草堆里。", "explanation": "这里不能用“上去”。草堆在地面，“爬上去”指向高处，应去掉“上去”，说〈钻进了草堆里〉。"}, {"text": "鱼儿游上去，潜到了河底。", "explanation": "这里应该用〈游下去〉。河底在下方，应由高处向低处去，用“下去”；“上去”表示向高处去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上去", "is_correct": true, "explanation": "正确：“爬上去”指沿梯子向上，与“靠好梯子”的语境一致。"}, {"text": "上不来", "is_correct": false, "explanation": "语义：“上来”指向说话人一方，句中没有这个方向。"}, {"text": "不起来", "is_correct": false, "explanation": "语义：“起来”表示起身，与“靠好梯子”后向上攀爬的语境不符。"}, {"text": "不下来", "is_correct": false, "explanation": "语义：“不下来”指无法向下，与靠好梯子后的攀爬动作不一致。"}], "explanations": {"上去": "正确：“爬上去”指沿梯子向上，与“靠好梯子”的语境一致。", "上不来": "语义：“上来”指向说话人一方，句中没有这个方向。", "不起来": "语义：“起来”表示起身，与“靠好梯子”后向上攀爬的语境不符。", "不下来": "语义：“不下来”指无法向下，与靠好梯子后的攀爬动作不一致。"}, "sentence_index": 6, "correct_answer": "上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把钱包往书包里放上去。", "explanation": "这里应该用〈放进去〉。书包里是容器，东西是放入的，不是向上移动，不能用“上去”。"}, {"text": "他从门口跑上去，到了大门外。", "explanation": "这里应该用〈出去〉。大门外不在高处，“上去”只用于向上的移动。"}, {"text": "他突然跳上去，落到了水里。", "explanation": "这里应该用〈跳下去〉或〈跳进去〉。水在低处，“上去”只表示向高处移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抓着绳子慢慢爬上去去。", "corrected_sentence": "他抓着绳子慢慢爬上去。", "error_description": "错误形式「他抓着绳子慢慢爬上去去」；正确形式「他抓着绳子慢慢爬上去」。「上去」本身已含「去」，后面不能再加一个「去」，多出的「去」应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫咪轻轻跳上去沙发。", "corrected_sentence": "猫咪轻轻跳上沙发。", "error_description": "错误形式「跳上去沙发」；正确形式「跳上沙发」。「上去」是复合趋向补语，不能直接带处所名词，处所须接在「上」后，应说「跳上沙发」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
