INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "主办是自己出头，办好一件大事。", "primary_collocate": null, "pronunciation": "zhǔ bàn", "ipa": "ʈʂu˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这次婚礼，我要自己主办。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人主办了这场大会。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷七十岁生日，儿子决定亲自主办。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的大事，都是老村长主办的。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么大的活动，她一个人也能主办好。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校庆这件大事，由王校长亲自主办。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次主办比赛，有点儿紧张。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想自己主办一场画展。", "target_word": "主办", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁来主办这次同学会？", "target_word": "主办", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司的年会很大，经理决定自己主办。", "target_word": "主办", "complexity_tier": "T3", "furigana": "zhǔ bàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "主办了", "label": "体标"}, {"form": "主办过", "label": "体标"}, {"form": "主办方", "label": "复合"}, {"form": "主办国", "label": "复合"}], "register": "书面", "sense_fingerprint": "亲自出面牵头，把一件大事办好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主办", "is_correct": true, "explanation": "主办（zhǔ bàn）：亲自出面操办大事，是本题的目标词。"}, {"text": "主板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是电脑主板。"}, {"text": "煮饭", "is_correct": false, "explanation": "fàn 与 bàn 声母不同（f 与 b），意思是做饭。"}, {"text": "竹板", "is_correct": false, "explanation": "zhú 与 zhǔ、bǎn 与 bàn 声调都不同，意思是竹制的拍板。"}, {"text": "主犯", "is_correct": false, "explanation": "fàn（第四声）与 bàn 声母不同（f 与 b），意思是主要犯罪人。"}], "explanations": {"主办": "主办（zhǔ bàn）：亲自出面操办大事，是本题的目标词。", "主板": "bǎn（第三声）与 bàn（第四声）声调不同，意思是电脑主板。", "煮饭": "fàn 与 bàn 声母不同（f 与 b），意思是做饭。", "竹板": "zhú 与 zhǔ、bǎn 与 bàn 声调都不同，意思是竹制的拍板。", "主犯": "fàn（第四声）与 bàn 声母不同（f 与 b），意思是主要犯罪人。"}, "sentence_index": null, "correct_answer": "主办"}, "level_3": {"options": [{"text": "主办", "is_correct": true, "explanation": "正确：“我要自己主办”表示亲自出面操办婚礼，与“自己”呼应，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“吃这次婚礼”说不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开、拆除，“拆这次婚礼”与操办婚礼的意思相反。"}, {"text": "报名", "is_correct": false, "explanation": "配价：“报名”不带“婚礼”作宾语，“我要自己报名这次婚礼”不成立。"}], "explanations": {"主办": "正确：“我要自己主办”表示亲自出面操办婚礼，与“自己”呼应，符合语境。", "吃": "搭配：“吃”的宾语应是食物，“吃这次婚礼”说不通。", "拆": "语义：“拆”是拆开、拆除，“拆这次婚礼”与操办婚礼的意思相反。", "报名": "配价：“报名”不带“婚礼”作宾语，“我要自己报名这次婚礼”不成立。"}, "sentence_index": 0, "correct_answer": "主办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在婚礼上主办了节目。", "explanation": "这里应该用〈主持〉。主持指担任节目的主持人；主办指亲自出面操办大事，节目要说“主持”。"}, {"text": "妈妈主办了一封信。", "explanation": "这里应该用〈写〉。主办用于需要统筹的大事，一封信要说“写”。"}, {"text": "工人主办了那座旧桥。", "explanation": "这里应该用〈修〉。主办指组织操办大事，修桥要说“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主办", "is_correct": true, "explanation": "主办（zhǔ bàn）：亲自出面操办大事，是本题的目标词。"}, {"text": "主班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，意思是负责当班的人。"}, {"text": "主判", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是主裁判。"}, {"text": "主宾", "is_correct": false, "explanation": "bīn 与 bàn 韵母及声调都不同，意思是主要的宾客。"}], "explanations": {"主办": "主办（zhǔ bàn）：亲自出面操办大事，是本题的目标词。", "主班": "bān（第一声）与 bàn（第四声）声调不同，意思是负责当班的人。", "主判": "pàn 与 bàn 声母不同（p 与 b），意思是主裁判。", "主宾": "bīn 与 bàn 韵母及声调都不同，意思是主要的宾客。"}, "sentence_index": null, "correct_answer": "主办"}, "level_3": {"options": [{"text": "主办", "is_correct": true, "explanation": "正确：“第一次主办比赛”指他亲自负责办比赛，与“紧张”的语境相合。"}, {"text": "吵", "is_correct": false, "explanation": "搭配：“吵”不带“比赛”作宾语，“吵比赛”不成立。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评比赛”是指责比赛，与“第一次……有点儿紧张”的语境不合。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄坏，“打碎比赛”不合逻辑。"}], "explanations": {"主办": "正确：“第一次主办比赛”指他亲自负责办比赛，与“紧张”的语境相合。", "吵": "搭配：“吵”不带“比赛”作宾语，“吵比赛”不成立。", "批评": "语义：“批评比赛”是指责比赛，与“第一次……有点儿紧张”的语境不合。", "打碎": "语义：“打碎”指弄坏，“打碎比赛”不合逻辑。"}, "sentence_index": 6, "correct_answer": "主办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "演员主办了一段舞蹈。", "explanation": "这里应该用〈表演〉。主办指操办大事，舞蹈是表演，要说“表演”。"}, {"text": "工人主办了整个礼堂。", "explanation": "这里应该用〈打扫〉。主办的对象是活动，礼堂要说“打扫”。"}, {"text": "设计师主办了那座新公园。", "explanation": "这里应该用〈设计〉。主办指组织操办活动，公园的规划要说“设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老村长热热闹闹得主办了这次活动。", "corrected_sentence": "老村长热热闹闹地主办了这次活动。", "error_description": "结构助词错误：动词前的状语要用“地”，“得”用在动词后引出补语。“热热闹闹”修饰“主办”，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老村长决定亲自主办了这件大事。", "corrected_sentence": "老村长决定亲自主办这件大事。", "error_description": "时态标记错误：“决定”的事尚未发生，“了”表示已完成，不能加在“主办”后面。应去掉“了”，说“决定亲自主办这件大事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
