INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责举办（活动、会议等）。", "primary_collocate": null, "pronunciation": "zhǔ bàn", "ipa": "ʈʂu˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛由市政府主办。", "target_word": "主办", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校主办了一场音乐会。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国际会议每年由不同的城市主办。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报社主办的读书活动明天开始。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪家公司主办这次展览？", "target_word": "主办", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国主办过很多大型体育比赛。", "target_word": "主办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生会主办的晚会很受欢迎。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想主办一个小型的图书展。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场新年晚会由电视台主办。", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明年的亚洲运动会将由哪个国家主办？", "target_word": "主办", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "主办了", "label": "体标"}, {"form": "主办过", "label": "体标"}, {"form": "主办方", "label": "复合"}, {"form": "主办国", "label": "复合"}], "register": "书面", "sense_fingerprint": "负责举办活动、会议、比赛等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e668734-d568-4cb3-9908-2c58943e3dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93250, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主办", "is_correct": true, "explanation": "主办（zhǔ bàn）：负责举办活动，是本题的目标词。"}, {"text": "主板", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是电脑主板。"}, {"text": "煮饭", "is_correct": false, "explanation": "fàn 与 bàn 声母不同（f 与 b），意思是做饭。"}, {"text": "竹板", "is_correct": false, "explanation": "zhú 与 zhǔ、bǎn 与 bàn 声调都不同，意思是竹制的拍板。"}, {"text": "主犯", "is_correct": false, "explanation": "fàn（第四声）与 bàn 声母不同（f 与 b），意思是主要犯罪人。"}], "explanations": {"主办": "主办（zhǔ bàn）：负责举办活动，是本题的目标词。", "主板": "bǎn（第三声）与 bàn（第四声）声调不同，意思是电脑主板。", "煮饭": "fàn 与 bàn 声母不同（f 与 b），意思是做饭。", "竹板": "zhú 与 zhǔ、bǎn 与 bàn 声调都不同，意思是竹制的拍板。", "主犯": "fàn（第四声）与 bàn 声母不同（f 与 b），意思是主要犯罪人。"}, "sentence_index": null, "correct_answer": "主办"}, "level_3": {"options": [{"text": "主办", "is_correct": true, "explanation": "正确：主办是动词，指负责举办比赛，填入此处与“市政府”搭配，符合语境。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”需要人作主语，“这次比赛由市政府参加”说不通。"}, {"text": "报名", "is_correct": false, "explanation": "配价：“报名”不带“由”引出的施事，“这次比赛由市政府报名”不成立。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“观看”指看，“由市政府观看这次比赛”与比赛的举办关系不合。"}], "explanations": {"主办": "正确：主办是动词，指负责举办比赛，填入此处与“市政府”搭配，符合语境。", "参加": "搭配：“参加”需要人作主语，“这次比赛由市政府参加”说不通。", "报名": "配价：“报名”不带“由”引出的施事，“这次比赛由市政府报名”不成立。", "观看": "语义：“观看”指看，“由市政府观看这次比赛”与比赛的举办关系不合。"}, "sentence_index": 0, "correct_answer": "主办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校主办了一座新教学楼。", "explanation": "这里应该用〈建〉。主办指负责举办活动、会议等，教学楼是建筑，要说“建”。"}, {"text": "出版社主办了一本新词典。", "explanation": "这里应该用〈出版〉。主办指负责举办活动、会议等；词典是图书，要说“出版”。"}, {"text": "政府主办了一座新大桥。", "explanation": "这里应该用〈修建〉。主办指组织活动，大桥是工程，要说“修建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93250, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主办", "is_correct": true, "explanation": "主办（zhǔ bàn）：负责举办活动，是本题的目标词。"}, {"text": "主班", "is_correct": false, "explanation": "bān（第一声）与 bàn（第四声）声调不同，意思是负责当班的人。"}, {"text": "主判", "is_correct": false, "explanation": "pàn 与 bàn 声母不同（p 与 b），意思是主裁判。"}, {"text": "主宾", "is_correct": false, "explanation": "bīn 与 bàn 韵母及声调都不同，意思是主要的宾客。"}], "explanations": {"主办": "主办（zhǔ bàn）：负责举办活动，是本题的目标词。", "主班": "bān（第一声）与 bàn（第四声）声调不同，意思是负责当班的人。", "主判": "pàn 与 bàn 声母不同（p 与 b），意思是主裁判。", "主宾": "bīn 与 bàn 韵母及声调都不同，意思是主要的宾客。"}, "sentence_index": null, "correct_answer": "主办"}, "level_3": {"options": [{"text": "主办", "is_correct": true, "explanation": "正确：主办修饰“晚会”，指学生会组织晚会，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，“吃的晚会”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：晚会可以举办，但不能说“唱的晚会”。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“学生会批评的晚会很受欢迎”前后矛盾，不合语境。"}], "explanations": {"主办": "正确：主办修饰“晚会”，指学生会组织晚会，符合语境。", "吃": "搭配：“吃”的宾语是食物，“吃的晚会”说不通。", "唱": "搭配：晚会可以举办，但不能说“唱的晚会”。", "批评": "语义：“学生会批评的晚会很受欢迎”前后矛盾，不合语境。"}, "sentence_index": 6, "correct_answer": "主办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在晚会上主办了三个节目。", "explanation": "这里应该用〈主持〉。主持指担任节目的主持人；主办指组织、承办整场活动，不能说“主办节目”。"}, {"text": "她主办了一份调查报告。", "explanation": "这里应该用〈撰写〉。主办用于活动、会议、比赛，报告是文字作品，要说“撰写”。"}, {"text": "代表团主办了那个国家。", "explanation": "这里应该用〈访问〉。主办的对象是活动，国家不能被“主办”，要说“访问”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次运动会由学校主办了过。", "corrected_sentence": "这次运动会由学校主办。", "error_description": "体标错误：“了”和“过”不能同时用在“主办”后面。这里是普通陈述，应删去“了过”，写作“由学校主办”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校想不主办这次晚会。", "corrected_sentence": "学校不想主办这次晚会。", "error_description": "否定词位置错误：“不想”的“不”要放在能愿动词“想”前面，不能说“想不”。应改为“不想主办”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd96073-efe9-44ec-8aa9-3667c3d6b00d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
