INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装有弹性衬垫的、可供多人坐靠的软座椅。", "primary_collocate": null, "pronunciation": "shā fā", "ipa": "ʂa˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这张三人沙发可以坐三个人。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们都坐在长沙发上聊天。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发里的弹簧坏了，坐着不舒服。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的皮沙发又软又舒服。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙发上靠着说话。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一套布沙发放在客厅。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套沙发的垫子可以拿下来洗。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人靠在沙发上休息。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太小，放不下大沙发。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发的颜色和墙很配。", "target_word": "沙发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "沙發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有弹性垫子、可供多人坐靠的软座椅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae11fc9-8d91-4ac8-9ade-c3aa73eb42d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：可供多人坐靠的软座椅，“三人沙发”说法正确。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是纸张，不能坐人。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是平面的纸，不能坐三个人。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：车票不说“三人”，也不能坐人。"}], "explanations": {"沙发": "沙发：可供多人坐靠的软座椅，“三人沙发”说法正确。", "报纸": "语义：报纸是纸张，不能坐人。", "地图": "语义：地图是平面的纸，不能坐三个人。", "车票": "搭配：车票不说“三人”，也不能坐人。"}, "sentence_index": 0, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家阳台上放着一只布沙发。", "explanation": "这里应该用〈张〉或〈套〉。“只”用于动物，沙发不能这样数。"}, {"text": "我们新买了一台大沙发。", "explanation": "这里应该用〈张〉或〈套〉。“台”用于机器、电器，不用于沙发。"}, {"text": "客厅里摆着一条旧沙发。", "explanation": "这里应该用〈张〉或〈套〉。“条”用于细长的东西，沙发不这么数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": true, "explanation": "沙发：带有可拆垫子的软座椅，符合“垫子可以拿下来洗”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有垫子，不能说“这套书的垫子”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，没有可以拿下来洗的垫子。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本没有可以拿下来洗的垫子。"}], "explanations": {"沙发": "沙发：带有可拆垫子的软座椅，符合“垫子可以拿下来洗”。", "书": "语义：书没有垫子，不能说“这套书的垫子”。", "冰箱": "语义：冰箱是电器，没有可以拿下来洗的垫子。", "课本": "语义：课本没有可以拿下来洗的垫子。"}, "sentence_index": 6, "correct_answer": "沙发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发可以放菜，当餐桌用。", "explanation": "这里把“沙发”当成了摆菜吃饭的平台来用。沙发是供人坐靠的软座椅，不能用来摆菜。"}, {"text": "这张沙发能发光，晚上当灯用。", "explanation": "这里把“沙发”说成了能发光照明的东西。沙发是软座椅，不会发光，与它供人坐靠的用途不符。"}, {"text": "这张沙发可以打开，当门用。", "explanation": "这里把“沙发”说成了能开合、供人出入的东西。沙发不能开合，与它供人坐靠的用途不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一只新沙发。", "corrected_sentence": "我想买一套新沙发。", "error_description": "量词错误：“一只”应为“一套”。“只”用于动物，沙发的量词是“张”或“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一只沙发擦干净了。", "corrected_sentence": "妈妈把一张沙发擦干净了。", "error_description": "量词错误：“一只”应为“一张”。沙发的量词是“张”或“套”，“只”用于动物，不能用来数沙发。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普遍", "is_correct": true, "explanation": "“普遍”与“个别”构成反义：个别指少数，普遍指涉及大多数的范围。"}, {"text": "重要", "is_correct": false, "explanation": "与“个别”没有反义关系，“重要”形容价值，与数量含义不对应。"}, {"text": "清楚", "is_correct": false, "explanation": "与“个别”没有反义关系，“清楚”形容明晰的程度。"}, {"text": "高大", "is_correct": false, "explanation": "与“个别”没有反义关系，“高大”形容体型。"}], "correct_answer": "普遍", "explanations": {"普遍": "“普遍”与“个别”构成反义：个别指少数，普遍指涉及大多数的范围。", "重要": "与“个别”没有反义关系，“重要”形容价值，与数量含义不对应。", "清楚": "与“个别”没有反义关系，“清楚”形容明晰的程度。", "高大": "与“个别”没有反义关系，“高大”形容体型。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普遍", "is_correct": true, "explanation": "“普遍”与“个别”构成反义：个别指少数，普遍指涉及大多数的范围。"}, {"text": "美丽", "is_correct": false, "explanation": "与“个别”没有反义关系，“美丽”形容外观的好看。"}, {"text": "干净", "is_correct": false, "explanation": "与“个别”没有反义关系，“干净”形容整洁的状态。"}, {"text": "简单", "is_correct": false, "explanation": "与“个别”没有反义关系，“简单”形容难度或结构。"}], "correct_answer": "普遍", "explanations": {"普遍": "“普遍”与“个别”构成反义：个别指少数，普遍指涉及大多数的范围。", "美丽": "与“个别”没有反义关系，“美丽”形容外观的好看。", "干净": "与“个别”没有反义关系，“干净”形容整洁的状态。", "简单": "与“个别”没有反义关系，“简单”形容难度或结构。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "个别是只有一两个，不是大多数。", "primary_collocate": null, "pronunciation": "gè bié", "ipa": "kɤ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "班里只有个别学生没带书。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别同学今天迟到了。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜都很好吃，只有个别太咸。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别人不喜欢这个办法，大多数人都同意。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是个别现象，不用太担心。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班都交了作业，只有个别人没交。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别地方下雨，大部分地方天气很好。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果大多很新鲜，个别有点坏了。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个别老人不会用手机，多数人都会。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里只有个别人知道这件事。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "极少数；只有一两个，不是大多数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”指只有少数，与“只有”相符，句意通顺。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，与“只有”所限定的少数矛盾。"}, {"text": "大量", "is_correct": false, "explanation": "语义：“大量”说数量多，与“只有”的少数语境矛盾。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容温度或气候，不能修饰“学生”。"}], "explanations": {"个别": "“个别”指只有少数，与“只有”相符，句意通顺。", "全部": "语义：“全部”指全体，与“只有”所限定的少数矛盾。", "大量": "语义：“大量”说数量多，与“只有”的少数语境矛盾。", "寒冷": "搭配：“寒冷”形容温度或气候，不能修饰“学生”。"}, "sentence_index": 0, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的个别人口很多。", "explanation": "这里应该用〈总〉。个别只表示单个或极少数，不能修饰整体的人口数量，与“很多”也互相矛盾。"}, {"text": "他每天只喝个别的水。", "explanation": "这里应该用〈少量〉。个别只指单个或极少数的人或事物，不能用来说水的份量。"}, {"text": "班里个别同学都交了作业。", "explanation": "这里应该用〈全部〉。个别只表示只有一两个，与“都”表示全体相矛盾，不能用来说全班同学都交了作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”指少数地方，与“大部分”形成对比，句意通顺。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”指全部，与“大部分”的说法矛盾。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”指天气好，与“下雨”矛盾。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度或触感，不能用来表示地方的范围。"}], "explanations": {"个别": "“个别”指少数地方，与“大部分”形成对比，句意通顺。", "整个": "语义：“整个”指全部，与“大部分”的说法矛盾。", "晴朗": "语义：“晴朗”指天气好，与“下雨”矛盾。", "冰冷": "搭配：“冰冷”形容温度或触感，不能用来表示地方的范围。"}, "sentence_index": 6, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的个别同学都考了满分。", "explanation": "这里应该用〈全体〉。个别只表示只有一两个，与“都”表示全体相矛盾，不能用来说全班同学都考了满分。"}, {"text": "我只有个别钱了。", "explanation": "这里应该用〈一点〉。个别指单个或极少数，不能用来说钱的多少。"}, {"text": "这个学校的个别学生有一千多人。", "explanation": "这里应该用〈全体〉。个别只表示只有一两个，与“一千多人”的规模相矛盾，应说“全体学生有一千多人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只有很个别同学没交作业。", "corrected_sentence": "只有个别同学没交作业。", "error_description": "错误在“很”：“个别”只用来修饰名词，不能受程度副词“很”修饰，应说“只有个别同学……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次检查只发现个别了问题。", "corrected_sentence": "这次检查只发现个别问题。", "error_description": "错误在体标：“了”不能插在“个别”和名词之间，“个别”修饰名词时后面直接接名词，应说“只发现个别问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
