INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93254, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "单独地、一个一个地进行（如个别辅导、个别谈话）。", "primary_collocate": null, "pronunciation": "gè bié", "ipa": "kɤ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "老师找小明个别谈话。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生需要个别辅导。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对每个病人个别检查。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要个别对待每个孩子。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理个别找了几个人谈话。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题要个别处理，不能一起办。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以后，老师个别指导了他。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的问题比较特别，我们个别解决吧。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给他安排了个别辅导。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家先开会，有事再个别说。", "target_word": "个别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单个的；一个一个地单独进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”修饰“谈话”，指一对一地单独谈，与句意相符。"}, {"text": "集体", "is_correct": false, "explanation": "语义：“集体”指多人一起，与“找小明”只涉及一人矛盾。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：“精美”形容物品，不能修饰“谈话”。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，与“小明”只涉及一人的语境矛盾。"}], "explanations": {"个别": "“个别”修饰“谈话”，指一对一地单独谈，与句意相符。", "集体": "语义：“集体”指多人一起，与“找小明”只涉及一人矛盾。", "精美": "搭配：“精美”形容物品，不能修饰“谈话”。", "全部": "语义：“全部”指全体，与“小明”只涉及一人的语境矛盾。"}, "sentence_index": 0, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班个别同学都交了作业。", "explanation": "这里应该用〈全部〉。个别表示单独、一个一个地进行，与“都”所表示的全体相矛盾，不能用来说全班都交了作业。"}, {"text": "我们个别一起开了一次大会。", "explanation": "这里应该用〈一起〉。个别表示单独进行，与“一起开会”的集体形式相矛盾。"}, {"text": "我们只放个别的盐。", "explanation": "这里应该用〈少量〉。个别只指单个或极少数的人或事物，不能用来说盐的份量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个别", "is_correct": true, "explanation": "“个别”修饰“指导”，指单独地一对一指导，符合句意。"}, {"text": "众多", "is_correct": false, "explanation": "语义：“众多”指数量多，与“指导了他”只针对一人矛盾。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能修饰“指导”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，与“指导”搭配不通。"}], "explanations": {"个别": "“个别”修饰“指导”，指单独地一对一指导，符合句意。", "众多": "语义：“众多”指数量多，与“指导了他”只针对一人矛盾。", "鲜艳": "搭配：“鲜艳”形容颜色，不能修饰“指导”。", "雪白": "搭配：“雪白”形容颜色，与“指导”搭配不通。"}, "sentence_index": 6, "correct_answer": "个别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题个别人都懂。", "explanation": "这里应该用〈大家〉。个别只表示单个或极少数，与“都”搭配表示全体时自相矛盾，应说“大家都懂”。"}, {"text": "大家个别一起吃了晚饭。", "explanation": "这里应该用〈一起〉。个别表示单独进行，与“大家”的集体行动相矛盾。"}, {"text": "他是一名个别工人。", "explanation": "这里应该用〈普通〉。个别强调单个或少数，不能用来描述一般身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长很个别找每位班主任谈话。", "corrected_sentence": "校长个别找每位班主任谈话。", "error_description": "错误在“很”：“个别”不能受“很”修饰，应直接放在动词前作状语，说“校长个别找……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师个别的约谈了每位学生。", "corrected_sentence": "老师个别约谈了每位学生。", "error_description": "错误在“的”：“个别”作状语修饰动词“约谈”时后面不加“的”，应说“老师个别约谈了每位学生”，不能说“个别的约谈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
