INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去的事情。", "primary_collocate": null, "pronunciation": "qián shì", "ipa": "tɕʰjɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "别再想前事了，好好过今天吧。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常对孩子们讲前事。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想谈前事，只想谈以后。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些前事，我早就忘了。", "target_word": "前事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过这次谈话，两人不再计较前事。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻开旧相册，想起了许多前事。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前事就让它过去吧，你不必太难过。", "target_word": "前事", "complexity_tier": "T3", "furigana": "qián shì jiù ràng tā guò qù ba, nǐ bú bì tài nán guò。", "sentence_source": "generated"}, {"text": "王老师说，前事要记住，路要向前走。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把前事告诉了新同事。", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总想着前事呢？", "target_word": "前事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "过去的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93258, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确答案：前事（qián shì），指过去的事情。"}, {"text": "前史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是前代的历史。"}, {"text": "强势", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），意思是强硬、有气势。"}, {"text": "闲事", "is_correct": false, "explanation": "xián 与 qián 声母不同（x 与 q），意思是与自己无关的事。"}, {"text": "前十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是排在前面的十个。"}], "explanations": {"前事": "正确答案：前事（qián shì），指过去的事情。", "前史": "shǐ（第三声）与 shì（第四声）声调不同，意思是前代的历史。", "强势": "qiáng 与 qián 韵母不同（ang 与 an），意思是强硬、有气势。", "闲事": "xián 与 qián 声母不同（x 与 q），意思是与自己无关的事。", "前十": "shí（第二声）与 shì（第四声）声调不同，意思是排在前面的十个。"}, "sentence_index": null, "correct_answer": "前事"}, "level_3": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确：“前事”指过去的事情，与“别再想”“好好过今天”的语境相合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“想”后接的是心里的念头或往事，不接“窗户”这类具体物件。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是具体的自然景物，不是可以回想的对象，与“别再想”不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“想”后接的是心里的念头或往事，不接“石头”这类具体物件。"}], "explanations": {"前事": "正确：“前事”指过去的事情，与“别再想”“好好过今天”的语境相合。", "窗户": "搭配：“想”后接的是心里的念头或往事，不接“窗户”这类具体物件。", "天空": "语义：“天空”是具体的自然景物，不是可以回想的对象，与“别再想”不合。", "石头": "搭配：“想”后接的是心里的念头或往事，不接“石头”这类具体物件。"}, "sentence_index": 0, "correct_answer": "前事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的前事很远大，老师都很看好他。", "explanation": "这里应该用〈前程〉。前程指将来的事业和发展，前事指过去的事情，二者时间方向相反。"}, {"text": "做这件事，安全是最重要的前事。", "explanation": "这里应该用〈前提〉。前提指事情成立必须先满足的条件，前事指过去的事情，此处表示条件，不能用前事。"}, {"text": "这家公司的前事很好，很多人都想来工作。", "explanation": "这里应该用〈前景〉。前景指将来的发展趋势，前事指过去的事情，不能用来说公司的发展方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93258, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确答案：前事（qián shì），指过去的事情。"}, {"text": "情势", "is_correct": false, "explanation": "qíng 与 qián 韵母不同（ing 与 an），意思是形势、局势。"}, {"text": "年事", "is_correct": false, "explanation": "nián 与 qián 声母不同（n 与 q），意思是年纪、岁数。"}, {"text": "浅视", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是目光短浅。"}, {"text": "前志", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是先前的志向。"}], "explanations": {"前事": "正确答案：前事（qián shì），指过去的事情。", "情势": "qíng 与 qián 韵母不同（ing 与 an），意思是形势、局势。", "年事": "nián 与 qián 声母不同（n 与 q），意思是年纪、岁数。", "浅视": "qiǎn（第三声）与 qián（第二声）声调不同，意思是目光短浅。", "前志": "zhì 与 shì 声母不同（zh 与 sh），意思是先前的志向。"}, "sentence_index": null, "correct_answer": "前事"}, "level_3": {"options": [{"text": "前事", "is_correct": true, "explanation": "正确：“前事”指过去的事情，与“让它过去”“不必太难过”的语境相合。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”还没有到，不能说“让它过去”。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“让它过去”用于事情或情绪，不用于“树木”这类具体事物。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“让它过去”用于事情或情绪，不用于“草地”这类具体事物。"}], "explanations": {"前事": "正确：“前事”指过去的事情，与“让它过去”“不必太难过”的语境相合。", "未来": "语义：“未来”还没有到，不能说“让它过去”。", "树木": "搭配：“让它过去”用于事情或情绪，不用于“树木”这类具体事物。", "草地": "搭配：“让它过去”用于事情或情绪，不用于“草地”这类具体事物。"}, "sentence_index": 6, "correct_answer": "前事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她担任学生会前事已经两年了。", "explanation": "这里应该用〈主席〉。主席指组织或会议的领导人，前事指以前发生的事，不能用来指担任的职务。"}, {"text": "他是这场比赛的前事。", "explanation": "这里应该用〈裁判〉。裁判指主持比赛、判定胜负的人，前事指以前发生的事，不能用来指人的身份。"}, {"text": "他是球队的前事，大家都很听他的。", "explanation": "这里应该用〈队长〉。队长指一支队伍的负责人，前事指以前发生的事，不能用来指人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一座前事讲给了新同事。", "corrected_sentence": "他把一件前事讲给了新同事。", "error_description": "量词错误：“前事”应用量词“件”，说“一件前事”；“座”用于山、房屋等大型固定物，不能用来计量“前事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从不跟别人很谈前事，只顾着往前走。", "corrected_sentence": "她从不跟别人谈前事，只顾着往前走。", "error_description": "错误：“很”是程度副词，不能放在动词“谈”前面；应去掉“很”，说“跟别人谈前事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
