INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "湖泊是陆地上一大片水，四周是岸。", "primary_collocate": null, "pronunciation": "hú pō", "ipa": "xu˧˥ pʰo˥˥", "syllable_count": 2, "sentences": [{"text": "我家后面有一个美丽的湖泊。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖泊四周都是山和树。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很多人在湖泊里游泳。", "target_word": "湖泊", "complexity_tier": "T3", "furigana": "húpō", "sentence_source": "generated"}, {"text": "这个湖泊里有不少鱼。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖泊的岸边有一条小路。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐船游览了整个湖泊。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的蓝色地方是湖泊。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的湖泊安静又漂亮。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在湖泊边玩水。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖泊的水是咸的。", "target_word": "湖泊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "陆地上一大片水，四周是岸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae11fc9-8d91-4ac8-9ade-c3aa73eb42d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哲学", "is_correct": false, "explanation": "搭配：“哲学”是抽象的学问，不能说“家后面有一个美丽的哲学”"}, {"text": "湖泊", "is_correct": true, "explanation": "湖泊：陆地上的一大片水，可以位于家后面，也可以很美丽"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是室内家电，不会出现在家后面的景观里"}, {"text": "星球", "is_correct": false, "explanation": "语义：“星球”是天体，不会位于我家后面的地上"}], "explanations": {"哲学": "搭配：“哲学”是抽象的学问，不能说“家后面有一个美丽的哲学”", "湖泊": "湖泊：陆地上的一大片水，可以位于家后面，也可以很美丽", "冰箱": "语义：“冰箱”是室内家电，不会出现在家后面的景观里", "星球": "语义：“星球”是天体，不会位于我家后面的地上"}, "sentence_index": 0, "correct_answer": "湖泊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖泊今天考试得了一百分。", "explanation": "这里应该用〈学生〉。学生会考试、得分；湖泊不参加考试。"}, {"text": "这个湖泊很烫，要慢慢喝。", "explanation": "这里应该用〈茶〉。茶是端起来慢慢喝的饮品；湖泊是天然水域，不能这样喝。"}, {"text": "这个湖泊很重，我提不动。", "explanation": "这里应该用〈水桶〉。水桶是可以提起的容器，装满水会很重；湖泊是大片水域，不能提起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山脉", "is_correct": false, "explanation": "语义：“山脉”是陆地上的山地，不是蓝色的水域"}, {"text": "森林", "is_correct": false, "explanation": "搭配：森林在地图上多用绿色表示，“蓝色”与“森林”搭配不对"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：“沙漠”是干燥的沙地，地图上通常不是蓝色"}, {"text": "湖泊", "is_correct": true, "explanation": "湖泊：地图上常用蓝色表示的水域，与句意相符"}], "explanations": {"山脉": "语义：“山脉”是陆地上的山地，不是蓝色的水域", "森林": "搭配：森林在地图上多用绿色表示，“蓝色”与“森林”搭配不对", "沙漠": "语义：“沙漠”是干燥的沙地，地图上通常不是蓝色", "湖泊": "湖泊：地图上常用蓝色表示的水域，与句意相符"}, "sentence_index": 6, "correct_answer": "湖泊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖泊的枝叶很茂盛，夏天能遮住阳光。", "explanation": "这里应该用〈大树〉。大树有枝叶可以遮阳；湖泊是大片水域，没有枝叶。"}, {"text": "湖泊从石缝里涌出来，清澈见底。", "explanation": "这里应该用〈泉水〉。泉水是从地下涌出的水，湖泊不会从石缝里涌出来"}, {"text": "湖泊顺着屋檐流下来。", "explanation": "这里应该用〈雨水〉。雨水是从天上落下的水，湖泊不会顺着屋檐流下来"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们湖泊边捡了一些石头。", "corrected_sentence": "孩子们在湖泊边捡了一些石头。", "error_description": "“湖泊边”表示地点，前面要用介词“在”引出，漏掉“在”后句子不通。正确说法：孩子们在湖泊边捡了一些石头。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在一棵湖泊边玩水。", "corrected_sentence": "孩子们在一个湖泊边玩水。", "error_description": "“湖泊”前应用量词“个”或“片”，“棵”用于树木，不能用来数湖泊。正确说法：孩子们在一个湖泊边玩水。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
