INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93261, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "前来是到这里来。", "primary_collocate": null, "pronunciation": "qián lái", "ipa": "tɕʰjɛn˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "欢迎各位前来参加我们的晚会。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人前来看望生病的老师。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢大家前来参加我的婚礼。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从很远的地方前来向我们请教。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有事请前来办公室找我。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你病了，朋友们都前来看你。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们前来采访这位老人。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前来买票的人已经很多了。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人前来拜访时，我正在做饭。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢专家前来给我们讲课。", "target_word": "前来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前来了", "label": "体标"}, {"form": "前来过", "label": "体标"}, {"form": "前來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人朝说话人所在的地方来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“欢迎”的态度相反，不能用来表示来参加晚会。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点，不能说游览晚会。"}, {"text": "前来", "is_correct": true, "explanation": "前来：朝说话人所在的地方来，与“欢迎各位”和“参加”搭配。"}, {"text": "退出", "is_correct": false, "explanation": "语义：“退出”是离开某项活动，与欢迎参加的意思相反。"}], "explanations": {"逃避": "语义：“逃避”与“欢迎”的态度相反，不能用来表示来参加晚会。", "游览": "搭配：“游览”的对象是景点，不能说游览晚会。", "前来": "前来：朝说话人所在的地方来，与“欢迎各位”和“参加”搭配。", "退出": "语义：“退出”是离开某项活动，与欢迎参加的意思相反。"}, "sentence_index": 0, "correct_answer": "前来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我住在北京，他前来伦敦留学。", "explanation": "这里应该用〈前往〉。前来表示朝说话人所在的地方来，说话人在北京，去伦敦要用前往。"}, {"text": "我住在北京，我们下周前来上海旅行。", "explanation": "这里应该用〈去〉。前来的终点是说话人所在的地方，说话人在北京，去上海应说去。"}, {"text": "我住在北京，妈妈明天前来天津做客。", "explanation": "这里应该用〈到〉。前来须以说话人所在处为终点，说话人在北京，去天津应用到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”表示赶走，与“采访”的行为目的相悖。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物等物体，不能用于采访这一行为。"}, {"text": "前来", "is_correct": true, "explanation": "前来：朝说话人所在的地方来，与“记者们”和“采访”搭配。"}, {"text": "辱骂", "is_correct": false, "explanation": "语义：“辱骂”表示侮辱，与正常的采访行为不符。"}], "explanations": {"驱逐": "语义：“驱逐”表示赶走，与“采访”的行为目的相悖。", "搬运": "搭配：“搬运”的对象是货物等物体，不能用于采访这一行为。", "前来": "前来：朝说话人所在的地方来，与“记者们”和“采访”搭配。", "辱骂": "语义：“辱骂”表示侮辱，与正常的采访行为不符。"}, "sentence_index": 6, "correct_answer": "前来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在北京，他明天前来故乡探亲。", "explanation": "这里应该用〈返回〉。前来的终点是说话人所在地，说话人在北京，回故乡要用返回。"}, {"text": "我在北京，他决定前来西藏支教。", "explanation": "这里应该用〈奔赴〉。前来的终点是说话人所在地，说话人在北京，赴西藏支教要用奔赴。"}, {"text": "我在北京，他下周前来纽约开会。", "explanation": "这里应该用〈飞往〉。前来的终点是说话人所在地，说话人在北京，去纽约要用飞往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前来老师们参加我们的会议。", "corrected_sentence": "前来的老师们参加我们的会议。", "error_description": "错误形式：“前来老师们”，作定语的“前来”后漏掉了“的”。正确形式：“前来的老师们”。原因：“前来”修饰名词时须加“的”，否则结构不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天老师们前来了参加会议。", "corrected_sentence": "明天老师们前来参加会议。", "error_description": "错误形式：“前来了”。正确形式：“前来”。原因：“明天”指将来，句中的动作未完成，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
