INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生育是妈妈生下小宝宝。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "她三十岁时生育了第一个孩子。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人现在不想生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她还能生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育孩子需要很多钱。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生育以后就辞职在家带孩子。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育前，她每周都去医院检查。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这家医院生育了双胞胎。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生育我的时候很辛苦。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女性生育后要好好休息。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想太早生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育了", "label": "体标"}, {"form": "生育过", "label": "体标"}], "register": "中性", "sense_fingerprint": "女性生下孩子这一具体行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是女性生下孩子。"}, {"text": "生鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, {"text": "剩余", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是女性生下孩子。", "生鱼": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。", "剩余": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“她三十岁时生育了第一个孩子”说的是她生下第一个孩子。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是人自己降生，不能带“孩子”作宾语。"}, {"text": "长大", "is_correct": false, "explanation": "配价：“长大”是不及物动词，后面不能带“第一个孩子”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，不能用来指生孩子。"}], "explanations": {"生育": "正确。“她三十岁时生育了第一个孩子”说的是她生下第一个孩子。", "出生": "配价：“出生”是人自己降生，不能带“孩子”作宾语。", "长大": "配价：“长大”是不及物动词，后面不能带“第一个孩子”。", "吃": "语义：“吃”指吃东西，不能用来指生孩子。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天生育上千辆汽车。", "explanation": "这里应该用〈生产〉。“生育”只用于人或动物生孩子，工厂制造汽车要用“生产”。"}, {"text": "他是1990年在北京生育的。", "explanation": "这里应该用〈出生〉。“生育”要以子女为对象，表示人自己降生要用“出生”。"}, {"text": "这家公司生育了很多员工。", "explanation": "这里应该用〈招聘〉。“生育”的对象是子女，公司招收员工要用“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是女性生下孩子。"}, {"text": "省域", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。"}, {"text": "盛誉", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是女性生下孩子。", "省域": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。", "盛誉": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“她在这家医院生育了双胞胎”说的是她在医院生下双胞胎。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：“挂号”是为看病登记，不能带“双胞胎”作宾语。"}, {"text": "住院", "is_correct": false, "explanation": "配价：“住院”是不及物动词，后面不能带宾语。"}, {"text": "出院", "is_correct": false, "explanation": "配价：“出院”是不及物动词，后面不能带宾语。"}], "explanations": {"生育": "正确。“她在这家医院生育了双胞胎”说的是她在医院生下双胞胎。", "挂号": "语义：“挂号”是为看病登记，不能带“双胞胎”作宾语。", "住院": "配价：“住院”是不及物动词，后面不能带宾语。", "出院": "配价：“出院”是不及物动词，后面不能带宾语。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院生育了很多病人。", "explanation": "这里应该用〈收治〉。医院接收病人要用“收治”，“生育”的对象是子女，不能用于病人。"}, {"text": "研究所生育了新的药物。", "explanation": "这里应该用〈研发〉。新药的开发要用“研发”，“生育”只指生孩子、繁衍后代。"}, {"text": "农学家生育了新的水稻品种。", "explanation": "这里应该用〈培育〉。培育新品种要用“培育”，“生育”不用于植物品种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她二十八岁时没生育了第一个孩子。", "corrected_sentence": "她二十八岁时生育了第一个孩子。", "error_description": "否定词错误。“没”与“了”不能同用：“没生育了”不成立。这里说的是已经发生的事，应去掉“没”，说“生育了第一个孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这家医院了生育一对双胞胎。", "corrected_sentence": "她在这家医院生育一对双胞胎。", "error_description": "“了”的位置错误。“了”不能放在动词“生育”之前，“了生育”不成立；这里应删去多余的“了”，说“生育一对双胞胎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
