INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生孩子；繁衍后代。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "生育是人类繁衍后代的方式。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的生育季节一般在春天。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想帮助家庭解决生育的困难。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育对一个家庭来说是大事。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都在讨论生育问题。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生育带来的责任很重。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定先工作，再考虑生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司支持员工生育，还给了假期。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫很难生育。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈人觉得生育越多越好。", "target_word": "生育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生育了", "label": "体标"}, {"form": "生育过", "label": "体标"}], "register": "中性", "sense_fingerprint": "泛指生孩子、繁衍后代这一社会和生物现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是生孩子、繁衍后代。"}, {"text": "生鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, {"text": "剩余", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是生孩子、繁衍后代。", "生鱼": "yú（第二声）与 yù（第四声）声调不同，意思是没有煮熟的鱼。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。", "剩余": "shèng（第四声）与 shēng（第一声）、yú（第二声）与 yù（第四声）声调都不同，意思是剩下的部分。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“生育是人类繁衍后代的方式”中，“生育”作主语，指生孩子这一行为。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与繁衍后代无关，句子意思不通。"}, {"text": "成长", "is_correct": false, "explanation": "语义：“成长”指长大，不是繁衍后代的方式。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不能作“繁衍后代的方式”的主语。"}], "explanations": {"生育": "正确。“生育是人类繁衍后代的方式”中，“生育”作主语，指生孩子这一行为。", "生病": "语义：“生病”与繁衍后代无关，句子意思不通。", "成长": "语义：“成长”指长大，不是繁衍后代的方式。", "吃饭": "搭配：“吃饭”不能作“繁衍后代的方式”的主语。"}, "sentence_index": 0, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场每年生育大量鸡蛋。", "explanation": "这里应该用〈生产〉。“生育”指生孩子、繁衍后代，鸡蛋是产品，要用“生产”。"}, {"text": "这棵小树生育得很快。", "explanation": "这里应该用〈生长〉。树木长得快要用“生长”，“生育”只指人或动物繁衍后代。"}, {"text": "学校生育了很多人才。", "explanation": "这里应该用〈培养〉。培养人才要用“培养”，“生育”指生孩子、繁衍后代，不能用于人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确：生育（shēng yù），意思是生孩子、繁衍后代。"}, {"text": "省域", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。"}, {"text": "盛誉", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}], "explanations": {"生育": "正确：生育（shēng yù），意思是生孩子、繁衍后代。", "省域": "shěng（第三声）与 shēng（第一声）声调不同，意思是省的范围。", "盛誉": "shèng（第四声）与 shēng（第一声）声调不同，意思是很高的声望。", "生意": "yì（第四声）与 yù（第四声）韵母不同（i 与 ü），意思是买卖、生意。"}, "sentence_index": null, "correct_answer": "生育"}, "level_3": {"options": [{"text": "生育", "is_correct": true, "explanation": "正确。“再考虑生育”说的是考虑要不要生孩子。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是本能，不是可以“考虑”的行为。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是可以“考虑”的事情，句子不通。"}, {"text": "眨眼", "is_correct": false, "explanation": "搭配：“考虑”不能与“眨眼”这类本能动作搭配。"}], "explanations": {"生育": "正确。“再考虑生育”说的是考虑要不要生孩子。", "呼吸": "语义：呼吸是本能，不是可以“考虑”的行为。", "咳嗽": "语义：咳嗽不是可以“考虑”的事情，句子不通。", "眨眼": "搭配：“考虑”不能与“眨眼”这类本能动作搭配。"}, "sentence_index": 6, "correct_answer": "生育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器每天生育上百个零件。", "explanation": "这里应该用〈生产〉。机器制造零件要用“生产”，“生育”只指人或动物生孩子、繁衍后代。"}, {"text": "她生育在一个农村家庭。", "explanation": "这里应该用〈出生〉。表示人降生要用“出生”，“生育”指生孩子，不能用于本人出生。"}, {"text": "这个城市生育了许多名人。", "explanation": "这里应该用〈涌现〉。人才大量出现要用“涌现”，“生育”只能指生孩子，不能说“生育名人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "生育了是人类延续后代的重要方式。", "corrected_sentence": "生育是人类延续后代的重要方式。", "error_description": "“了”的位置错误。“生育”作主语时后面不能带“了”，应说“生育是……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会应该支持女性很生育。", "corrected_sentence": "社会应该支持女性生育。", "error_description": "副词错误。“很”是程度副词，不能直接修饰动词“生育”，“很生育”不成立；应去掉“很”，说“支持女性生育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
