INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留给是把东西放着，给别人。", "primary_collocate": null, "pronunciation": "liú gěi", "ipa": "ljoʊ˧˥ keɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈把最后一块蛋糕留给了我。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个座位留给老人。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把好吃的都留给弟弟。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的饭是留给你的。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把最后一张票留给我朋友。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把大房间留给了奶奶。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一半苹果留给小狗。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果是留给客人的。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把周末的时间留给家人。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一碗汤，是留给爸爸的。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留给了", "label": "体标"}, {"form": "留给过", "label": "体标"}], "register": "中性", "sense_fingerprint": "留给：把东西先放着不用，给某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留给", "is_correct": true, "explanation": "正确：“留给”表示把东西留着交给某人，与“把最后一块蛋糕……了我”相符。"}, {"text": "留下", "is_correct": false, "explanation": "配价：“留下”不带“我”作接受者，不能说“留下了我”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与把蛋糕交给我的意思不合。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是分割，不表示把东西交给某人。"}], "explanations": {"留给": "正确：“留给”表示把东西留着交给某人，与“把最后一块蛋糕……了我”相符。", "留下": "配价：“留下”不带“我”作接受者，不能说“留下了我”。", "扔": "语义：“扔”是丢弃，与把蛋糕交给我的意思不合。", "切": "语义：“切”是分割，不表示把东西交给某人。"}, "sentence_index": 0, "correct_answer": "留给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙留给门口，等妈妈来拿。", "explanation": "这里应该用〈放在〉。“留给”的接受者必须是人，不能说留给“门口”。"}, {"text": "这份礼物是留给桌子的。", "explanation": "这里应该用〈摆〉，说“摆在桌子上”。“留给”的接受者必须是人，不能用于桌子这类物品的位置。"}, {"text": "这件外套是留给衣柜的。", "explanation": "这里应该用〈挂〉，说“挂在衣柜里”。“留给”的接受者必须是人，不能用于衣柜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留给", "is_correct": true, "explanation": "正确：“留给小狗”表示把苹果留着给小狗，与句意相符。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”是夺取，与把苹果给小狗的意思不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹住，不表示把东西交给别人。"}, {"text": "藏", "is_correct": false, "explanation": "配价：“藏”不带“小狗”作接受者，不能说“藏给小狗”。"}], "explanations": {"留给": "正确：“留给小狗”表示把苹果留着给小狗，与句意相符。", "抢": "语义：“抢”是夺取，与把苹果给小狗的意思不合。", "咬": "语义：“咬”是用牙齿夹住，不表示把东西交给别人。", "藏": "配价：“藏”不带“小狗”作接受者，不能说“藏给小狗”。"}, "sentence_index": 6, "correct_answer": "留给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "碗里还留给一块饼干。", "explanation": "这里应该用〈剩〉。“留给”表示把东西先放着给某人，不表示剩余。"}, {"text": "我把书包留给书架上。", "explanation": "这里应该用〈放在〉。“留给”的接受者必须是人，不能说留给“书架”。"}, {"text": "我把钥匙留给教室，他明天来拿。", "explanation": "这里应该用〈留在〉，说“留在教室里”。“留给”的接受者必须是人，不能用于教室这类地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这盒饼干把留给妹妹。", "corrected_sentence": "我把这盒饼干留给妹妹。", "error_description": "多余的“把”：“把”字句只用一个“把”，“把”后接“这盒饼干”，之后直接说“留给妹妹”；这里多加一个“把”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这盒点心留给。", "corrected_sentence": "我把这盒点心留给爷爷。", "error_description": "漏掉接受者：“留给”后必须带接受者，说“留给爷爷”；这里只说“留给”，句子没有说完。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
