INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事物保留下来，交给某人。", "primary_collocate": null, "pronunciation": "liú gěi", "ipa": "ljoʊ˧˥ keɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷把这块手表留给了爸爸。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把房子留给了孙子。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有留给孩子很多钱。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书是奶奶留给我的。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走的时候留给我一封信。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲留给儿子的只有一句话。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老画家留给世界很多画。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店是爸爸留给我的。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把她的旧戒指留给了女儿。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把祖传的老书桌留给了我。", "target_word": "留给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留给了", "label": "体标"}, {"form": "留给过", "label": "体标"}], "register": "中性", "sense_fingerprint": "留给：把事物保留下来传给或交给某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留给", "is_correct": true, "explanation": "正确：“留给了爸爸”表示把手表留下来交给爸爸，与句意相符。"}, {"text": "留下", "is_correct": false, "explanation": "配价：“留下”不带“爸爸”作接受者，不能说“留下了爸爸”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与把手表交给爸爸的意思不合。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，不表示把东西交给某人，句子不通。"}], "explanations": {"留给": "正确：“留给了爸爸”表示把手表留下来交给爸爸，与句意相符。", "留下": "配价：“留下”不带“爸爸”作接受者，不能说“留下了爸爸”。", "扔": "语义：“扔”是丢弃，与把手表交给爸爸的意思不合。", "修": "语义：“修”是修理，不表示把东西交给某人，句子不通。"}, "sentence_index": 0, "correct_answer": "留给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "碗里还留给一块饼干。", "explanation": "这里应该用〈剩〉。“留给”表示把东西先放着给某人，不表示剩余。"}, {"text": "他把钥匙留给门口，等妈妈来拿。", "explanation": "这里应该用〈放在〉。“留给”的接受者必须是人，不能说留给“门口”。"}, {"text": "这份礼物是留给桌子的。", "explanation": "这里应该用〈摆在〉，说“摆在桌子上”。“留给”的接受者必须是人，不能用于桌子这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留给", "is_correct": true, "explanation": "正确：“留给世界很多画”表示把画留下来交给世界，与句意相符。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”是绘制，“画世界很多画”不合句意。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”不与“世界”构成接受关系，句子不通。"}, {"text": "拍", "is_correct": false, "explanation": "配价：“拍”不带“世界”作接受者，不能说“拍给世界”。"}], "explanations": {"留给": "正确：“留给世界很多画”表示把画留下来交给世界，与句意相符。", "画": "语义：“画”是绘制，“画世界很多画”不合句意。", "撕": "搭配：“撕”不与“世界”构成接受关系，句子不通。", "拍": "配价：“拍”不带“世界”作接受者，不能说“拍给世界”。"}, "sentence_index": 6, "correct_answer": "留给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把名字留给纸上。", "explanation": "这里应该用〈写〉，说“写在纸上”。“留给”的接受者必须是人，不能说留给“纸上”。"}, {"text": "他把衣服留给衣柜里。", "explanation": "这里应该用〈挂〉，说“挂在衣柜里”。“留给”的接受者必须是人，不能说留给“衣柜”。"}, {"text": "这本书是留给书架的。", "explanation": "这里应该用〈放在〉，说“放在书架上”。“留给”的接受者必须是人，不能用于书架这类地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把这条项链把留给了姐姐。", "corrected_sentence": "奶奶把这条项链留给了姐姐。", "error_description": "多余的“把”：“把”字句只用一个“把”，“把”后接“这条项链”，之后直接说“留给了姐姐”；这里多加一个“把”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他临走前把车钥匙留给着我。", "corrected_sentence": "他临走前把车钥匙留给了我。", "error_description": "体标错误：“留给”完成时要用“了”，说“留给了我”；这里用“着”表示持续，“留给着我”不通，应说“留给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
