INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "值得信赖；确实。", "primary_collocate": null, "pronunciation": "kě kào", "ipa": "kʰɤ˨˩˦ kʰɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "小王做事认真，是个可靠的人。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最可靠的朋友住在北京。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把孩子交给他，我很放心，他很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是按时来，大家都说他可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个可靠的人帮我看家。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息可靠吗？是谁告诉你的？", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据可靠消息，明天公司会放假。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话不可靠，别太相信他。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟年纪小，但是做事很可靠。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从可靠的人那里听到了这件事。", "target_word": "可靠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可靠", "label": "复合"}, {"form": "可靠性", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容人值得信赖，或消息确实、真实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab94bc6-c383-4ea4-8aec-1bb1428bc55b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：值得信赖，做事让人放心。"}, {"text": "可口", "is_correct": false, "explanation": "kǒu（第三声）与 kào（第四声）韵母与声调都不同（-ou 与 -ao），意思是好吃、合口味。"}, {"text": "可看", "is_correct": false, "explanation": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。"}, {"text": "可考", "is_correct": false, "explanation": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。"}], "explanations": {"可靠": "可靠：值得信赖，做事让人放心。", "可口": "kǒu（第三声）与 kào（第四声）韵母与声调都不同（-ou 与 -ao），意思是好吃、合口味。", "可看": "kàn（第四声）与 kào（第四声）韵母不同（-an 与 -ao），声调相同，意思是值得看。", "可考": "kǎo（第三声）与 kào（第四声）声调不同，意思是可以考证。"}, "sentence_index": null, "correct_answer": "可靠"}, "level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：值得信赖，做事让人放心，这里形容人的品行。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不认真，与“做事认真”矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”指不愿做事，与“做事认真”矛盾。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容空间或宽度，不能用来形容人的品性。"}], "explanations": {"可靠": "可靠：值得信赖，做事让人放心，这里形容人的品行。", "马虎": "语义：“马虎”指做事不认真，与“做事认真”矛盾。", "懒": "语义：“懒”指不愿做事，与“做事认真”矛盾。", "窄": "搭配：“窄”形容空间或宽度，不能用来形容人的品性。"}, "sentence_index": 0, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很可靠，每天跑步十公里。", "explanation": "这里应该用〈结实〉。可靠用于人的品行或消息的真实，形容身体强壮要说结实。"}, {"text": "他的房间很可靠，收拾得很整洁。", "explanation": "这里应该用〈整洁〉。可靠不用来形容房间的样子，房间干净利落要说整洁。"}, {"text": "他今天精神很可靠。", "explanation": "这里应该用〈好〉。可靠指人值得信赖，不用来描述精神状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可靠", "is_correct": true, "explanation": "可靠：确实、真实，这里形容消息值得相信。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境没有声音，不能修饰“消息”。"}, {"text": "香", "is_correct": false, "explanation": "语义：“香”形容气味或味道，不能用来修饰“消息”。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，不能用来说消息的真假。"}], "explanations": {"可靠": "可靠：确实、真实，这里形容消息值得相信。", "安静": "语义：“安静”形容环境没有声音，不能修饰“消息”。", "香": "语义：“香”形容气味或味道，不能用来修饰“消息”。", "慢": "语义：“慢”形容速度，不能用来说消息的真假。"}, "sentence_index": 6, "correct_answer": "可靠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很可靠，我每天都听。", "explanation": "这里应该用〈好听〉。可靠用于事物能依靠、不出错，形容歌的好听要说好听。"}, {"text": "他跑得很可靠，一下子就到了。", "explanation": "这里应该用〈快〉。可靠不用来形容跑步的速度，跑得快要说快。"}, {"text": "这块蛋糕很可靠，大家都吃光了。", "explanation": "这里应该用〈甜〉。可靠不用来形容味道，蛋糕味道甜要说甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是可靠的完成任务。", "corrected_sentence": "他总是可靠地完成任务。", "error_description": "错误：“可靠”修饰动词“完成”时要用“地”，不能用“的”。正确形式是“可靠地完成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
