INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他盯着窗外的雨，一直没说话着。", "corrected_sentence": "他盯着窗外的雨，一直没说话。", "error_description": "体标错误：句末多出“着”。“着”表示动作的持续，不能接在否定的“没说话”之后，应删去句末的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
