INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "程式是电脑里一步一步照着做的命令。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "tʂʰɤŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他每天晚上都在电脑上写程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程式可以帮我算数学题。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑里有一个新程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写简单的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程式出了问题，电脑打不开了。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在公司设计手机程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个程式关掉，电脑太慢了。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程式很好用，你也下载一个吧。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学过三个月，已经会写小程式了。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程式里有一个错误，电脑不能运行。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个程式", "label": "量词：个"}, {"form": "一套程式", "label": "量词：套"}, {"form": "程式设计", "label": "复合词"}], "register": "中性", "sense_fingerprint": "电脑程式，按步骤执行的命令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确答案。程式是电脑里按步骤执行的命令。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实 chéngshí 与 chéngshì 只有第二个音节声调不同，意思是真实、不说谎。"}, {"text": "诚挚", "is_correct": false, "explanation": "诚挚 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是真诚恳切。"}, {"text": "尘世", "is_correct": false, "explanation": "尘世 chénshì 与 chéngshì 韵母不同（n 与 ng），意思是人间、世间。"}], "explanations": {"程式": "正确答案。程式是电脑里按步骤执行的命令。", "诚实": "诚实 chéngshí 与 chéngshì 只有第二个音节声调不同，意思是真实、不说谎。", "诚挚": "诚挚 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是真诚恳切。", "尘世": "尘世 chénshì 与 chéngshì 韵母不同（n 与 ng），意思是人间、世间。"}, "sentence_index": null, "correct_answer": "程式"}, "level_3": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确。“写程式”指编写电脑里的命令，符合句中的电脑语境。"}, {"text": "毛笔字", "is_correct": false, "explanation": "语义：毛笔字要用毛笔书写，不能在电脑上写。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法靠毛笔书写，与在电脑上写的语境不符。"}, {"text": "字帖", "is_correct": false, "explanation": "语义：字帖是供人临摹的范本，与在电脑上写东西的语境不符。"}], "explanations": {"程式": "正确。“写程式”指编写电脑里的命令，符合句中的电脑语境。", "毛笔字": "语义：毛笔字要用毛笔书写，不能在电脑上写。", "书法": "语义：书法靠毛笔书写，与在电脑上写的语境不符。", "字帖": "语义：字帖是供人临摹的范本，与在电脑上写东西的语境不符。"}, "sentence_index": 0, "correct_answer": "程式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只程式。", "explanation": "量词错误：“只”多用于动物或成对的东西，程式应该用“个”或“套”。"}, {"text": "他把程式吃进了肚子里。", "explanation": "用法错误：“吃”的对象应是食物，程式是电脑里的命令，不能吃。"}, {"text": "他的程式长得很高，比爸爸还高。", "explanation": "用法错误：“长高”只用于人和植物，程式没有身高，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93289, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确答案。程式是电脑里按步骤执行的命令。"}, {"text": "成熟", "is_correct": false, "explanation": "成熟 chéngshú 与 chéngshì 第二音节的韵母（ú 与 ì）和声调都不同，意思是发育完全。"}, {"text": "惩治", "is_correct": false, "explanation": "惩治 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是惩罚、治理。"}, {"text": "成日", "is_correct": false, "explanation": "成日 chéngrì 与 chéngshì 声母不同（r 与 sh），意思是整天。"}], "explanations": {"程式": "正确答案。程式是电脑里按步骤执行的命令。", "成熟": "成熟 chéngshú 与 chéngshì 第二音节的韵母（ú 与 ì）和声调都不同，意思是发育完全。", "惩治": "惩治 chéngzhì 与 chéngshì 声母不同（zh 与 sh），意思是惩罚、治理。", "成日": "成日 chéngrì 与 chéngshì 声母不同（r 与 sh），意思是整天。"}, "sentence_index": null, "correct_answer": "程式"}, "level_3": {"options": [{"text": "程式", "is_correct": true, "explanation": "正确。句中说电脑太慢，要关掉的是电脑里的程序，程式符合语境。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯与“电脑太慢”没有关系，关掉灯不能解决电脑慢的问题。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是调节温度用的，与电脑速度无关。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：关窗户与电脑太慢无关，句子前后不连贯。"}], "explanations": {"程式": "正确。句中说电脑太慢，要关掉的是电脑里的程序，程式符合语境。", "灯": "语义：灯与“电脑太慢”没有关系，关掉灯不能解决电脑慢的问题。", "空调": "语义：空调是调节温度用的，与电脑速度无关。", "窗户": "语义：关窗户与电脑太慢无关，句子前后不连贯。"}, "sentence_index": 6, "correct_answer": "程式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把程式种在花盆里。", "explanation": "用法错误：“种”的对象是植物，程式是命令，不能种。"}, {"text": "这个程式唱得很好听。", "explanation": "用法错误：“唱”的对象是歌曲，程式不能唱。"}, {"text": "他每天都用程式洗澡。", "explanation": "用法错误：“洗”的对象应是身体或衣物，程式不能用来洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
