INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定的格式或规程。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "tʂʰɤŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "办这件事要按照一定的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文章有固定的程式，写起来不难。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写信有一定的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事都有固定的程式，一点也不乱。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼的程式很复杂，大家要听司仪的。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "京剧的动作有固定的程式，演员要多年练习。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学习怎样写公文的程式。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话总是那一套程式，没有新意。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前有一套固定的程式，每个人都要做。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种公文有固定的程式，不能随便改。", "target_word": "程式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套程式", "label": "量词：套"}, {"form": "程式化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "固定的格式、规程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
