INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份公文有一套固定地程式。", "corrected_sentence": "这份公文有一套固定的程式。", "error_description": "结构助词错误：“固定”修饰名词“程式”，应用“的”，不能用“地”（“地”用于动词前）。应说“固定的程式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
