INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约同是约好几个人一起去。", "primary_collocate": null, "pronunciation": "yuē tóng", "ipa": "ɥe˥˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我想约同大家去划船。", "target_word": "约同", "complexity_tier": "T3", "furigana": "wǒ xiǎng yuē tóng dà jiā qù huá chuán", "sentence_source": "generated"}, {"text": "他约同三个同学去图书馆学习。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐约同朋友们去买衣服。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我约同几个人去看展览。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她约同同事去机场接客人。", "target_word": "约同", "complexity_tier": "T3", "furigana": "tā yuē tóng tóng shì qù jī chǎng jiē kè rén", "sentence_source": "generated"}, {"text": "王先生约同邻居们去山上走走。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经约同好几个朋友了。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想约同爸爸去钓鱼。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们约同老师去春游。", "target_word": "约同", "complexity_tier": "T3", "furigana": "tóng xué men yuē tóng lǎo shī qù chūn yóu", "sentence_source": "generated"}, {"text": "你要约同谁去旅行？", "target_word": "约同", "complexity_tier": "T3", "furigana": "nǐ yào yuē tóng shéi qù lǚ xíng", "sentence_source": "generated"}], "morphological_forms": [{"form": "约同了", "label": "体标"}, {"form": "约同过", "label": "体标"}], "register": "书面", "sense_fingerprint": "约好几个人一起去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae11fc9-8d91-4ac8-9ade-c3aa73eb42d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约同", "is_correct": true, "explanation": "正确：“约同”表示约好别人一起去，与“想”“大家”和“去划船”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能以“大家”为对象，也与“去划船”不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象应是物品，不能说“修理大家”。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出错误，与“想……去划船”的愿望不合。"}], "explanations": {"约同": "正确：“约同”表示约好别人一起去，与“想”“大家”和“去划船”相合。", "打扫": "语义：“打扫”的对象是场所或物品，不能以“大家”为对象，也与“去划船”不合。", "修理": "搭配：“修理”的对象应是物品，不能说“修理大家”。", "批评": "语义：“批评”指指出错误，与“想……去划船”的愿望不合。"}, "sentence_index": 0, "correct_answer": "约同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我约同那幅画去看展览。", "explanation": "这里应该用〈带〉。〈约同〉的对象只能是能一起行动的人，“画”不能被邀约，只能说把画带去看展览。"}, {"text": "老师约同学生不要迟到。", "explanation": "这里应该用〈警告〉。〈约同〉表示邀约别人一同做，老师要学生守时是告诫，不能说“约同学生不要迟到”。"}, {"text": "明天我约同自己去看展览。", "explanation": "这里应该用〈一个人〉。〈约同〉的对象必须是别人，说话人自己去应说“一个人去”，不能说“约同自己”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约同", "is_correct": true, "explanation": "正确：“约同”表示约好别人一起去，与“已经”“好几个朋友”和“了”相合。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象应是物件，不能说“搬好几个朋友”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭物体表面，不能以人为对象。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物品，与“朋友”不相容，句子不成立。"}], "explanations": {"约同": "正确：“约同”表示约好别人一起去，与“已经”“好几个朋友”和“了”相合。", "搬": "搭配：“搬”的对象应是物件，不能说“搬好几个朋友”。", "擦": "语义：“擦”指擦拭物体表面，不能以人为对象。", "挂": "语义：“挂”指悬挂物品，与“朋友”不相容，句子不成立。"}, "sentence_index": 6, "correct_answer": "约同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司要约同谁去出差？", "explanation": "这里应该用〈派〉。约同表示平等的邀约，公司安排员工出差是指派，不能用“约同”。"}, {"text": "你要约同谁去打喷嚏？", "explanation": "这里应该用〈打球〉。〈约同〉要接可以共同去做的自主行为，“打喷嚏”是不由自主发生的，不能邀约别人一同去做。"}, {"text": "你要约同谁去长高？", "explanation": "这里应该用〈锻炼〉。〈约同〉要接可以共同去做的自主行为，“长高”是身体自然生长，不能邀约别人一同去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想约同着两个同学去爬山。", "corrected_sentence": "我想约同两个同学去爬山。", "error_description": "“约同”后多加了“着”，“着”表示持续状态，与“想”表示的意愿不合。应去掉“着”，说“约同两个同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你约同在朋友们去看电影。", "corrected_sentence": "你约同了朋友们去看电影。", "error_description": "“在”不能夹在动词“约同”和宾语“朋友们”之间，应删去“在”并改用“了”表示动作已完成：应为“你约同了朋友们去看电影。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
