INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "邀约（别人）一同（做某事）。", "primary_collocate": null, "pronunciation": "yuē tóng", "ipa": "ɥe˥˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他约同几个朋友去爬山。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师约同班里几个学生去参观博物馆。", "target_word": "约同", "complexity_tier": "T3", "furigana": "lǎo shī yuē tóng bān lǐ jǐ gè xué shēng qù cān guān bó wù guǎn", "sentence_source": "generated"}, {"text": "她约同邻居去公园跑步。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我约同两位同事吃饭。", "target_word": "约同", "complexity_tier": "T3", "furigana": "wǒ yuē tóng liǎng wèi tóng shì chī fàn", "sentence_source": "generated"}, {"text": "周末他约同家人去海边玩。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王约同大家明天去看电影。", "target_word": "约同", "complexity_tier": "T3", "furigana": "xiǎo wáng yuē tóng dà jiā míng tiān qù kàn diàn yǐng", "sentence_source": "generated"}, {"text": "经理约同客户去工厂看看。", "target_word": "约同", "complexity_tier": "T3", "furigana": "jīng lǐ yuē tóng kè hù qù gōng chǎng kàn kan", "sentence_source": "generated"}, {"text": "他们约同了几个人去旅行。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张老师约同我去参加比赛。", "target_word": "约同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾约同朋友去唱歌。", "target_word": "约同", "complexity_tier": "T3", "furigana": "tā céng yuē tóng péng you qù chàng gē", "sentence_source": "generated"}], "morphological_forms": [{"form": "约同了", "label": "体标"}, {"form": "约同过", "label": "体标"}], "register": "书面", "sense_fingerprint": "邀约别人一同做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae11fc9-8d91-4ac8-9ade-c3aa73eb42d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约同", "is_correct": true, "explanation": "正确：“约同”表示邀约别人一同去做，与“几个朋友”和“去爬山”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能以“几个朋友”为对象，也不表示邀约。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出缺点或错误，与“去爬山”的邀约意思无关。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象应是物品或设备，不能说“修理几个朋友”。"}], "explanations": {"约同": "正确：“约同”表示邀约别人一同去做，与“几个朋友”和“去爬山”相合。", "打扫": "语义：“打扫”的对象是场所或物品，不能以“几个朋友”为对象，也不表示邀约。", "批评": "语义：“批评”指指出缺点或错误，与“去爬山”的邀约意思无关。", "修理": "搭配：“修理”的对象应是物品或设备，不能说“修理几个朋友”。"}, "sentence_index": 0, "correct_answer": "约同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我约同自己去吃饭。", "explanation": "这里应该用〈独自〉。〈约同〉指邀约别人一同做，说话人自己一个人去要说“独自”，不能说“约同自己”。"}, {"text": "我约同那两棵树去公园。", "explanation": "这里应该用〈搬〉。〈约同〉只能用于能自己行动、一起去的人，树不能被邀约，只能说把树搬去公园。"}, {"text": "班主任约同全班明天考试。", "explanation": "这里应该用〈通知〉。“约同”是邀约别人一同做，班主任只是告知全班考试时间，不是邀大家一起去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约同", "is_correct": true, "explanation": "正确：“约同”表示邀约别人一同去，“客户”和“去工厂看看”都与之相合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象应是场所或展品，不能直接以“客户”为宾语。"}, {"text": "押", "is_correct": false, "explanation": "语义：“押”指押送或扣押，与“去工厂看看”的友好来访语境不合。"}, {"text": "盯", "is_correct": false, "explanation": "语义：“盯”指注视，不能带“去工厂看看”这样的邀约内容。"}], "explanations": {"约同": "正确：“约同”表示邀约别人一同去，“客户”和“去工厂看看”都与之相合。", "参观": "搭配：“参观”的对象应是场所或展品，不能直接以“客户”为宾语。", "押": "语义：“押”指押送或扣押，与“去工厂看看”的友好来访语境不合。", "盯": "语义：“盯”指注视，不能带“去工厂看看”这样的邀约内容。"}, "sentence_index": 6, "correct_answer": "约同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她约同朋友下雨。", "explanation": "这里应该用〈散步〉。〈约同〉要接人可以共同完成的自主行为，“下雨”是天气现象，人不能被邀约去下。"}, {"text": "老师约同学生写检讨。", "explanation": "这里应该用〈罚〉。〈约同〉表示平等地邀约别人一同做，老师对学生的处罚是命令，不能用“约同”。"}, {"text": "她约同朋友去昏倒。", "explanation": "这里应该用〈爬山〉。〈约同〉要接人可以共同去做的自主行为，“昏倒”是不由自主发生的，不能邀约别人一同去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很约同了两个同学去看书。", "corrected_sentence": "他约同了两个同学去看书。", "error_description": "“很”一般修饰形容词，不能直接修饰动作动词“约同”，应删去。正确说法：他约同了两个同学去看书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她约同了两个同事了去喝咖啡。", "corrected_sentence": "她约同了两个同事去喝咖啡。", "error_description": "“了”只用一次，紧跟“约同”之后表示完成；宾语“两个同事”后又加“了”是多余的。正确说法：她约同了两个同事去喝咖啡。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451c901-7c79-413a-b179-a22aa1e6098f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
