INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "统治者是管着一个国家的人，大家要听他的。", "primary_collocate": null, "pronunciation": "tǒng zhì zhě", "ipa": "tʰʊŋ˨˩˦ ʈʂɨ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "古代的统治者住在很大的宫殿里。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的统治者很年轻。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都得听统治者的话。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的统治者会让老百姓过上好日子。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位统治者每天都要看很多信。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统治者说的话，大家不敢不听。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一位古代统治者的故事。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家换了新的统治者。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统治者为什么要收那么多税？", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当统治者，让全国的人都听他的。", "target_word": "统治者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "统治者们", "label": "复数"}, {"form": "統治者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "统治者：管着一个国家、大家要听从的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "统治者", "is_correct": true, "explanation": "统治者指管着国家、大家要听他的人，放在「古代的___住在很大的宫殿里」中指古代的国君，语义和搭配都合适。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有宫殿可住，与「很大的宫殿」矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "配价：「住」要求有生命的施事，石头不能住在宫殿里。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是家用器具，不是能住在宫殿中的人，句子不通。"}], "explanations": {"统治者": "统治者指管着国家、大家要听他的人，放在「古代的___住在很大的宫殿里」中指古代的国君，语义和搭配都合适。", "乞丐": "语义：乞丐没有宫殿可住，与「很大的宫殿」矛盾。", "石头": "配价：「住」要求有生命的施事，石头不能住在宫殿里。", "台灯": "语义：台灯是家用器具，不是能住在宫殿中的人，句子不通。"}, "sentence_index": 0, "correct_answer": "统治者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的统治者很有经验。", "explanation": "这里应该用〈管理者〉。统治者指掌握国家政权的人，公司的负责人应说「管理者」。"}, {"text": "我们班的统治者很负责。", "explanation": "这里应该用〈班长〉。统治者指掌握国家政权的人，班里的负责人一般说「班长」。"}, {"text": "这个路口的统治者很认真。", "explanation": "这里应该用〈警察〉。统治者指掌握国家政权的人，指挥路口交通的应说「警察」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统治者", "is_correct": true, "explanation": "统治者指掌握国家政权的人，「一位古代___的故事」中指古代的统治者，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词「位」只用于人，不能修饰「猫」。"}, {"text": "隧道", "is_correct": false, "explanation": "语义：隧道是交通通道，不是可以讲故事的对象，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有故事可讲，「讲了……的故事」不能用于窗户。"}], "explanations": {"统治者": "统治者指掌握国家政权的人，「一位古代___的故事」中指古代的统治者，符合句意。", "猫": "搭配：量词「位」只用于人，不能修饰「猫」。", "隧道": "语义：隧道是交通通道，不是可以讲故事的对象，句子不通。", "窗户": "语义：窗户没有故事可讲，「讲了……的故事」不能用于窗户。"}, "sentence_index": 6, "correct_answer": "统治者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台晚会的统治者很幽默。", "explanation": "这里应该用〈主持人〉。统治者指掌握国家政权的人，晚会的主持人不能称为统治者。"}, {"text": "这家小店的统治者很热情。", "explanation": "这里应该用〈店主〉。统治者指掌握国家政权的人，小店的老板应说「店主」。"}, {"text": "这位统治者做的菜很好吃。", "explanation": "这里应该用〈厨师〉。统治者指掌握国家政权的人，做菜的应说「厨师」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只统治者很关心老百姓。", "corrected_sentence": "这位统治者很关心老百姓。", "error_description": "「统治者」指人，量词应用「位」，这里把「这位」错成「这只」，「只」用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条统治者很有名。", "corrected_sentence": "那位统治者很有名。", "error_description": "「统治者」指人，应用量词「位」，这里把「位」错成「条」，「条」用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
