INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚焦是把眼睛或灯光集中在一个点上。", "primary_collocate": null, "pronunciation": "jù jiāo", "ipa": "tɕy˥˩ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "他的眼睛慢慢聚焦，看清了黑板上的字。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的灯光聚焦在歌手身上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把灯光聚焦在桌子中间。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机聚焦以后，照片就清楚了。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，眼睛很难聚焦。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师先聚焦，再按下快门。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，光就聚焦在小女孩的脸上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放大镜可以把阳光聚焦成一个小点。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机对着花聚焦了一下。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我盯着前面，眼睛要聚焦在一个点上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚焦了", "label": "体标：了"}, {"form": "聚焦着", "label": "体标：着"}, {"form": "聚焦过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "眼睛、镜头、灯光对准一个点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚焦", "is_correct": true, "explanation": "正确。“眼睛慢慢聚焦”指眼睛对准目标，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化是固体变为液体，不能用来形容眼睛。"}, {"text": "腌制", "is_correct": false, "explanation": "语义：腌制用于食物，与眼睛无关。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干用于潮湿的东西，眼睛不能被烘干。"}], "explanations": {"聚焦": "正确。“眼睛慢慢聚焦”指眼睛对准目标，符合句意。", "融化": "语义：融化是固体变为液体，不能用来形容眼睛。", "腌制": "语义：腌制用于食物，与眼睛无关。", "烘干": "语义：烘干用于潮湿的东西，眼睛不能被烘干。"}, "sentence_index": 0, "correct_answer": "聚焦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把牛奶聚焦在杯子里。", "explanation": "用法错误：牛奶是液体，“聚焦”不能用于液体。"}, {"text": "妈妈把衣服聚焦在床上。", "explanation": "语义错误：“聚焦”指集中光线或注意力，不是把衣服聚拢。"}, {"text": "这些树聚焦在山坡上。", "explanation": "用词错误：“聚焦”用于光线或注意力，树木的分布要用“集中”，不能用“聚焦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚焦", "is_correct": true, "explanation": "正确。“光就聚焦在小女孩的脸上”指光线集中在一处，符合句意。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：凝固指液体变成固体，光不会凝固。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵是食物或面团的变化，光不能发酵。"}, {"text": "堆积", "is_correct": false, "explanation": "搭配：“堆积”后接的是物品，光不能堆积在脸上。"}], "explanations": {"聚焦": "正确。“光就聚焦在小女孩的脸上”指光线集中在一处，符合句意。", "凝固": "语义：凝固指液体变成固体，光不会凝固。", "发酵": "语义：发酵是食物或面团的变化，光不能发酵。", "堆积": "搭配：“堆积”后接的是物品，光不能堆积在脸上。"}, "sentence_index": 6, "correct_answer": "聚焦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的脚聚焦在地上，走不动了。", "explanation": "主语错误：“聚焦”的主语是眼睛、镜头或光线，脚不能聚焦。"}, {"text": "他把碎玻璃聚焦在角落里。", "explanation": "用词错误：“聚焦”用于光线或注意力，碎玻璃的堆放要用“集中”或“堆放”，不能用“聚焦”。"}, {"text": "这首歌聚焦了一晚上。", "explanation": "语义错误：“聚焦”用于光线、镜头或注意力，不能用来说唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "舞台的灯光聚焦主持人身上。", "corrected_sentence": "舞台的灯光聚焦在主持人身上。", "error_description": "搭配错误：“聚焦”后接处所要用“在……身上”结构，漏掉“在”是错误，应说“聚焦在主持人身上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相机聚焦了在远处的小鸟上。", "corrected_sentence": "相机聚焦在远处的小鸟上。", "error_description": "体标与结构错误：“聚焦”后接“在……上”的结构中不能插入“了”，去掉“了”才通顺，应说“聚焦在远处的小鸟上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
