INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使注意力集中于某个问题或对象上。", "primary_collocate": null, "pronunciation": "jù jiāo", "ipa": "tɕy˥˩ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "这次会议聚焦环境问题。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的报道聚焦在那位老人身上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的目光都聚焦在新来的老师身上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书聚焦孩子的成长问题。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该把注意力聚焦在学习上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影聚焦普通人的生活。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家聚焦今天的重点。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片慢慢聚焦到一个山村的变化上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的提问聚焦在课文的中心思想上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的讨论聚焦在交通问题上。", "target_word": "聚焦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚焦了", "label": "体标：了"}, {"form": "聚焦着", "label": "体标：着"}, {"form": "聚焦过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "把注意力集中到某个问题或话题上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚焦", "is_correct": true, "explanation": "正确。“聚焦”表示把注意力集中在某个问题上，符合句意。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：粉刷的对象是墙面，不能用于会议和问题。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：喂养的对象是动物或人，不能用于环境问题。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割是收庄稼，与会议讨论环境无关。"}], "explanations": {"聚焦": "正确。“聚焦”表示把注意力集中在某个问题上，符合句意。", "粉刷": "语义：粉刷的对象是墙面，不能用于会议和问题。", "喂养": "语义：喂养的对象是动物或人，不能用于环境问题。", "收割": "语义：收割是收庄稼，与会议讨论环境无关。"}, "sentence_index": 0, "correct_answer": "聚焦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他聚焦了一杯牛奶。", "explanation": "用法错误：“聚焦”用于光线或注意力，液体不能聚焦。"}, {"text": "我把书聚焦起来放进了箱子里。", "explanation": "语义错误：“聚焦”不是把东西聚拢，把书聚在一起不能用“聚焦”。"}, {"text": "这些房子聚焦在城市中心。", "explanation": "用词错误：“聚焦”用于光线或注意力，房屋的分布要用“集中”，不能用“聚焦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚焦", "is_correct": true, "explanation": "正确。“聚焦”表示把注意力集中在重点上，符合句意。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：清洗需要有具体的对象，重点不能清洗。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不接“重点”。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张装在一起，不能用于重点。"}], "explanations": {"聚焦": "正确。“聚焦”表示把注意力集中在重点上，符合句意。", "清洗": "语义：清洗需要有具体的对象，重点不能清洗。", "喂": "搭配：“喂”的对象是人或动物，不接“重点”。", "装订": "语义：装订是把纸张装在一起，不能用于重点。"}, "sentence_index": 6, "correct_answer": "聚焦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天聚焦了一下午的电视。", "explanation": "用法错误：“聚焦”不是看电视的意思，看电视要说“看”。"}, {"text": "孩子们聚焦在操场上踢球。", "explanation": "用法错误：“聚焦”指光线或注意力集中，不能用来描述踢球这种行动。"}, {"text": "他聚焦了一个很长的假期。", "explanation": "用法错误：假期不能被聚焦，这里应说“过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的会议聚焦经济问题上。", "corrected_sentence": "今天的会议聚焦在经济问题上。", "error_description": "搭配错误：“聚焦”后接处所要用“在……上”结构，应说“聚焦在经济问题上”，漏掉“在”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师请大家聚焦了在今天的重点上。", "corrected_sentence": "老师请大家聚焦在今天的重点上。", "error_description": "体标错误：“聚焦”后接“在……上”的结构中不能插入“了”，去掉“了”才通顺，应说“聚焦在今天的重点上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
