INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听书是不用看，用耳朵听别人念书。", "primary_collocate": null, "pronunciation": "tīng shū", "ipa": "tʰiŋ˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "奶奶眼睛不好，她每天晚上都听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我喜欢躺在床上听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候不能看书，我就听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在地上，安静地听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给我们念故事，我们都爱听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听书不用看字，只用耳朵听。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眼睛累了，所以闭上眼睛听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在公园里听书，听得很高兴。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听书的时候，我常常喝着茶。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去图书馆听书，不想看书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听过书", "label": "体标"}, {"form": "听着书", "label": "体标"}, {"form": "聽書", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用耳朵听别人念书，不用眼睛看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指不用眼睛看，用耳朵听别人念书，与“奶奶眼睛不好”的语境相符。"}, {"text": "看书", "is_correct": false, "explanation": "语义：前句说“奶奶眼睛不好”，看书需要用眼睛，与句意矛盾。"}, {"text": "开车", "is_correct": false, "explanation": "语义：眼睛不好的人不能开车，“每天晚上都开车”与句中的身体状况矛盾。"}, {"text": "看报", "is_correct": false, "explanation": "语义：眼睛不好的人不能看报，“每天晚上都看报”与句中的身体状况矛盾。"}], "explanations": {"听书": "正确。听书指不用眼睛看，用耳朵听别人念书，与“奶奶眼睛不好”的语境相符。", "看书": "语义：前句说“奶奶眼睛不好”，看书需要用眼睛，与句意矛盾。", "开车": "语义：眼睛不好的人不能开车，“每天晚上都开车”与句中的身体状况矛盾。", "看报": "语义：眼睛不好的人不能看报，“每天晚上都看报”与句中的身体状况矛盾。"}, "sentence_index": 0, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我睡前一个人听书，眼睛一直盯着书页。", "explanation": "这里应该用〈看书〉。听书是用耳朵听别人念，不用眼睛看书页；“眼睛一直盯着书页”说的是看书。"}, {"text": "他戴着眼镜，低头用红笔在书上圈出生字，这就是听书。", "explanation": "这里应该用〈读书〉。听书是不用眼睛看、只用耳朵听的；圈生字要对着书上的字看，这是读书。"}, {"text": "他坐在窗前听书，眼睛一行一行地扫过纸面。", "explanation": "这里应该用〈阅读〉。听书不用眼睛看字；“眼睛一行一行地扫过纸面”描述的是阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指用耳朵听别人念书，与“闭上眼睛”的语境相符。"}, {"text": "上网", "is_correct": false, "explanation": "语义：闭着眼睛无法上网，与“闭上眼睛”矛盾。"}, {"text": "看电视", "is_correct": false, "explanation": "语义：闭着眼睛无法看电视，与“闭上眼睛”矛盾。"}, {"text": "读报", "is_correct": false, "explanation": "语义：闭着眼睛无法读报，与“闭上眼睛”矛盾。"}], "explanations": {"听书": "正确。听书指用耳朵听别人念书，与“闭上眼睛”的语境相符。", "上网": "语义：闭着眼睛无法上网，与“闭上眼睛”矛盾。", "看电视": "语义：闭着眼睛无法看电视，与“闭上眼睛”矛盾。", "读报": "语义：闭着眼睛无法读报，与“闭上眼睛”矛盾。"}, "sentence_index": 6, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不想看字，就自己大声朗读，这也算听书。", "explanation": "这里的〈听书〉被用成了“自己出声念书”的意思。听书是用耳朵听别人念书，自己出声读出来不是听书。"}, {"text": "他把课文一个字一个字地抄在本子上，这就叫听书。", "explanation": "这里应该用〈抄写〉。抄写是照着字写下来，与听书不是一回事。"}, {"text": "他闭着眼睛把课文背出来，这就叫听书。", "explanation": "这里应该用〈背诵〉。背诵是靠记忆说出内容，不是用耳朵听别人念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天听书听很开心。", "corrected_sentence": "我昨天听书听得很开心。", "error_description": "错误：“听书听很开心”。正确：“听书听得很开心”。动词“听”和后面的补语“很开心”之间要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天听书了两个小时。", "corrected_sentence": "我昨天听书听了两个小时。", "error_description": "错误：“听书了两个小时”。正确：“听书听了两个小时”。动词“听”带时段补语时要重复动词，“了”放在第二个“听”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
