INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听人讲述或播放朗读的书籍内容。", "primary_collocate": null, "pronunciation": "tīng shū", "ipa": "tʰiŋ˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "我每天坐地铁的时候听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班路上用耳机听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听书，你能帮我找一本好听的吗？", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭的时候总是听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很有意思，我昨天晚上听书听到很晚。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友推荐我听书，说比看书轻松。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步的时候听书，时间过得特别快。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听书的时候，主播的声音很好听，我一听就喜欢。", "target_word": "听书", "complexity_tier": "T3", "furigana": "tīng shū", "sentence_source": "generated"}, {"text": "他在车上打开手机，开始听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢睡前听书。", "target_word": "听书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听过书", "label": "体标"}, {"form": "听着书", "label": "体标"}, {"form": "聽書", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用手机或耳机播放朗读的书籍内容来听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指用手机或耳机播放朗读的内容来听，与“坐地铁”的语境相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：坐地铁的时候不能开车，与句中的情境矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐地铁的时候不能游泳，与句中的情境矛盾。"}, {"text": "看电台", "is_correct": false, "explanation": "搭配：电台要用“听”，不说“看电台”。"}], "explanations": {"听书": "正确。听书指用手机或耳机播放朗读的内容来听，与“坐地铁”的语境相符。", "开车": "语义：坐地铁的时候不能开车，与句中的情境矛盾。", "游泳": "语义：坐地铁的时候不能游泳，与句中的情境矛盾。", "看电台": "搭配：电台要用“听”，不说“看电台”。"}, "sentence_index": 0, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他低头在电脑前把书的内容一句句打进去，这就是听书。", "explanation": "这里应该用〈录入〉。听书是听人念或播放的朗读，把文字一句句打进电脑是录入，不是听书。"}, {"text": "我用打印机听书，纸上的字很清楚。", "explanation": "这里应该用〈印书〉。听书是播放声音，不会在纸上印出字。"}, {"text": "我不用耳机，自己对着手机大声朗读，这也算听书。", "explanation": "这里的〈听书〉被用成了“自己出声念书”的意思。听书是听别人或录好的朗读，自己出声念不是听书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听书", "is_correct": true, "explanation": "正确。听书指用耳机听播放的朗读，与“跑步”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：跑步的时候不能睡觉，与句中的动作矛盾。"}, {"text": "骑车", "is_correct": false, "explanation": "语义：跑步和骑车不能同时进行，句中的情境不合。"}, {"text": "看广播", "is_correct": false, "explanation": "搭配：广播要用“听”，不说“看广播”。"}], "explanations": {"听书": "正确。听书指用耳机听播放的朗读，与“跑步”的语境相符。", "睡觉": "语义：跑步的时候不能睡觉，与句中的动作矛盾。", "骑车": "语义：跑步和骑车不能同时进行，句中的情境不合。", "看广播": "搭配：广播要用“听”，不说“看广播”。"}, "sentence_index": 6, "correct_answer": "听书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把自己的声音录下来，这就是听书。", "explanation": "这里应该用〈录音〉。听书是听已经录好的朗读，录下自己的声音不叫听书。"}, {"text": "他闭着眼睛把课文背出来，这就叫听书。", "explanation": "这里应该用〈背诵〉。背诵是靠记忆说出内容，不是用耳朵听别人念。"}, {"text": "他把书一页页抄下来，这就叫听书。", "explanation": "这里应该用〈抄书〉。抄书要照着书上的字写，不是听书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周用手机听书听很开心。", "corrected_sentence": "我上周用手机听书听得很开心。", "error_description": "错误：“听书听很开心”。正确：“听书听得很开心”。动词“听”和后面的补语“很开心”之间要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨晚用手机听书了一个小时。", "corrected_sentence": "我昨晚用手机听书听了一个小时。", "error_description": "错误：“听书了一个小时”。正确：“听书听了一个小时”。动词“听”带时段补语时要重复动词，“了”放在第二个“听”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖是一对反义词，指身上的肉少。"}, {"text": "高", "is_correct": false, "explanation": "高说身高，与胖没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢说速度，与胖没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快说速度，与胖没有反义关系。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖是一对反义词，指身上的肉少。", "高": "高说身高，与胖没有反义关系。", "慢": "慢说速度，与胖没有反义关系。", "快": "快说速度，与胖没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "瘦", "is_correct": true, "explanation": "正确答案：瘦与胖是一对反义词，指身上的肉少。"}, {"text": "矮", "is_correct": false, "explanation": "矮说身高，与胖没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻是重的反义词，说分量，不是胖的反义词。"}, {"text": "软", "is_correct": false, "explanation": "软说质地，与胖没有反义关系。"}], "correct_answer": "瘦", "explanations": {"瘦": "正确答案：瘦与胖是一对反义词，指身上的肉少。", "矮": "矮说身高，与胖没有反义关系。", "轻": "轻是重的反义词，说分量，不是胖的反义词。", "软": "软说质地，与胖没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "胖是身上的肉多，看起来圆圆的。", "primary_collocate": null, "pronunciation": "pàng", "ipa": "pʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他的脸圆圆的，看起来很胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟小时候很胖，现在很瘦。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小了，我穿着显得很胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃得太多，最近胖了不少。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我太胖，要多运动。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又高又胖，走路很慢。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个胖老师笑着走进教室。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一点儿都不胖，不用减肥。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕太胖，晚上不吃米饭。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆圆的脸，圆圆的肚子，他真胖。", "target_word": "胖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "胖胖的", "label": "重叠"}, {"form": "胖子", "label": "复合"}, {"form": "发胖", "label": "复合"}], "register": "中性", "sense_fingerprint": "胖：人身上肉多、外形圆圆的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖（pàng），身上肉多。"}, {"text": "旁", "is_correct": false, "explanation": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 pàng 声母不同（f 与 p），意思是放置。"}, {"text": "盼", "is_correct": false, "explanation": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。"}, {"text": "棒", "is_correct": false, "explanation": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}], "explanations": {"胖": "正确答案：胖（pàng），身上肉多。", "旁": "páng（第二声）与 pàng（第四声）声调不同，意思是旁边。", "放": "fàng 与 pàng 声母不同（f 与 p），意思是放置。", "盼": "pàn 与 pàng 韵尾不同（n 与 ng），意思是期盼。", "棒": "bàng 与 pàng 声母不同（b 与 p，不送气与送气），意思是棒子。"}, "sentence_index": null, "correct_answer": "胖"}, "level_3": {"options": [{"text": "胖", "is_correct": true, "explanation": "正确答案：胖指身上肉多，与“圆圆的脸”的描写相合。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，不能用来描写脸的样子。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度或节奏，与描写外貌的“圆圆的脸”不搭。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“看起来很远”不能用来描写外貌，“远”说的是距离。"}], "explanations": {"胖": "正确答案：胖指身上肉多，与“圆圆的脸”的描写相合。", "快": "语义：“快”说速度，不能用来描写脸的样子。", "慢": "语义：“慢”说速度或节奏，与描写外貌的“圆圆的脸”不搭。", "远": "搭配：“看起来很远”不能用来描写外貌，“远”说的是距离。"}, "sentence_index": 0, "correct_answer": "胖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地很胖，能种很多菜。", "explanation": "这里应该用〈肥〉。胖用于人或动物的身体，说土地肥沃要用肥。"}, {"text": "这块木头很胖，用锯子锯不开。", "explanation": "这里应该用〈硬〉。胖用于人或动物的身体，木头的软硬要用硬。"}, {"text": "这个房间很胖，可以放下两张床。", "explanation": "这里应该用〈宽〉。胖不用于空间，房间的宽窄要用宽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_v