INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "货物是车和船运来运去的东西。比如大箱子里装的东西。", "primary_collocate": null, "pronunciation": "huò wù", "ipa": "xuɔ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "大船上装着很多货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把货物运到了港口。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在往车上搬货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货物都放在大箱子里。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上的货物要三天才能到。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物太重，一个人搬不动。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船靠岸后，人们开始卸货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆大车里全是货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆满了货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物到了，请你在这里签字。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货物", "label": "量词"}, {"form": "货物清单", "label": "复合"}, {"form": "貨物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车船运送的东西，如箱子里装的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab94bc6-c383-4ea4-8aec-1bb1428bc55b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“大船上装着很多货物”，货物是船上装运的东西。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能装在船上。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是能装上船的东西。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“装着”的宾语应是可以装进船里的实物，时间装不上。"}], "explanations": {"货物": "正确：“大船上装着很多货物”，货物是船上装运的东西。", "天空": "语义：天空不能装在船上。", "河流": "语义：河流不是能装上船的东西。", "时间": "搭配：“装着”的宾语应是可以装进船里的实物，时间装不上。"}, "sentence_index": 0, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都用货物洗脸。", "explanation": "这里应该用〈肥皂〉。货物是供运输、买卖的东西，洗脸用的东西要说肥皂。"}, {"text": "船上装了一只货物。", "explanation": "这里量词用错。“只”不能用来数货物；货物可以说“一件货物”或“一批货物”，这里应改为〈件〉或〈批〉。"}, {"text": "妈妈把新买的货物穿上了。", "explanation": "这里应该用〈衣服〉。货物不能穿在身上，穿的东西要说衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“卸货物”指把船上运来的东西卸下来，与“船靠岸后”相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“卸”要搭配可以装卸的货物，空气不能卸。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是可以卸下来的东西。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以卸下来的东西。"}], "explanations": {"货物": "正确：“卸货物”指把船上运来的东西卸下来，与“船靠岸后”相符。", "空气": "搭配：“卸”要搭配可以装卸的货物，空气不能卸。", "声音": "语义：声音不是可以卸下来的东西。", "颜色": "语义：颜色不是可以卸下来的东西。"}, "sentence_index": 6, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都在读货物。", "explanation": "这里应该用〈报纸〉。货物不是可以阅读的东西，读的东西要说报纸。"}, {"text": "我们晚上吃了很多货物。", "explanation": "这里应该用〈食物〉。货物不能用来吃，吃的东西要说食物。"}, {"text": "孩子们在玩货物。", "explanation": "这里应该用〈玩具〉。货物是供买卖的物品，孩子玩的东西要说玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车上装了一辆货物。", "corrected_sentence": "卡车上装了一车货物。", "error_description": "错误：“一辆货物”，量词“辆”只用于车辆，不能用来数货物；正确：“一车货物”。装满货物的车可以用“车”作量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们货物搬上了卡车。", "corrected_sentence": "工人们把货物搬上了卡车。", "error_description": "错误：漏掉了介词“把”。“搬”字句中，处置对象“货物”前要加“把”，正确形式是“把货物搬上了卡车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供运输、买卖的物品。", "primary_collocate": null, "pronunciation": "huò wù", "ipa": "xuɔ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "这批货物明天要卖到国外。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的货物又多又便宜。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在检查新到的货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货物卖得很快，已经不多了。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做生意，每天都要买卖货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把货物的价格写在纸上。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门卖进口货物。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物的质量好，客人才会再来。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用车运货物到城里去卖。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物卖完了，商店今天关门。", "target_word": "货物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批货物", "label": "量词"}, {"form": "货物清单", "label": "复合"}, {"form": "貨物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来运输、买卖的物品，商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab94bc6-c383-4ea4-8aec-1bb1428bc55b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“这批货物”指供买卖的物品，可以卖到国外。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不能当作商品卖到国外。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“这批”用于可以成批计量的物品，天气不能这样计量或买卖。"}, {"text": "岁月", "is_correct": false, "explanation": "语义：岁月是时间，不是可以买卖的东西。"}], "explanations": {"货物": "正确：“这批货物”指供买卖的物品，可以卖到国外。", "乘客": "语义：乘客是人，不能当作商品卖到国外。", "天气": "搭配：“这批”用于可以成批计量的物品，天气不能这样计量或买卖。", "岁月": "语义：岁月是时间，不是可以买卖的东西。"}, "sentence_index": 0, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用货物刷牙。", "explanation": "这里应该用〈牙刷〉。货物是供运输、买卖的物品，刷牙用的东西要说牙刷。"}, {"text": "我买了一只货物。", "explanation": "这里量词用错。“只”不能用来数货物；货物可以说“一件货物”或“一批货物”，这里应改为〈件〉或〈批〉。"}, {"text": "我每天用货物写日记。", "explanation": "这里应该用〈钢笔〉。货物是供运输、买卖的东西，写字的工具要说钢笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": true, "explanation": "正确：“进口货物”指从国外买来再卖的物品，与“专门卖”相符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是人，不能进口，也不能当商品卖。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“进口”搭配可以买卖的物品，时间不能进口。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是商品，不能进口买卖。"}], "explanations": {"货物": "正确：“进口货物”指从国外买来再卖的物品，与“专门卖”相符。", "病人": "语义：病人是人，不能进口，也不能当商品卖。", "时间": "搭配：“进口”搭配可以买卖的物品，时间不能进口。", "名字": "语义：名字不是商品，不能进口买卖。"}, "sentence_index": 6, "correct_answer": "货物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们晚上吃了很多货物。", "explanation": "这里应该用〈食物〉。货物指供运输、买卖的东西，吃的东西要说食物。"}, {"text": "孩子们每天都在玩货物。", "explanation": "这里应该用〈玩具〉。货物是供买卖的物品，孩子玩的东西要说玩具。"}, {"text": "我每天都在读货物。", "explanation": "这里应该用〈书〉。货物不是可以阅读的东西，读的东西要说书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天公司收到了一个货物。", "corrected_sentence": "今天公司收到了一批货物。", "error_description": "错误：“一个货物”，量词用错；正确：“一批货物”。货物要成批计量，用量词“批”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把货物的卖完了。", "corrected_sentence": "我把货物卖完了。", "error_description": "错误：“货物的卖完了”，“的”不能加在处置对象“货物”后面，“把货物”后应直接接动词；正确：“把货物卖完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
