INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脾气是一个人高兴或生气时容易有的样子。", "primary_collocate": null, "pronunciation": "pí qi", "ipa": "pʰi˧˥ tɕʰi", "syllable_count": 2, "sentences": [{"text": "他今天心情不好，脾气很大。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿的脾气，高兴时唱歌，生气时不说话。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子累了就会发脾气。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脾气一上来，脸就红了。", "target_word": "脾气", "complexity_tier": "T3", "furigana": "tā pí qi yí shàng lái, liǎn jiù hóng le.", "sentence_source": "generated"}, {"text": "爸爸等了一个小时，脾气上来了。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿的时候，脾气特别不好。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别对我发脾气，我没做错。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的脾气来得快，去得也快。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈高兴的时候，脾气特别好。", "target_word": "脾气", "complexity_tier": "T3", "furigana": "mā ma gāo xìng de shí hou, pí qi tè bié hǎo.", "sentence_source": "generated"}, {"text": "天气太热，大家的脾气都大了。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发脾气", "label": "复合"}, {"form": "好脾气", "label": "复合"}, {"form": "坏脾气", "label": "复合"}], "register": "口语", "sense_fingerprint": "脾气：人一时高兴或生气的情绪表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脾气", "is_correct": true, "explanation": "正确：“脾气很大”指一时容易发怒，与“心情不好”相符。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“脸色”不与“很大”搭配，不说“脸色很大”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说体形，与“心情不好”的语境无关，句子前后不搭。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间很大”描述空间，与前面表示心情的分句没有关系。"}], "explanations": {"脾气": "正确：“脾气很大”指一时容易发怒，与“心情不好”相符。", "脸色": "搭配：“脸色”不与“很大”搭配，不说“脸色很大”。", "身材": "体貌：“身材”说体形，与“心情不好”的语境无关，句子前后不搭。", "房间": "语义：“房间很大”描述空间，与前面表示心情的分句没有关系。"}, "sentence_index": 0, "correct_answer": "脾气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的脾气很认真。", "explanation": "这里应该用〈态度〉。脾气指一时的情绪表现，描述对工作的认真程度要用态度。"}, {"text": "他听到好消息，脾气很高。", "explanation": "这里应该用〈心情〉，说“心情很好”。脾气不说“很高”。"}, {"text": "这几天的脾气很冷，下了很多雪。", "explanation": "这里应该用〈天气〉。脾气指一时的情绪表现，不能形容一段时间的冷暖和降雪，要说“天气很冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脾气", "is_correct": true, "explanation": "正确：“发脾气”表示生气时的情绪表现，与“别对我发”的语境相符。"}, {"text": "信号", "is_correct": false, "explanation": "语义：“信号”不表示怒气，“对我发信号”与“我没做错”的语境不合。"}, {"text": "传单", "is_correct": false, "explanation": "语义：“发传单”是散发纸张，与对人发泄怒气无关。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“发工资”是给人发钱，不说“对我发工资”。"}], "explanations": {"脾气": "正确：“发脾气”表示生气时的情绪表现，与“别对我发”的语境相符。", "信号": "语义：“信号”不表示怒气，“对我发信号”与“我没做错”的语境不合。", "传单": "语义：“发传单”是散发纸张，与对人发泄怒气无关。", "工资": "搭配：“发工资”是给人发钱，不说“对我发工资”。"}, "sentence_index": 6, "correct_answer": "脾气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一把脾气，谁都怕他。", "explanation": "量词错误：脾气不用“把”计量，应说“一股脾气”。"}, {"text": "这碗汤的脾气很咸。", "explanation": "这里应该用〈味道〉。脾气指一时的情绪表现，不能用来形容汤的咸淡，要说“味道很咸”。"}, {"text": "他的脾气很大，能举起石头。", "explanation": "这里应该用〈力气〉。脾气不表示身体力量，不能说“脾气大，能举起石头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一听这话，一条脾气就上来了。", "corrected_sentence": "他一听这话，一股脾气就上来了。", "error_description": "量词错误：“脾气”应用“股”计量，说“一股脾气”；这里用“条”不对，“条”不用于脾气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一生气就发起脾气去。", "corrected_sentence": "妈妈一生气就发起脾气来。", "error_description": "趋向补语错误：“发起……来”表示动作开始并持续，要用“来”；这里用“去”不对，说“发起脾气来”，不能说“发起脾气去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
