INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的性情；容易发怒的性格。", "primary_collocate": null, "pronunciation": "pí qi", "ipa": "pʰi˧˥ tɕʰi", "syllable_count": 2, "sentences": [{"text": "他是个好脾气的人，从不生气。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师脾气很好，学生都喜欢他。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脾气不好，说话很急。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷有点儿脾气，但心很好。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩脾气很倔，不肯听别人的话。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住了很多年，我知道他的脾气。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脾气很怪，朋友不多。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的脾气像火一样，一点就着。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板脾气坏，大家都不敢说话。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你得改改脾气，不然没有朋友。", "target_word": "脾气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发脾气", "label": "复合"}, {"form": "好脾气", "label": "复合"}, {"form": "坏脾气", "label": "复合"}], "register": "口语", "sense_fingerprint": "脾气：人的性情，尤指容易发怒的性格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1174ca66-1df4-46ea-a83f-6bba417a06d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脾气", "is_correct": true, "explanation": "正确：“好脾气”指性情温和、不易发怒，与“从不生气”相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说体形，不说性情，与“从不生气”没有对应关系。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：“胃口”指食欲，与一个人的性情无关。"}, {"text": "手艺", "is_correct": false, "explanation": "语义：“手艺”指技能，“好手艺的人”与“从不生气”不搭。"}], "explanations": {"脾气": "正确：“好脾气”指性情温和、不易发怒，与“从不生气”相符。", "身材": "体貌：“身材”说体形，不说性情，与“从不生气”没有对应关系。", "胃口": "语义：“胃口”指食欲，与一个人的性情无关。", "手艺": "语义：“手艺”指技能，“好手艺的人”与“从不生气”不搭。"}, "sentence_index": 0, "correct_answer": "脾气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很响亮，全班都听见了。", "explanation": "这里应该用〈声音〉。脾气指人的性情或发怒的样子，不能形容声音的响亮程度，要说“声音很响亮”。"}, {"text": "他听到好消息，脾气很高。", "explanation": "这里应该用〈情绪〉。脾气不用来形容高兴的心情，不能说“脾气很高”。"}, {"text": "他有一条脾气，谁都不敢惹他。", "explanation": "量词错误：脾气不用“条”计量，应说“一股脾气”或“一副好脾气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脾气", "is_correct": true, "explanation": "正确：“他脾气很怪”描述性情，与“朋友不多”前后相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说身体高矮，与“朋友不多”没有关系，句子不通。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹很怪”说书写，与性情和交友没有关系。"}, {"text": "鞋码", "is_correct": false, "explanation": "搭配：“鞋码”不能用“很怪”来形容，句子无法成立。"}], "explanations": {"脾气": "正确：“他脾气很怪”描述性情，与“朋友不多”前后相符。", "身高": "体貌：“身高”说身体高矮，与“朋友不多”没有关系，句子不通。", "字迹": "语义：“字迹很怪”说书写，与性情和交友没有关系。", "鞋码": "搭配：“鞋码”不能用“很怪”来形容，句子无法成立。"}, "sentence_index": 6, "correct_answer": "脾气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的脾气很贵。", "explanation": "这里应该用〈价钱〉。脾气指人的性情，不能用来形容衣服的价格，要说“价钱很贵”。"}, {"text": "他有一把脾气，谁都怕他。", "explanation": "量词错误：脾气不用“把”计量，应说“一股脾气”。"}, {"text": "这件衣服的脾气很红。", "explanation": "这里应该用〈颜色〉。脾气指人的性情，不能用来形容衣服的颜色，要说“颜色很红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只好脾气，从不跟人吵架。", "corrected_sentence": "他有一副好脾气，从不跟人吵架。", "error_description": "量词错误：“脾气”应用“副”计量，说“一副好脾气”；这里用“只”不对，“只”用于动物或成对、单个的物件，不用于脾气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2761d3ba-58f1-4d5f-8e55-f8cc77968be1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
