INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子他隐藏很好，没有人找到。", "corrected_sentence": "这个盒子他隐藏得很好，没有人找到。", "error_description": "“隐藏”后面表示程度要用“得”连接，应说“隐藏得很好”。去掉“得”后，“隐藏很好”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
