INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人或事物藏起来，不让别人发现。", "primary_collocate": null, "pronunciation": "yǐn cáng", "ipa": "in˨˩˦ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小偷隐藏在大树后面，没有人看见。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们隐藏在门后面，想吓爸爸一跳。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想隐藏自己的错误，不告诉老师。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着，隐藏了心里的难过。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现他隐藏在山里的小房子里。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫隐藏在草里，鸟没有发现它。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直隐藏着这个秘密，没有告诉朋友。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩捉迷藏时，我隐藏在大衣柜里。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用帽子隐藏自己的脸，不想让别人认出来。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别想隐藏事实，大家都已经知道了。", "target_word": "隐藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐藏了", "label": "体标：了"}, {"form": "隐藏着", "label": "体标：着"}, {"form": "隐藏过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "把人或事物藏起来，不让别人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐藏", "is_correct": true, "explanation": "正确。“隐藏”指把人藏起来，不让别人发现，与“在大树后面，没有人看见”相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”与“在大树后面”不搭配，句子不通。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”是写文章，与小偷躲藏的情景不合。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”是在教室学习，与“在大树后面”的情景矛盾。"}], "explanations": {"隐藏": "正确。“隐藏”指把人藏起来，不让别人发现，与“在大树后面，没有人看见”相符。", "洗澡": "搭配：“洗澡”与“在大树后面”不搭配，句子不通。", "写作": "语义：“写作”是写文章，与小偷躲藏的情景不合。", "上课": "语义：“上课”是在教室学习，与“在大树后面”的情景矛盾。"}, "sentence_index": 0, "correct_answer": "隐藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这幅新画隐藏给大家看。", "explanation": "这里应该用〈展示〉。“隐藏”是不让人看见，“给大家看”要用“展示”。"}, {"text": "他公开隐藏了自己的身份。", "explanation": "这里应该用〈透露〉。“隐藏”是不让别人知道，身份要让人知道时应说“透露”。"}, {"text": "他大声隐藏了那个秘密。", "explanation": "这里应该用〈公布〉。“隐藏”是不让别人知道，要把秘密说给大家听时应说“公布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐藏", "is_correct": true, "explanation": "正确。“隐藏”指不让别人知道，与“没有告诉朋友”相符。"}, {"text": "泄露", "is_correct": false, "explanation": "语义：“泄露”是让秘密传出去，与“没有告诉朋友”矛盾。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损的东西，不能与“秘密”搭配。"}, {"text": "宣扬", "is_correct": false, "explanation": "语义：“宣扬”是大力传播，与“没有告诉朋友”的句意相反。"}], "explanations": {"隐藏": "正确。“隐藏”指不让别人知道，与“没有告诉朋友”相符。", "泄露": "语义：“泄露”是让秘密传出去，与“没有告诉朋友”矛盾。", "修补": "搭配：“修补”用于破损的东西，不能与“秘密”搭配。", "宣扬": "语义：“宣扬”是大力传播，与“没有告诉朋友”的句意相反。"}, "sentence_index": 6, "correct_answer": "隐藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店把新款手机隐藏在柜台上。", "explanation": "这里应该用〈陈列〉。“隐藏”指不让人发现，放在柜台上供人挑选要说“陈列”。"}, {"text": "他把那个花瓶隐藏在窗台上。", "explanation": "这里应该用〈摆放〉。“隐藏”指藏起来不让别人发现，窗台上的花瓶要说“摆放”。"}, {"text": "学校把通知隐藏在校门口。", "explanation": "这里应该用〈张贴〉。“隐藏”与“校门口”人来人往的公开位置矛盾，通知要说“张贴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他悄悄隐藏大树后面，没有人发现。", "corrected_sentence": "他悄悄隐藏在大树后面，没有人发现。", "error_description": "“隐藏”后面引出地点时要加介词“在”，应说“隐藏在大树后面”。“隐藏”不能直接接地点名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直隐藏了着自己的小秘密。", "corrected_sentence": "她一直隐藏着自己的小秘密。", "error_description": "“着”表示状态持续，“隐藏”后面已经带了“着”，不能再加“了”。应说“一直隐藏着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
