INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用某种原料加工制成的产品。", "primary_collocate": null, "pronunciation": "zhì pǐn", "ipa": "tʂɻ̩⁵¹ pʰin²¹⁴", "syllable_count": 2, "sentences": [{"text": "豆腐和豆浆都是大豆制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的肉制品很新鲜。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属制品放在潮湿的地方会生锈。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橡胶制品用久了会变硬。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂用棉花加工各种棉制品。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢吃面制品，比如面条和饺子。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些银制品是用银子加工做成的。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买肉制品的时候要看生产日期。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批陶瓷制品要运到国外去。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在食品厂检查乳制品的质量。", "target_word": "制品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豆制品", "label": "复合"}, {"form": "肉制品", "label": "复合"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "制品：以某种原料加工而成的产品，如豆制品、肉制品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e6d86ab-0aec-443b-942c-15f3d782f1c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：用某种原料加工制成的产品，是本题的正确答案。"}, {"text": "纸品", "is_correct": false, "explanation": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。"}, {"text": "织品", "is_correct": false, "explanation": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。"}, {"text": "试品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“试品”指用于检验的样品。"}, {"text": "次品", "is_correct": false, "explanation": "cì 与 zhì 声母不同，“次品”指质量较差的产品。"}, {"text": "饰品", "is_correct": false, "explanation": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}], "explanations": {"制品": "制品：用某种原料加工制成的产品，是本题的正确答案。", "纸品": "zhǐ pǐn（第三声）与 zhì pǐn（第四声）声调不同，“纸品”指纸类产品。", "织品": "zhī pǐn（第一声）与 zhì pǐn（第四声）声调不同，“织品”指纺织品。", "试品": "shì 与 zhì 声母不同，“试品”指用于检验的样品。", "次品": "cì 与 zhì 声母不同，“次品”指质量较差的产品。", "饰品": "shì 与 zhì 声母不同，“饰品”指装饰用的物品。"}, "sentence_index": null, "correct_answer": "制品"}, "level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：用原料加工而成的产品，豆腐和豆浆正是由大豆加工成的。"}, {"text": "植株", "is_correct": false, "explanation": "语义：“植株”是植物本身，豆腐和豆浆不是植株。"}, {"text": "豆荚", "is_correct": false, "explanation": "语义：“豆荚”是大豆的果荚，豆腐和豆浆不是豆荚。"}, {"text": "豆田", "is_correct": false, "explanation": "搭配：“都是”后面不能接“豆田”这类地点名词。"}], "explanations": {"制品": "制品：用原料加工而成的产品，豆腐和豆浆正是由大豆加工成的。", "植株": "语义：“植株”是植物本身，豆腐和豆浆不是植株。", "豆荚": "语义：“豆荚”是大豆的果荚，豆腐和豆浆不是豆荚。", "豆田": "搭配：“都是”后面不能接“豆田”这类地点名词。"}, "sentence_index": 0, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大豆是做豆腐的制品。", "explanation": "这里应该用〈原料〉。大豆是加工前的东西，“制品”指加工后做成的成品。"}, {"text": "我买了一台制品。", "explanation": "这里应该用〈件〉。“台”用于机器等大型器械，不用于“制品”。"}, {"text": "这本小说是他的代表制品。", "explanation": "这里应该用〈作品〉。小说等文艺创作称作品，“制品”指用材料加工的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制品", "is_correct": true, "explanation": "制品：经加工做成的东西，与“加工做成”搭配。"}, {"text": "银子", "is_correct": false, "explanation": "语义：“银子”是原材料，不是经过加工做成的东西，与句子语境相反。"}, {"text": "银行", "is_correct": false, "explanation": "语义：“银行”是机构，不能用“加工做成”来说明。"}, {"text": "银矿", "is_correct": false, "explanation": "搭配：“银矿”是开采的地方，不能说被加工做成。"}], "explanations": {"制品": "制品：经加工做成的东西，与“加工做成”搭配。", "银子": "语义：“银子”是原材料，不是经过加工做成的东西，与句子语境相反。", "银行": "语义：“银行”是机构，不能用“加工做成”来说明。", "银矿": "搭配：“银矿”是开采的地方，不能说被加工做成。"}, "sentence_index": 6, "correct_answer": "制品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在田里种满了制品。", "explanation": "这里应该用〈庄稼〉。“制品”是加工做成的东西，不能种在田里，应说“庄稼”。"}, {"text": "这家工厂用制品加工汽油。", "explanation": "这里应该用〈原油〉。原油是加工前的原料，“制品”是加工后的产品，不能再拿来加工汽油。"}, {"text": "这条路的制品长十公里。", "explanation": "这里应该用〈长度〉。“制品”指用某种原料加工制成的产品，不能用来说明道路的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家厂生产了一只大豆制品。", "corrected_sentence": "这家厂生产了很多大豆制品。", "error_description": "量词错误：“很多”与“大豆制品”搭配，不能说“一只大豆制品”；“只”一般用于动物等，不用于制品，应说“很多大豆制品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只银制品已经包装好了。", "corrected_sentence": "这批银制品已经包装好了。", "error_description": "“银制品”成批包装，计量应说“这批银制品”，不能说“这只银制品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a74b59e-f7cd-47b0-82b1-32bc260f4af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把好朋友当外人）相反。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”只说心情，与“见外”无关。"}, {"text": "严肃", "is_correct": false, "explanation": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。"}, {"text": "懒惰", "is_correct": false, "explanation": "无反义关系：“懒惰”指不愿劳动，与“见外”的人际含义无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把好朋友当外人）相反。", "高兴": "无反义关系：“高兴”只说心情，与“见外”无关。", "严肃": "无反义关系：“严肃”描述态度庄重，与“见外”的客气程度不对应。", "懒惰": "无反义关系：“懒惰”指不愿劳动，与“见外”的人际含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。"}, {"text": "冷静", "is_correct": false, "explanation": "无反义关系：“冷静”指情绪平稳，与“见外”无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列有序，与“见外”无关。"}, {"text": "便宜", "is_correct": false, "explanation": "无反义关系：“便宜”指价格低，与“见外”无关。"}], "correct_answer": "亲近", "explanations": {"亲近": "正确：“亲近”指关系亲密、不拘礼节，与“见外”（把人当外人）相反。", "冷静": "无反义关系：“冷静”指情绪平稳，与“见外”无关。", "整齐": "无反义关系：“整齐”形容排列有序，与“见外”无关。", "便宜": "无反义关系：“便宜”指价格低，与“见外”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "见外是把好朋友当成外人，太客气。", "primary_collocate": null, "pronunciation": "jiàn wài", "ipa": "tɕjɛn˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "好朋友之间还说谢谢，太见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把你当家人，你怎么还这么见外？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃你一顿饭，不用跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对老朋友一点也不见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不肯让我帮忙，是不是跟我见外？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别见外，有事就给我打电话。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们这么熟了，你还见外什么？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是好姐妹，说话从不见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样分得清清楚楚，也太见外了吧。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有什么需要尽管说，千万别跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見外", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把好朋友当外人，太客气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“太见外了”指把好朋友当外人、过分客气，与句中“好朋友之间还说谢谢”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与“好朋友之间还说谢谢”的语境不符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”描述环境或状态，无法评价朋友之间的客气程度。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，与朋友间说谢谢的行为无关。"}], "explanations": {"见外": "正确：“太见外了”指把好朋友当外人、过分客气，与句中“好朋友之间还说谢谢”相符。", "热闹": "语义：“热闹”形容场面喧闹，与“好朋友之间还说谢谢”的语境不符。", "安静": "语义：“安静”描述环境或状态，无法评价朋友之间的客气程度。", "漂亮": "体貌：“漂亮”形容外貌，与朋友间说谢谢的行为无关。"}, "sentence_index": 0, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放假那天我出门见外，跟几个朋友聚聚。", "explanation": "这里应该用〈见面〉。见外指过分客气，不表示出门会面；与朋友相聚要用见面。"}, {"text": "他一进门就大大咧咧地翻我的冰箱，见外得很。", "explanation": "这里应该用〈放肆〉。见外是过分客气，与翻人家冰箱的放肆正相反。"}, {"text": "我们俩亲亲热热地抱在一起，真见外。", "explanation": "这里应该用〈亲热〉。见外表示把人当外人、过分客气，与拥抱时的亲热正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“你还见外什么”指对方不必再把我当外人，与“咱们这么熟了”相符。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体状况，与“咱们这么熟了”的人际语境无关。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”描述才智，无法放在“你还……什么”中表达人际态度。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多形容声音，不能用于“你还……什么”这一反问结构。"}], "explanations": {"见外": "正确：“你还见外什么”指对方不必再把我当外人，与“咱们这么熟了”相符。", "健康": "语义：“健康”说身体状况，与“咱们这么熟了”的人际语境无关。", "聪明": "语义：“聪明”描述才智，无法放在“你还……什么”中表达人际态度。", "清脆": "搭配：“清脆”多形容声音，不能用于“你还……什么”这一反问结构。"}, "sentence_index": 6, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩是老搭档，他见外地拍拍我的肩膀。", "explanation": "这里应该用〈亲近〉。见外表示把人当外人、过分客气，与拍肩的亲近正相反。"}, {"text": "孩子们见外地抢着玩具，谁也不肯让。", "explanation": "这里应该用〈不客气〉。见外是过分客气，与抢玩具的不客气正相反。"}, {"text": "一家人吃饭，他却见外地抢着盛汤。", "explanation": "这里应该用〈随便〉。见外是过分客气，与一家人吃饭时的随便正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个很见外人。", "corrected_sentence": "他是一个很见外的人。", "error_description": "错误：漏掉“的”。“见外”作定语修饰“人”时要加“的”，应说“很见外的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩这么熟，别很见外了。", "corrected_sentence": "我们俩这么熟，别太见外了。", "error_description": "错误：“很”。劝阻句中应用“太”（“别太见外了”），“很”不能用于“别”之后表示这一意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
