INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "把对方当作外人看待，过分客气。", "primary_collocate": null, "pronunciation": "jiàn wài", "ipa": "tɕjɛn˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "你帮过我很多次，我怎么会见外呢？", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都是自己人，你别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要给我钱，我说这样太见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来家里吃饭，还带那么多东西，真见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再客气，我就觉得你见外了。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是老同学，不用跟我见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话很直，从来不跟朋友见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你收下这点心意，别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在我家吧，千万别见外。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很见外，借支笔都说谢谢。", "target_word": "见外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見外", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把对方当外人，过分客气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e49e6890-ab2b-4fe2-b804-aada486c92c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“见外”指把对方当外人、过分客气，此句表示“我不会把你当外人”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与受人帮助后的反问语境无关。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“我怎么会清楚呢”不成立，“清楚”不能放在“会”之后表示这种反问。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”描述才智，与“你帮过我很多次”这一感激语境不相干。"}], "explanations": {"见外": "正确：“见外”指把对方当外人、过分客气，此句表示“我不会把你当外人”。", "热闹": "语义：“热闹”形容场面喧闹，与受人帮助后的反问语境无关。", "清楚": "搭配：“我怎么会清楚呢”不成立，“清楚”不能放在“会”之后表示这种反问。", "聪明": "语义：“聪明”描述才智，与“你帮过我很多次”这一感激语境不相干。"}, "sentence_index": 0, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我出门见外，和朋友去郊游。", "explanation": "这里应该用〈见面〉。见外指把对方当外人而过分客气，不表示出门会面；与朋友相聚要用见面。"}, {"text": "我们俩在一起从不分彼此，见外得很。", "explanation": "这里应该用〈亲密〉。见外是把对方当外人、过分客气，与“从不分彼此”的亲密正相反。"}, {"text": "他一进门就大摇大摆地翻我的冰箱，真见外。", "explanation": "这里应该用〈放肆〉。见外指过分客气，与未经允许就乱翻东西的放肆正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见外", "is_correct": true, "explanation": "正确：“从来不跟朋友见外”指从不把朋友当外人，与“很直”的说话风格相符。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“朋友”的关系矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述与朋友的相处方式。"}, {"text": "疯狂", "is_correct": false, "explanation": "语义：“疯狂”指失控的状态，与“从来不跟朋友……”的语境不搭。"}], "explanations": {"见外": "正确：“从来不跟朋友见外”指从不把朋友当外人，与“很直”的说话风格相符。", "陌生": "语义：“陌生”指彼此不熟悉，与“朋友”的关系矛盾。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述与朋友的相处方式。", "疯狂": "语义：“疯狂”指失控的状态，与“从来不跟朋友……”的语境不搭。"}, "sentence_index": 6, "correct_answer": "见外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见我就热情地拥抱我，真见外。", "explanation": "这里应该用〈热情〉。见外表示把人当外人、过分客气，与一见面就拥抱的热情正相反。"}, {"text": "周末在家，他见外地躺在沙发上看电视。", "explanation": "这里应该用〈随便〉。见外是过分客气，与躺在沙发上看电视的随便正相反。"}, {"text": "孩子们一见到糖果就抢，见外得很。", "explanation": "这里应该用〈不客气〉。见外指过分客气，与抢糖果时的不客气正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别把我见外。", "corrected_sentence": "别跟我见外。", "error_description": "错误：“把我”。“见外”不能用“把”引出宾语，这一搭配的固定格式是“跟+人+见外”，应改为“别跟我见外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别很见外，有事就说。", "corrected_sentence": "别太见外，有事就说。", "error_description": "错误：“很”。劝阻句中应用“太”（“别太见外”），“很”不能用于“别”之后表示这一意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3936e6d-6c30-4543-94f8-e02c93cae5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一点不是一点也不。说一点不累，就是不累。", "primary_collocate": null, "pronunciation": "yì diǎn bù", "ipa": "i˥˩ tiɛn˨˩˦ pu˥˩", "syllable_count": 3, "sentences": [{"text": "他一点不胖，你为什么说他胖？", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不饿，你们先吃吧。", "target_word": "一点不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子一点不怕生，见谁都说话。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里一点不热，开着空调呢。", "target_word": "一点不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语很好，说话一点不紧张。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服一点不小，我穿正合适。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不想去，因为太远了。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一点不着急，慢慢地吃早饭。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上一点不堵，我们很快就到了。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这个消息，她一点不高兴。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿不", "label": "儿化变体"}, {"form": "一點不", "label": "繁体"}], "register": "口语", "sense_fingerprint": "等于一点也不，后接形容词或心理动词表示完全不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语义：“非常胖”说他很胖，与后面“你为什么说他胖”的反问相矛盾。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”是书面用语，口语里不这样说；“甚胖”同样与反问的语境矛盾。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别胖”同样表示他很胖，与“你为什么说他胖”不协调。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不胖，与“你为什么说他胖”的反问相呼应，符合语境。"}], "explanations": {"非常": "语义：“非常胖”说他很胖，与后面“你为什么说他胖”的反问相矛盾。", "甚": "语域：“甚”是书面用语，口语里不这样说；“甚胖”同样与反问的语境矛盾。", "特别": "语义：“特别胖”同样表示他很胖，与“你为什么说他胖”不协调。", "一点不": "一点不：表示完全不胖，与“你为什么说他胖”的反问相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚跑完马拉松，腿软得站不住，一点不累。", "explanation": "这里应该用〈很〉（很累）。“一点不累”表示完全不累，与“腿软得站不住”所说的疲劳相矛盾。"}, {"text": "屋里暖气烧得很足，他却一点不热，脱掉了外套。", "explanation": "这里应该用〈有点〉（有点热）。“一点不热”表示完全不热，与“脱掉了外套”的动作相矛盾。"}, {"text": "我一点不困，所以打了一个大哈欠。", "explanation": "这里应该用〈挺〉（挺困的）。“一点不困”表示完全不困，与“打了一个大哈欠”所表现的困倦相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最", "is_correct": false, "explanation": "语义：“最想去”表示意愿最强，与后面“因为太远了”的不去理由相矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分想去”表示很想去，与“因为太远了”作为理由相矛盾。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”要与前面的转折相呼应，此句没有转折语境，“却想去”不通。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不想去，与“因为太远了”构成理由，语义连贯。"}], "explanations": {"最": "语义：“最想去”表示意愿最强，与后面“因为太远了”的不去理由相矛盾。", "十分": "语义：“十分想去”表示很想去，与“因为太远了”作为理由相矛盾。", "却": "搭配：“却”要与前面的转折相呼应，此句没有转折语境，“却想去”不通。", "一点不": "一点不：表示完全不想去，与“因为太远了”构成理由，语义连贯。"}, "sentence_index": 6, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一点不生气，把桌子拍得直响。", "explanation": "这里应该用〈非常〉（非常生气）。“一点不生气”表示完全不生气，与“把桌子拍得直响”所表现的怒气相矛盾。"}, {"text": "我一点不怕黑，吓得躲进了被子里。", "explanation": "这里应该用〈特别〉（特别怕黑）。“一点不怕黑”表示完全不怕，与“吓得躲进了被子里”的害怕相矛盾。"}, {"text": "屋里很冷，他却一点不冷，直打哆嗦。", "explanation": "这里应该用〈稍微〉（稍微有点冷）。“一点不冷”表示完全不冷，与“直打哆嗦”的反应相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学一点不不怕老师。", "corrected_sentence": "我们班的同学一点不怕老师。", "error_description": "“不”重复出现，形成双重否定，句意与原意相反。错误形式：一点不不怕；正确形式：一点不怕。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子一点不的晃，很稳。", "corrected_sentence": "这张桌子一点不晃，很稳。", "error_description": "“一点不”后面直接接形容词，中间不能加“的”。错误形式：一点不的晃；正确形式：一点不晃。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
