INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一点也不；完全不。用于加强否定语气。", "primary_collocate": null, "pronunciation": "yì diǎn bù", "ipa": "i˥˩ tiɛn˨˩˦ pu˥˩", "syllable_count": 3, "sentences": [{"text": "这道菜一点不辣，你放心吃。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点不累，还能再走一会儿。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲得太快，我一点不懂。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气很好，我一点不冷。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，这件事一点不难。", "target_word": "一点不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一点不生气，还笑着对我说话。", "target_word": "一点不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方一点不远，走十分钟就到。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天睡得很好，今天一点不困。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书一点不贵，才十块钱。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一点不怕黑，一个人在家很好。", "target_word": "一点不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点儿不", "label": "儿化变体"}, {"form": "一點不", "label": "繁体"}], "register": "口语", "sense_fingerprint": "放在形容词或动词前，完全否定，加强否定语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太", "is_correct": false, "explanation": "语义：“太辣”表示辣得过分，与后面的“你放心吃”相矛盾。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最辣”表示辣度居首，同样与“你放心吃”的语境不符。"}, {"text": "甚是", "is_correct": false, "explanation": "语域：“甚是”偏书面语，这句口语里不这样说；而且“甚是辣”仍与“你放心吃”矛盾。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不辣，与“你放心吃”相呼应，符合语境。"}], "explanations": {"太": "语义：“太辣”表示辣得过分，与后面的“你放心吃”相矛盾。", "最": "语义：“最辣”表示辣度居首，同样与“你放心吃”的语境不符。", "甚是": "语域：“甚是”偏书面语，这句口语里不这样说；而且“甚是辣”仍与“你放心吃”矛盾。", "一点不": "一点不：表示完全不辣，与“你放心吃”相呼应，符合语境。"}, "sentence_index": 0, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿极了，一点不想吃饭。", "explanation": "这里应该用〈很〉（很想吃饭）。“一点不”表示完全没有某种意愿，与“饿极了”的状态正相反。"}, {"text": "我的腿一点不疼，可是走起路来还是一瘸一拐的。", "explanation": "这里应该用〈有点〉（有点疼）。「一点不疼」表示完全不疼，与「一瘸一拐」所表现的疼痛相矛盾。"}, {"text": "我一点不喝酒，只喝了一小杯。", "explanation": "这里应该用〈很少〉（很少喝酒）。“一点不”表示完全不做某事，与“只喝了一小杯”的少量相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语义：“非常远”说明距离很远，与“走十分钟就到”矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分远”同样说明很远，与“走十分钟就到”不符。"}, {"text": "甚", "is_correct": false, "explanation": "语域：“甚”偏书面，口语里不用；“甚远”也与“走十分钟就到”矛盾。"}, {"text": "一点不", "is_correct": true, "explanation": "一点不：表示完全不远，与“走十分钟就到”相呼应，符合语境。"}], "explanations": {"非常": "语义：“非常远”说明距离很远，与“走十分钟就到”矛盾。", "十分": "语义：“十分远”同样说明很远，与“走十分钟就到”不符。", "甚": "语域：“甚”偏书面，口语里不用；“甚远”也与“走十分钟就到”矛盾。", "一点不": "一点不：表示完全不远，与“走十分钟就到”相呼应，符合语境。"}, "sentence_index": 6, "correct_answer": "一点不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她刚拿到第一名，一点不开心，笑个不停。", "explanation": "这里应该用〈非常〉（非常开心）。“一点不”表示完全没有某种感受，与“笑个不停”所表现的快乐相矛盾。"}, {"text": "这次考试他一点不紧张，手心全是汗。", "explanation": "这里应该用〈特别〉（特别紧张）。“一点不”表示完全不紧张，与“手心全是汗”所描述的紧张相矛盾。"}, {"text": "这个孩子一点不害怕，躲在妈妈身后直发抖。", "explanation": "这里应该用〈有些〉（有些害怕）。“一点不”表示完全不怕，与“躲在妈妈身后直发抖”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服很一点不贵。", "corrected_sentence": "这件衣服一点不贵。", "error_description": "“一点不”前面不能再加程度副词“很”。错误形式：很一点不贵；正确形式：一点不贵。“一点不”本身已表示完全否定，不能与“很”叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路一点不都陡。", "corrected_sentence": "这条路一点不陡。", "error_description": "语序错误：“一点不”是整体的否定副词，后面直接接形容词，不能再插入“都”。错误形式：一点不都陡；正确形式：一点不陡（或：一点都不陡）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连写是把字一个接一个，不停笔地写。", "primary_collocate": null, "pronunciation": "lián xiě", "ipa": "li̯ɛn˧˥ ɕi̯ɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他拿起笔，一口气连写了十个字。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手有点累，不能再连写了。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法老师说，这几个字要连写，中间不能停笔。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她连写了三页，才放下笔。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时间不够，我只好连写下去。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一行字太多，我中间停了几次，没法连写。", "target_word": "连写", "complexity_tier": "T3", "furigana": "lián xiě", "sentence_source": "generated"}, {"text": "他喜欢连写，写出来的字很流畅。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子连写五遍名字，写得很整齐。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这句话连写一遍。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在桌前，不停笔地连写。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连写了", "label": "体标"}, {"form": "连写过", "label": "体标"}, {"form": "連寫", "label": "繁体"}], "register": "通用", "sense_fingerprint": "字一个接一个，不停笔地接着写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连写", "is_correct": true, "explanation": "正确：“连写”表示接连不停地写，与“一口气……十个字”吻合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，写字不能说吃，句子语义不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，不能用于写字，句子不通。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是果实或花叶，不能说摘字。"}], "explanations": {"连写": "正确：“连写”表示接连不停地写，与“一口气……十个字”吻合。", "吃": "语义：“吃”指吞咽食物，写字不能说吃，句子语义不通。", "唱": "语义：“唱”指歌唱，不能用于写字，句子不通。", "摘": "搭配：“摘”的对象是果实或花叶，不能说摘字。"}, "sentence_index": 0, "correct_answer": "连写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根绳子连写起来，又长又结实。", "explanation": "这里应该用〈连接〉。连写的意思是接连不停地写，不指把绳子等物体接在一起。"}, {"text": "他把这幅画连写在墙上。", "explanation": "这里应该用〈挂〉。连写指接连不停地书写，不能用来挂东西。"}, {"text": "我们学校连写了一场运动会。", "explanation": "这里应该用〈举办〉。连写指接连不停地书写，组织运动会要用〈举办〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连写", "is_correct": true, "explanation": "正确：“连写”作“喜欢”的宾语，指接连不停地写，与“写出来的字很流畅”吻合。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指作画，与“写出来的字”不符，句子矛盾。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，不能与“写出来的字”搭配，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，与写字无关，句子不通。"}], "explanations": {"连写": "正确：“连写”作“喜欢”的宾语，指接连不停地写，与“写出来的字很流畅”吻合。", "画": "语义：“画”指作画，与“写出来的字”不符，句子矛盾。", "跑": "语义：“跑”指快速移动，不能与“写出来的字”搭配，句子不通。", "睡": "语义：“睡”指睡觉，与写字无关，句子不通。"}, "sentence_index": 6, "correct_answer": "连写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把碗连写了三遍。", "explanation": "这里应该用〈洗〉。连写指书写，不能用于洗碗；清洗餐具应用〈洗〉。"}, {"text": "师傅连写好了那台电脑。", "explanation": "这里应该用〈修理〉。连写指接连不停地书写，不能用于修理机器。"}, {"text": "他连写了三圈，还不累。", "explanation": "这里应该用〈跑〉。连写指书写，不能表示跑步的圈数；绕场跑步应用〈跑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她坐下来，把这首诗连写了一个。", "corrected_sentence": "她坐下来，把这首诗连写了一遍。", "error_description": "动量词错误。“连写”的次数应用“遍”，误用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他连写很快。", "corrected_sentence": "他连写得很快。", "error_description": "补语标记“得”漏写。“连写”后的程度补语应加“得”，应为“连写得很快”，误作“连写很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
