INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把几个字母或笔画连接起来书写。", "primary_collocate": null, "pronunciation": "lián xiě", "ipa": "li̯ɛn˧˥ ɕi̯ɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "写英文的时候，这两个字母可以连写。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们把这几个笔画连写。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写字很快，常常把几个字母连写。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英文草书里常把字母连写。", "target_word": "连写", "complexity_tier": "T3", "furigana": "lián xiě", "sentence_source": "generated"}, {"text": "这个字的两笔可以连写，不用抬笔。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩刚学英文，还不会连写字母。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，我把这三个字母连写成一个。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写名字的时候，他喜欢连写最后两个字母。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练习以后，我连写字母更顺手了。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两笔连写起来，看着更漂亮。", "target_word": "连写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连写了", "label": "体标"}, {"form": "连写过", "label": "体标"}, {"form": "連寫", "label": "繁体"}], "register": "通用", "sense_fingerprint": "把几个字母或笔画连成一体来写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连写", "is_correct": true, "explanation": "正确：“连写”指把字母连起来写，与“写英文的时候，这两个字母可以……”的语境吻合。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言内容，不能说翻译字母。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与书写字母无关，句子语义不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清除污物，字母不能被洗，句子语义不通。"}], "explanations": {"连写": "正确：“连写”指把字母连起来写，与“写英文的时候，这两个字母可以……”的语境吻合。", "翻译": "搭配：“翻译”的对象是语言内容，不能说翻译字母。", "唱": "语义：“唱”指歌唱，与书写字母无关，句子语义不通。", "洗": "语义：“洗”指用水清除污物，字母不能被洗，句子语义不通。"}, "sentence_index": 0, "correct_answer": "连写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根管子用接头连写起来。", "explanation": "这里应该用〈连接〉。连写的对象是字母或笔画，指书写时把它们连成一体；连接用于把两根管子等物体接在一起。"}, {"text": "他用线条连写了一幅画。", "explanation": "这里应该用〈绘制〉。连写只指把字母或笔画连成一体书写，不能用来画画；画图应用〈绘制〉。"}, {"text": "这种药要连写三天。", "explanation": "这里应该用〈连用〉。连写只指把字母或笔画连成一体书写，药物接连服用应用〈连用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连写", "is_correct": true, "explanation": "正确：“连写”与“把……连写成一个”搭配，指把字母连成一体。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指分割，与把字母连成一个的意思相反，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去，字母不能被擦成一个，句子语义不通。"}, {"text": "染", "is_correct": false, "explanation": "搭配：“染”的对象是颜色或织物，不能说把字母染成一个。"}], "explanations": {"连写": "正确：“连写”与“把……连写成一个”搭配，指把字母连成一体。", "切": "语义：“切”指分割，与把字母连成一个的意思相反，句子不通。", "擦": "语义：“擦”指抹去，字母不能被擦成一个，句子语义不通。", "染": "搭配：“染”的对象是颜色或织物，不能说把字母染成一个。"}, "sentence_index": 6, "correct_answer": "连写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个班级连写成了一个。", "explanation": "这里应该用〈合并〉。连写限于书写中把字母或笔画连成一体，班级不属于书写对象；两个班级并成一个应用〈合并〉。"}, {"text": "他用针线把布连写起来。", "explanation": "这里应该用〈缝〉。连写的对象是字母或笔画，布料要靠针线缝合，不能说连写。"}, {"text": "两个学生连写成了一个小组。", "explanation": "这里应该用〈组成〉。连写限于书写中把字母或笔画连成一体，人组成一个小组要用〈组成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把两个字母连写一起。", "corrected_sentence": "他把两个字母连写在一起。", "error_description": "“连写”后的介词“在”漏写。应为“连写在一起”（“在一起”表示连在一处），误作“连写一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们把这四个字母连写三个。", "corrected_sentence": "老师让我们把这四个字母连写三遍。", "error_description": "动量词错误。“连写”的次数应用“遍”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
