INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "醒来是睡着以后，睁开眼睛。", "primary_collocate": null, "pronunciation": "xǐng lái", "ipa": "ɕiŋ˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "今天早上我六点就醒来了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他醒来的时候，天还没有亮。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子醒来以后，先找妈妈。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我醒来看了看手机，已经八点了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她醒来以后，看见窗外有太阳。", "target_word": "醒来", "complexity_tier": "T3", "furigana": "xǐng lái", "sentence_source": "generated"}, {"text": "小猫醒来了，慢慢走到我身边。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上太累，我今早很晚才醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闹钟响了，可是他没有醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你醒来的时候，我已经做好早饭了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我醒来时，房间里很安静。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醒来了", "label": "体标"}, {"form": "醒来过", "label": "体标"}, {"form": "醒來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "睡着以后睁开眼睛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指睡着以后睁开眼睛，与“六点就”的起床语境相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：早上六点不会下课，与“今天早上”的时间矛盾。"}, {"text": "吃晚饭", "is_correct": false, "explanation": "语义：早上六点不吃晚饭，与“今天早上”的时间矛盾。"}, {"text": "醒悟", "is_correct": false, "explanation": "搭配：醒悟要说“醒悟过来”或指想明白道理，不说“六点就醒悟了”。"}], "explanations": {"醒来": "正确。醒来指睡着以后睁开眼睛，与“六点就”的起床语境相符。", "下课": "语义：早上六点不会下课，与“今天早上”的时间矛盾。", "吃晚饭": "语义：早上六点不吃晚饭，与“今天早上”的时间矛盾。", "醒悟": "搭配：醒悟要说“醒悟过来”或指想明白道理，不说“六点就醒悟了”。"}, "sentence_index": 0, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸醒来了妹妹，让她起床上学。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}, {"text": "我整夜醒来，一直没有合眼。", "explanation": "这里应该用〈醒着〉。醒来是从睡眠中醒过来，句中说整夜醒来又一直没有合眼，表示整夜保持清醒，与醒来的意思不符。"}, {"text": "我整晚没睡，一直醒来到天亮。", "explanation": "这里应该用〈清醒〉。醒来是一次性的动作，不能表示一直保持清醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指睡后醒过来，与“今早很晚才”的语境相符。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜指夜里不睡，与“今早”的时间矛盾。"}, {"text": "醒酒", "is_correct": false, "explanation": "搭配：醒酒要和喝酒搭配，句中没有喝酒的情况。"}, {"text": "上晚自习", "is_correct": false, "explanation": "语义：晚自习在晚上进行，不会发生在“今早”。"}], "explanations": {"醒来": "正确。醒来指睡后醒过来，与“今早很晚才”的语境相符。", "熬夜": "语义：熬夜指夜里不睡，与“今早”的时间矛盾。", "醒酒": "搭配：醒酒要和喝酒搭配，句中没有喝酒的情况。", "上晚自习": "语义：晚自习在晚上进行，不会发生在“今早”。"}, "sentence_index": 6, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他醒来了弟弟，两个人一起去上学。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}, {"text": "我醒来后一直沉睡，没有睁开眼睛。", "explanation": "这里的〈醒来〉被用成了“仍未醒过来”的意思。醒来表示已经醒过来、睁开眼睛，句中却说没有睁开眼睛，前后矛盾。"}, {"text": "他醒来后一直睡着，还在打呼噜。", "explanation": "这里的〈醒来〉被用成了“醒后仍在睡”的意思。醒来表示已经醒过来，句中又说一直在睡，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我醒来了时，天已经亮了。", "corrected_sentence": "我醒来时，天已经亮了。", "error_description": "错误：“醒来了时”。正确：“醒来时”。“了”不能夹在动词“醒来”和时间词“时”之间，应直接说“醒来时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被醒来后，先喝了一杯水。", "corrected_sentence": "她醒来后，先喝了一杯水。", "error_description": "错误：“被醒来后”。正确：“醒来后”。“醒来”是不及物动词，不能用“被”字句表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
