INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从睡眠中恢复知觉。", "primary_collocate": null, "pronunciation": "xǐng lái", "ipa": "ɕiŋ˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "他从梦中醒来，出了一身汗。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都睡着了，只有我半夜醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她睡了很久，终于醒来了。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人睡了一天一夜才醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常常在半夜醒来，然后睡不着。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车到站的时候，他才从睡梦中醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他醒来时，还不知道自己在哪儿。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的雷声让孩子突然醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人睡得很沉，叫了几次都没醒来。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她醒来后觉得头很疼。", "target_word": "醒来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醒来了", "label": "体标"}, {"form": "醒来过", "label": "体标"}, {"form": "醒來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "从睡眠或梦中恢复知觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指从梦中恢复知觉，与“从梦中”的语境相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与梦境无关，句子语义不通。"}, {"text": "醒悟", "is_correct": false, "explanation": "搭配：醒悟指想明白道理，不说“从梦中醒悟”。"}, {"text": "醒酒", "is_correct": false, "explanation": "语义：醒酒要因为喝了酒，句中没有喝酒的情况，与句意不合。"}], "explanations": {"醒来": "正确。醒来指从梦中恢复知觉，与“从梦中”的语境相符。", "吃饭": "语义：“吃饭”与梦境无关，句子语义不通。", "醒悟": "搭配：醒悟指想明白道理，不说“从梦中醒悟”。", "醒酒": "语义：醒酒要因为喝了酒，句中没有喝酒的情况，与句意不合。"}, "sentence_index": 0, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈醒来了孩子，让他去上学。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}, {"text": "他睡了一天一夜，醒来后一直睡着，没有醒过来。", "explanation": "这里的〈醒来〉被用成了“仍在睡梦中”的意思。醒来表示恢复知觉，句中却说一直昏睡、没有醒过来，前后矛盾。"}, {"text": "他很醒来，一直躺在床上没起床。", "explanation": "这里应该用〈醒着〉。醒来是瞬间变化，不能用“很”修饰；表示清醒的状态要说醒着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "醒来", "is_correct": true, "explanation": "正确。醒来指恢复知觉，与“还不知道自己在哪儿”的刚醒状态相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去工作，与“还不知道自己在哪儿”的刚醒状态不合。"}, {"text": "觉醒", "is_correct": false, "explanation": "语域：觉醒多指思想或意识的觉醒，描述刚醒来的状态时不用它。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭是清醒时的活动，与“还不知道自己在哪儿”的刚醒状态不合。"}], "explanations": {"醒来": "正确。醒来指恢复知觉，与“还不知道自己在哪儿”的刚醒状态相符。", "上班": "语义：“上班”指去工作，与“还不知道自己在哪儿”的刚醒状态不合。", "觉醒": "语域：觉醒多指思想或意识的觉醒，描述刚醒来的状态时不用它。", "吃饭": "语义：吃饭是清醒时的活动，与“还不知道自己在哪儿”的刚醒状态不合。"}, "sentence_index": 6, "correct_answer": "醒来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她醒来后仍然沉睡，觉得头很疼。", "explanation": "这里的〈醒来〉被用成了“仍未恢复知觉”的意思。醒来表示已经恢复知觉，句中却说仍在沉睡，前后矛盾。"}, {"text": "她看书看着看着，就醒来了，觉得头很疼。", "explanation": "这里应该用〈入睡〉。醒来表示睡后醒过来，不能表示睡着；句中“看着看着”的过程是睡着，应说入睡。"}, {"text": "她醒来了我，让我去开门。", "explanation": "这里应该用〈叫醒〉。醒来是不及物动词，不能带宾语表示使别人醒过来，应说叫醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被从梦中醒来，心里很害怕。", "corrected_sentence": "他从梦中醒来，心里很害怕。", "error_description": "错误：“被从梦中醒来”。正确：“从梦中醒来”。“醒来”是不及物动词，不能用“被”字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她睡了很久，把醒来后觉得很饿。", "corrected_sentence": "她睡了很久，醒来后觉得很饿。", "error_description": "错误：“把醒来后”。正确：“醒来后”。“醒来”是不及物动词，后面不能接“把”字结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
