INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开家到外面去；外出。", "primary_collocate": null, "pronunciation": "chū mén", "ipa": "ʈʂʰu˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶年纪大了，很少出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常在家，不太爱出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出门去买菜了，一会儿就回来。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出门工作，晚上才回家。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕冷，冬天几乎不出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪的时候，大家都不出门。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每次出门都要带很多东西。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张昨天出门办事，还没回来。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪路滑，出门要小心。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王今天不在，他出门了。", "target_word": "出门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了门", "label": "体标"}, {"form": "出过门", "label": "体标"}, {"form": "出门去", "label": "趋向"}], "register": "口语", "sense_fingerprint": "离开家到外面去，外出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab94bc6-c383-4ea4-8aec-1bb1428bc55b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「很少」搭配，表示少外出。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”与“奶奶年纪大了”不符，奶奶不需要上学。"}, {"text": "当兵", "is_correct": false, "explanation": "语义：“当兵”与奶奶的身份不符，句子语义不通。"}, {"text": "罢工", "is_correct": false, "explanation": "搭配：“罢工”的主语应是工作的人，不能用于“奶奶”。"}], "explanations": {"出门": "出门：离开家到外面去，与「很少」搭配，表示少外出。", "上学": "语义：“上学”与“奶奶年纪大了”不符，奶奶不需要上学。", "当兵": "语义：“当兵”与奶奶的身份不符，句子语义不通。", "罢工": "搭配：“罢工”的主语应是工作的人，不能用于“奶奶”。"}, "sentence_index": 0, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份包裹刚出门，就被退回来了。", "explanation": "这里应该用〈寄出〉。出门指人离开家到外面去，包裹寄出要用“寄出”，不能用“出门”。"}, {"text": "我下班后刚出门，妈妈就做好了饭。", "explanation": "这里应该用〈进门〉。出门是离开家，下班回家要用“进门”。"}, {"text": "这碗汤刚出门，就凉了。", "explanation": "这里应该用〈端出来〉。出门指人离开家到外面去，汤端出来要用“端出来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出门", "is_correct": true, "explanation": "出门：离开家到外面去，与「每次都要带很多东西」搭配。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”不是需要外出带很多东西的活动，与句意矛盾。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：做梦时不需要带很多东西，与句意矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时不需要带很多东西，与句意矛盾。"}], "explanations": {"出门": "出门：离开家到外面去，与「每次都要带很多东西」搭配。", "发烧": "语义：“发烧”不是需要外出带很多东西的活动，与句意矛盾。", "做梦": "语义：做梦时不需要带很多东西，与句意矛盾。", "睡觉": "语义：睡觉时不需要带很多东西，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "出门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一出门就回房睡觉了。", "explanation": "这里应该用〈回房〉。出门是离开家到外面去，回房睡觉要说“回房”，不能用“出门”。"}, {"text": "孩子放学就出门，躺在床上睡觉。", "explanation": "这里应该用〈在家〉。出门是离开家，躺在床上睡觉应在家里，要说“在家”。"}, {"text": "他整天出门，留在屋里看书。", "explanation": "这里应该用〈留在〉。出门是离开家到外面去，与“留在屋里”矛盾，应说“留在屋里看书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她过出门，去过很多国家。", "corrected_sentence": "她出过门，去过很多国家。", "error_description": "错误在于“过”的位置。应说“出过门”，“过”表示经历，放在“出”之后、“门”之前；“过出门”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出门了去，没有带钥匙。", "corrected_sentence": "他出门去了，没有带钥匙。", "error_description": "错误在于“了”与趋向补语“去”的顺序。应说“出门去了”，“去”紧接“出门”，“了”放在最后；“出门了去”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fff3e13-71dc-4d89-85cb-66db3873d673') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "正确：“关闭”与“开办”相对，指停止营业或使店铺、学校停止运作。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”是文娱活动，与“开办”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”指进食，与创立机构没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "无关：“看书”指阅读，与“开办”不构成反义。"}], "correct_answer": "关闭", "explanations": {"关闭": "正确：“关闭”与“开办”相对，指停止营业或使店铺、学校停止运作。", "跳舞": "无关：“跳舞”是文娱活动，与“开办”没有反义关系。", "吃饭": "无关：“吃饭”指进食，与创立机构没有反义关系。", "看书": "无关：“看书”指阅读，与“开办”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "正确：“关闭”与“开办”相对，指停止营业或使店铺停止运作。"}, {"text": "钓鱼", "is_correct": false, "explanation": "无关：“钓鱼”是休闲活动，与“开办”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清除污物，与创立机构没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“开办”不构成反义。"}], "correct_answer": "关闭", "explanations": {"关闭": "正确：“关闭”与“开办”相对，指停止营业或使店铺停止运作。", "钓鱼": "无关：“钓鱼”是休闲活动，与“开办”没有反义关系。", "打扫": "无关：“打扫”指清除污物，与创立机构没有反义关系。", "洗澡": "无关：“洗澡”指清洁身体，与“开办”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开办是新开一家学校或店，让它开始做事。", "primary_collocate": null, "pronunciation": "kāi bàn", "ipa": "kʰaɪ˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "我姐姐想开办一家花店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店是去年开办的。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开办了一所幼儿园。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学校下个月就要开办了。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开办一家小店不太容易。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人开办过一家面包店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的饭店刚开办，客人还不多。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存款开办了一家咖啡店。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生在城里开办一所音乐学校。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把开办小店的想法告诉了妈妈。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开办了", "label": "体标"}, {"form": "开办过", "label": "体标"}, {"form": "開辦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新开学校或店铺并使其开始运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指新开店铺并使其开始运作，与“我姐姐想……一家花店”吻合。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”指采下果实或花朵，不能用于开店，句子不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”的对象是动植物，不能说养一家花店。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，不能用于开一家店，句子语义不通。"}], "explanations": {"开办": "正确：“开办”指新开店铺并使其开始运作，与“我姐姐想……一家花店”吻合。", "摘": "语义：“摘”指采下果实或花朵，不能用于开店，句子不通。", "养": "搭配：“养”的对象是动植物，不能说养一家花店。", "煮": "语义：“煮”指烹饪，不能用于开一家店，句子语义不通。"}, "sentence_index": 0, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府开办了一个新基金。", "explanation": "这里应该用〈设立〉。开办指创办学校、店铺等机构，基金要用〈设立〉。"}, {"text": "我们开办了一次郊游。", "explanation": "这里应该用〈组织〉。开办用于创办机构，活动要用〈组织〉。"}, {"text": "剧组开办了一部电影。", "explanation": "这里应该用〈拍摄〉。开办用于创办机构，影片要用〈拍摄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指饭店刚刚开始经营，与“我们的饭店刚……，客人还不多”吻合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于饭店的经营状态，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带宾语，“刚送”后缺少对象，句子不完整。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”指说话，饭店不能“讲”，句子语义不通。"}], "explanations": {"开办": "正确：“开办”指饭店刚刚开始经营，与“我们的饭店刚……，客人还不多”吻合。", "吃": "语义：“吃”指进食，不能用于饭店的经营状态，句子不通。", "送": "配价：“送”需要带宾语，“刚送”后缺少对象，句子不完整。", "讲": "语义：“讲”指说话，饭店不能“讲”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生开办了电灯。", "explanation": "这里应该用〈发明〉。开办用于创办机构，电灯要用〈发明〉。"}, {"text": "这家出版社开办了很多书。", "explanation": "这里应该用〈出版〉。开办用于创办机构，书籍要用〈出版〉。"}, {"text": "农民开办了很多蔬菜。", "explanation": "这里应该用〈种植〉。开办用于创办机构，蔬菜要用〈种植〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹想把开办一家面馆。", "corrected_sentence": "我妹妹想开办一家面馆。", "error_description": "“把”字误用。“想”后直接接动词“开办”，不需要“把”，应删去“把”，改为“想开办一家面馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅在镇上开办了一只超市。", "corrected_sentence": "我舅舅在镇上开办了一家超市。", "error_description": "量词误用。超市应用量词“家”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
