INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93360, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创立并开始经营或举办（学校、企业等）。", "primary_collocate": null, "pronunciation": "kāi bàn", "ipa": "kʰaɪ˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "他想在老家开办一所小学。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司是三年前开办的。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师开办了一家画画学校。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府帮助农民开办小工厂。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后开办过一家小公司。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学是一百年前开办的。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算开办一个培训班教孩子英语。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开办了夜校，让大人也能学习。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开办一家饭店需要很多钱。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把开办新医院的计划告诉了大家。", "target_word": "开办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开办了", "label": "体标"}, {"form": "开办过", "label": "体标"}, {"form": "開辦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "创立并开始经营学校、企业等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4835ab79-f4e1-4482-a6ca-5e78ccd07271') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指创立并开始经营学校，与“在老家……一所小学”吻合。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指游水，不能用于创办学校，句子不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”的对象是动植物或子女，不能说养一所小学。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，学校不能被写出来，句子语义不通。"}], "explanations": {"开办": "正确：“开办”指创立并开始经营学校，与“在老家……一所小学”吻合。", "游": "语义：“游”指游水，不能用于创办学校，句子不通。", "养": "搭配：“养”的对象是动植物或子女，不能说养一所小学。", "写": "语义：“写”指书写，学校不能被写出来，句子语义不通。"}, "sentence_index": 0, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国开办了新的外交关系。", "explanation": "这里应该用〈建立〉。开办用于创办学校、企业等机构，外交关系要用〈建立〉。"}, {"text": "班主任开办了一份期末成绩单。", "explanation": "这里应该用〈制作〉。开办用于创办学校、企业等机构，成绩单要用〈制作〉。"}, {"text": "他们开办了一座新桥。", "explanation": "这里应该用〈修建〉。开办不用于建筑物，桥梁要用〈修建〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开办", "is_correct": true, "explanation": "正确：“开办”指创立培训班，与“打算……教孩子英语”吻合。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，不能用于创立培训班，句子语义不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是物品或设施，不能说修一个培训班。"}, {"text": "雇", "is_correct": false, "explanation": "搭配：“雇”的对象是人员，不能说雇一个培训班。"}], "explanations": {"开办": "正确：“开办”指创立培训班，与“打算……教孩子英语”吻合。", "删除": "语义：“删除”指去掉，不能用于创立培训班，句子语义不通。", "修": "搭配：“修”的对象是物品或设施，不能说修一个培训班。", "雇": "搭配：“雇”的对象是人员，不能说雇一个培训班。"}, "sentence_index": 6, "correct_answer": "开办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开办了一篇新论文。", "explanation": "这里应该用〈发表〉。开办用于创办机构，论文要用〈发表〉。"}, {"text": "公司开办了一款新产品。", "explanation": "这里应该用〈推出〉。开办指创办机构，产品要用〈推出〉。"}, {"text": "他开办了一首歌，在晚会上唱给大家听。", "explanation": "这里应该用〈创作〉。开办用于创办学校、企业等机构，歌曲要用〈创作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲在城里把开办了一家工厂。", "corrected_sentence": "我父亲在城里开办了一家工厂。", "error_description": "错误：“把”字误用。“把”后直接接动词“开办”，缺少把字宾语，应删去“把”，改为“我父亲在城里开办了一家工厂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐在城里开办了一只书店。", "corrected_sentence": "我姐姐在城里开办了一家书店。", "error_description": "量词误用。书店应用量词“家”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbd03526-a1bc-400f-ab2a-ad06bb6bdf94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
