INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93363, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "前此是在这件事以前。", "primary_collocate": null, "pronunciation": "qián cǐ", "ipa": "tɕʰjɛn˧˥ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他今天第一次上台，前此从没唱过歌。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们搬来这里已经三年，前此住在别的城市。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了第一名，前此没有人看好他。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书出版了，前此她写过很多文章。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此老师没有说过这件事，所以我们都很吃惊。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定从今天开始，前此大家可以随便进来。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年才开始学中文，前此一个字也不会。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此我只在书上见过大熊猫，今天终于看到了真的。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店上个月开门，前此这里是一个小公园。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天第一次开会，前此都是在网上说话。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指在这件事发生以前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确答案。前此读作 qián cǐ，意思是在这件事以前。"}, {"text": "前次", "is_correct": false, "explanation": "cì（第四声）与 cǐ（第三声）声调不同，前次的意思是上一次。"}, {"text": "千次", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，千次的意思是一千次。"}, {"text": "前齿", "is_correct": false, "explanation": "chǐ 与 cǐ 声母不同（ch 与 c），前齿的意思是前面的牙齿。"}], "explanations": {"前此": "正确答案。前此读作 qián cǐ，意思是在这件事以前。", "前次": "cì（第四声）与 cǐ（第三声）声调不同，前次的意思是上一次。", "千次": "qiān（第一声）与 qián（第二声）声调不同，千次的意思是一千次。", "前齿": "chǐ 与 cǐ 声母不同（ch 与 c），前齿的意思是前面的牙齿。"}, "sentence_index": null, "correct_answer": "前此"}, "level_3": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确。前此指在这件事以前，与“第一次上台”的首次经历相合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示一贯发生，与“第一次上台、从没唱过歌”的情况不合。"}, {"text": "老是", "is_correct": false, "explanation": "语域：“老是”是口语，与书面语的“前此”不符；又与“第一次”相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时发生，与“从没唱过歌”相矛盾。"}], "explanations": {"前此": "正确。前此指在这件事以前，与“第一次上台”的首次经历相合。", "总是": "语义：“总是”表示一贯发生，与“第一次上台、从没唱过歌”的情况不合。", "老是": "语域：“老是”是口语，与书面语的“前此”不符；又与“第一次”相矛盾。", "偶尔": "语义：“偶尔”表示有时发生，与“从没唱过歌”相矛盾。"}, "sentence_index": 0, "correct_answer": "前此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前此我要去北京工作。", "explanation": "这里应该用〈将来〉。前此指过去的时间，不能与表示打算的“要”去北京工作配合。"}, {"text": "前此他再也没有抽烟。", "explanation": "这里应该用〈从此〉。前此指此前，与“再也没有抽烟”所说的此后状态矛盾。"}, {"text": "前此请你把门关上。", "explanation": "这里应该用〈以后〉。前此指此前的时间，不能用来让对方将来去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确。前此表示在此以前，与“今年才开始学”的情况相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已经完成，与“今年才开始学”、一个字也不会的情况相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即将发生，与“一个字也不会”描述的现状不合。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”标记将来，与描述现状的“一个字也不会”不合。"}], "explanations": {"前此": "正确。前此表示在此以前，与“今年才开始学”的情况相合。", "已经": "语义：“已经”表示事情已经完成，与“今年才开始学”、一个字也不会的情况相矛盾。", "马上": "语义：“马上”指即将发生，与“一个字也不会”描述的现状不合。", "将": "体貌：“将”标记将来，与描述现状的“一个字也不会”不合。"}, "sentence_index": 6, "correct_answer": "前此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前此他明天就要去北京。", "explanation": "这里应该用〈随后〉。前此指此前的时间，不能与表示将来的“明天就要去北京”搭配。"}, {"text": "我们先吃饭，前此去公园。", "explanation": "这里应该用〈然后〉。前此指在此之前，而句子说的是吃饭之后去公园，顺序颠倒了。"}, {"text": "前此老师让我们明天交作业。", "explanation": "这里应该用〈以后〉。前此指此前的时间，不能与“明天交作业”这种将来的要求搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的前此没有唱过歌，今天是第一次上台。", "corrected_sentence": "他前此没有唱过歌，今天是第一次上台。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“他前此没有唱过歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的前此从没想过要学画画。", "corrected_sentence": "我前此从没想过要学画画。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“我前此从没想过要学画画。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
