INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在此以前；先前。多用于书面语。", "primary_collocate": null, "pronunciation": "qián cǐ", "ipa": "tɕʰjɛn˧˥ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "前此他从未来过这个城市。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此我们没有见过面。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此公司没有这样的规定。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此他一直住在乡下，去年才搬到北京。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此大家都不知道这件事。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此这里没有医院，现在有了。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此她很少说话，今天却说了很多。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此我对音乐没有兴趣。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此他从没迟到，这次是第一次。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前此学校没有游泳池，同学们只能去外面游泳。", "target_word": "前此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语副词，在此以前、先前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4949539b-d775-4702-b6ea-cac00b4ddf44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确答案。前此读作 qián cǐ，意思是在此以前、先前。"}, {"text": "前次", "is_correct": false, "explanation": "cì（第四声）与 cǐ（第三声）声调不同，前次的意思是上一次。"}, {"text": "千次", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，千次的意思是一千次。"}, {"text": "前齿", "is_correct": false, "explanation": "chǐ 与 cǐ 声母不同（ch 与 c），前齿的意思是前面的牙齿。"}], "explanations": {"前此": "正确答案。前此读作 qián cǐ，意思是在此以前、先前。", "前次": "cì（第四声）与 cǐ（第三声）声调不同，前次的意思是上一次。", "千次": "qiān（第一声）与 qián（第二声）声调不同，千次的意思是一千次。", "前齿": "chǐ 与 cǐ 声母不同（ch 与 c），前齿的意思是前面的牙齿。"}, "sentence_index": null, "correct_answer": "前此"}, "level_3": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确。前此指在此以前，与“从未来过”所叙述的过去经历相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“从未来过”所叙述的经历不合。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常发生，与“从未来过”相矛盾。"}, {"text": "老是", "is_correct": false, "explanation": "语域：“老是”是口语，与书面语的“前此”不同；又与“从未”相矛盾。"}], "explanations": {"前此": "正确。前此指在此以前，与“从未来过”所叙述的过去经历相合。", "忽然": "语义：“忽然”表示突然发生，与“从未来过”所叙述的经历不合。", "常常": "语义：“常常”表示经常发生，与“从未来过”相矛盾。", "老是": "语域：“老是”是口语，与书面语的“前此”不同；又与“从未”相矛盾。"}, "sentence_index": 0, "correct_answer": "前此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我决定前此每天锻炼身体。", "explanation": "这里应该用〈今后〉。前此指过去的时间，不能用来表示将来的打算。"}, {"text": "请你前此把作业交给老师。", "explanation": "这里应该用〈往后〉。前此指此前的时间，不能用来要求对方将来去做事。"}, {"text": "前此他明年会去北京。", "explanation": "这里应该用〈以后〉。前此指此前的时间，不能与表示将来的“明年会去北京”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前此", "is_correct": true, "explanation": "正确。前此表示在此以前，与“今天却说了很多”形成对比。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生不久，与“很少说话”所描述的长期习惯不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“很少说话”所说的一贯状态不合。"}, {"text": "压根", "is_correct": false, "explanation": "搭配：“压根”要与否定词连用，不能修饰“很少说话”。"}], "explanations": {"前此": "正确。前此表示在此以前，与“今天却说了很多”形成对比。", "刚刚": "语义：“刚刚”指刚发生不久，与“很少说话”所描述的长期习惯不合。", "立刻": "语义：“立刻”表示马上发生，与“很少说话”所说的一贯状态不合。", "压根": "搭配：“压根”要与否定词连用，不能修饰“很少说话”。"}, "sentence_index": 6, "correct_answer": "前此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前此他再也没有来过这个城市。", "explanation": "这里应该用〈此后〉。前此指在此之前，与“再也没有来过”所说的此后情况矛盾。"}, {"text": "前此我们明天去爬山。", "explanation": "这里应该用〈以后〉。前此指此前的时间，不能与“明天去爬山”这样的将来安排搭配。"}, {"text": "我们先吃饭，前此去公园。", "explanation": "这里应该用〈然后〉。前此指在此之前，而句子说的是吃饭之后去公园，顺序颠倒了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的前此没有听说过这件事。", "corrected_sentence": "他前此没有听说过这件事。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“他前此没有听说过这件事。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的前此很少在周末出门。", "corrected_sentence": "我们前此很少在周末出门。", "error_description": "“前此”是副词，前面不能加“的”。“的”应去掉，说“我们前此很少在周末出门。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69faa942-6f72-45b2-890f-648576f03b31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "劳动力是能干活的人，有力气去做事的人。", "primary_collocate": null, "pronunciation": "láo dòng lì", "ipa": "lɑʊ˧˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂需要很多劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的年轻劳动力都去城里工作了。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方缺少劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算招一些劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村里的劳动力不多。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多劳动力从农村来到大城市。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天农忙时，家里需要更多劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多年轻的劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板雇了十个劳动力来搬东西。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动力少，工作就做得慢。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "劳动力：能干活的人，指人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗人", "is_correct": false, "explanation": "语义：工厂需要的是能干活的人手，不需要很多诗人，与“工厂”的语境不合。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的人，工厂需要很多这样的人手，语义吻合。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”是植物的花，工厂不需要很多花朵，与语境不符。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“需要很多”后面的宾语应是可被需要的人或物，“季节”不能这样使用。"}], "explanations": {"诗人": "语义：工厂需要的是能干活的人手，不需要很多诗人，与“工厂”的语境不合。", "劳动力": "劳动力指能干活的人，工厂需要很多这样的人手，语义吻合。", "花朵": "语义：“花朵”是植物的花，工厂不需要很多花朵，与语境不符。", "季节": "搭配：“需要很多”后面的宾语应是可被需要的人或物，“季节”不能这样使用。"}, "sentence_index": 0, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位劳动力长得很漂亮。", "explanation": "这里应该用〈工人〉。“劳动力”指能干活的人或其劳动能力，不用来形容人的长相，说人漂亮时不用它。"}, {"text": "他是我的劳动力，我很爱他。", "explanation": "这里应该用〈亲人〉。“劳动力”指能干活的人或其劳动能力，不指家人，也不用来表达亲情。"}, {"text": "公司打算招一只劳动力。", "explanation": "这里的量词应改用〈名〉。“只”用于动物或成对器官中的一个，不用于指人的劳动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节日", "is_correct": false, "explanation": "搭配：“需要更多”的对象应是人手或物资，“节日”在农忙语境中不能这样使用。"}, {"text": "真理", "is_correct": false, "explanation": "语义：农忙时家里缺的是干活的人，“真理”与农活无关。"}, {"text": "劳动力", "is_correct": true, "explanation": "劳动力指能干活的人，农忙时家里需要的正是这种人手，语义通顺。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”是天体，农忙时家里并不需要它们，与语境不符。"}], "explanations": {"节日": "搭配：“需要更多”的对象应是人手或物资，“节日”在农忙语境中不能这样使用。", "真理": "语义：农忙时家里缺的是干活的人，“真理”与农活无关。", "劳动力": "劳动力指能干活的人，农忙时家里需要的正是这种人手，语义通顺。", "星星": "语义：“星星”是天体，农忙时家里并不需要它们，与语境不符。"}, "sentence_index": 6, "correct_answer": "劳动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "劳动力坏了，生产就停了。", "explanation": "这里应该用〈机器〉。“劳动力”指人，不能说“坏了”，会出故障的是机器。"}, {"text": "他是劳动力，唱得很好听。", "explanation": "这里应该用〈歌手〉。“劳动力”指能干活的人或其劳动能力，不指会唱歌的人。"}, {"text": "工厂今年招了一台劳动力。", "explanation": "这里应该用〈名〉或〈个〉。“台”用于机器等器械，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂今年要增加一根劳动力。", "corrected_sentence": "这家工厂今年要增加一批劳动力。", "error_description": "量词错误：“劳动力”（指人）前应用〈一批〉，“根”用于细长的东西，不能修饰劳动力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里来了一把劳动力。", "corrected_sentence": "城里来了一批劳动力。", "error_description": "量词错误：“劳动力”（指人）前应用〈一批〉，“把”用于有柄的器具，不能修饰人员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d43dc11-1112-41c2-9e7a-2c6b07b17dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
