INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人所具有的从事劳动的能力（指能力本身，不指人）。", "primary_collocate": null, "pronunciation": "láo dòng lì", "ipa": "lɑʊ˧˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "他生病以后，失去了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，没有劳动力了。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人还有一点劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤后，他丧失了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要还有劳动力，他就不会闲着。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场病让他部分丧失了劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手受伤了，暂时没有劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去劳动力的人可以得到帮助。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然很老，但是还有劳动力。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，有劳动力就要自己赚钱。", "target_word": "劳动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "劳动力：人所具有的劳动能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df811bf5-9274-44e9-838a-6aef24dd96b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
